// ==========================================
// ★ K 의 방 — B등급 직업 갈림길 · 연결
// 협상가 · 결속술사 · 견습 기사 · 신호수 · 표사
// 연결: 쫓기는 밤에 사람을 붙들고, 묶고, 앞에 서고, 부르고, 끝까지 데려간다 — 비 오는 밤, 시간이 없다
// ==========================================

// ──────────────────────────────────────────
// 협상가 (negotiator) · 자원 없음
// ──────────────────────────────────────────
kJob('negotiator', 'B', [

{ at:'B', t:'처마 밑 — 같이 숨은 사람',
  x:`비가 처마 끝에서 줄이 되어 떨어진다. 처마 밑은 두 사람 몫이다. 이미 한 사람이 있다.<br><br>
    골목 끝에서 손전등 빛이 바닥을 훑는다. 이쪽으로 온다.<br>
    먼저 와 있던 사람이 속삭인다. 조용히 있어 주는 값을 부른다. 말린 고기 두 점.<br><br>
    협상가는 안다. 침묵에 값을 매기는 사람은 그 침묵을 두 번 판다.`,
  o:[
    { l:'① 한 점은 지금, 한 점은 빛이 지나간 뒤에 주겠다고 한다.', k:'bond', dc:20,
      ok:`한 점을 내밀었다. 남은 한 점은 빛이 지나간 다음이라고 했다.<br><br>그 사람 눈이 고기와 손전등 사이를 오간다. 지금 이쪽을 팔면 한 점이다. 기다리면 두 점이다. 셈은 금방 끝났다.<br>빛이 처마를 핥고 지나갔다. 둘 다 숨을 안 쉬었다.<br><br>남은 한 점을 줬다. 값은 다 치렀다. 대신 시간에 나눠 걸었다. 반을 뒤에 걸어 두면 상대는 그때까지 이쪽 편이다. 입으로만 하던 흥정 하나가 손에 버릇으로 내려앉았다.`,
      ng:`한 점을 내밀자 그 사람이 받는다. 그리고 처마 밖으로 한 발 나간다.<br><br><span style="color:#9fb4c8;">"여기요."</span> 크지 않은 목소리였다. 빛이 이쪽 얼굴에 박혔다.<br>뛰었다. 젖은 벽돌에 무릎을 갈았다. 뒤에서 그 사람이 남은 한 점 값을 손전등 쪽에서 받는 소리가 났다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-24, mind:-14 }, wake:1 },
    { l:'② 그 사람 신발을 본다.', k:'gaze', dc:20,
      ok:`바지 끝이 젖었다. 어깨도 젖었다. 신발 코만 말랐다.<br><br>비를 맞으며 걸어온 사람이 아니다. 처마 밑에 오래 서 있던 사람도 아니다. 방금 차에서 내렸다.<br>값을 주지 않았다. 고개를 숙이고 처마를 떠났다. 등 뒤에서 그 사람이 손전등 쪽으로 손을 드는 기척이 났다. 가리킬 데가 없어진 손이다.`,
      ng:`신발을 보려고 고개를 숙인 게 들켰다.<br><br>그 사람이 웃는다. 무엇을 보는지 아는 웃음이다. 값이 두 배가 됐다.<br>네 점을 다 줬다. 빛이 지나간 뒤에 그 사람이 말했다. 다음에 또 보자고. 다음이 있다는 말이 제일 비싸다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-15, spirit:-12 } },
    { l:'③ 흥정하지 않고 처마를 나와 빗속으로 간다.', k:'hide', dc:21,
      ok:`흥정을 안 했다. 안 하는 것도 값이다.<br><br>빗속으로 나와 담벼락 그늘을 탔다. 손전등이 처마 밑을 비춘다. 거기 그 사람이 혼자 서 있다.<br>그 사람이 손을 들어 이쪽이 간 쪽을 가리킨다. 빛은 그쪽을 안 봤다. 판 것을 사는 쪽도 파는 사람을 안 믿는다.`,
      ng:`담벼락 그늘이 끝나는 데서 빛에 걸렸다.<br><br>뛰었다. 빗물 고인 하수구 뚜껑에 발이 빠졌다. 발목이 꺾였다.<br>뒤에서 처마 밑 사람이 손전등에게 무언가 말한다. 값도 안 받고. 그게 제일 싼 배신이다.`,
      win:{ exp:14, dream:2 }, lose:{ hp:-22, spirit:-14 } }
  ] },

{ at:'B', t:'계단참 — 나가는 길을 파는 사람',
  x:`계단참에 사람이 쭈그려 앉아 있다. 외투 안에서 젖은 쪽지를 꺼내 보인다.<br><br>
    나가는 길이 적혀 있다고 한다. 자기가 직접 그렸다고.<br>
    값은 꿈결 셋. 아니면 누가 반 시간 여기 대신 앉아 있어 주는 것.<br><br>
    왜 직접 안 나가냐고 물으면 안 된다. 그 질문 하나가 값을 두 배로 올린다.`,
  o:[
    { l:'① 쪽지를 반으로 찢어 반값에 반만 산다.', k:'bond', dc:20,
      ok:`위쪽 반만 달라고 했다. 반값에.<br><br>그 사람이 웃는다. 위쪽 반으로는 어디서 시작하는지만 안다고. 그거면 됐다. 시작이 맞는지만 보면 나머지가 거짓인지 안다.<br>위쪽 반을 따라가니 그림대로 계단이 있다. 맞다. 돌아와서 아래쪽 반을 마저 샀다. 처음 부른 값 그대로.<br><br>그 사람이 아래쪽 반을 건네며 말한다. 끝까지 산 사람은 처음이라고.`,
      ng:`찢자고 하는데 그 사람이 쪽지를 품에 넣는다.<br><br>반만 사려는 사람은 반만 믿는 사람이다. 반만 믿는 사람에게는 안 판다.<br>그 사람이 계단 아래로 짧게 소리친다. 누구를 부르는 소리인지 몰라서 더 무섭다. 계단을 뛰어 올라가다 정강이를 모서리에 박았다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-22, mind:-12 } },
    { l:'② 쪽지를 먼저 받고 이쪽이 대신 앉겠다고 한다.', k:'bond', dc:21,
      doom:{ title:'대신 앉은 자리', what:'계단참에 붙들려 앉았습니다', dc:17, sec:55,
        text:`쪽지를 먼저 받았다. 그리고 계단참에 앉았다. 반 시간이라고 했다.<br><br>그 사람이 일어난다. 무릎 펴는 소리가 길다. 아주 오래 앉아 있던 무릎이다.<br>그 사람은 계단을 내려가며 한 번도 안 돌아본다. 일어나려는데 엉덩이가 바닥에서 안 떨어진다. 계단참이 이쪽 무게를 외우기 시작했다.<br><br>쪽지를 폈다. 길은 맞다. 앉아 있는 사람만 못 가는 길이다.`,
        dieText:`반 시간은 지나갔다. 앉은 사람에게만 안 지나갔다.<br><br>다음에 올라온 팀이 계단참에 쭈그린 사람을 봤다. 외투 안에서 젖은 쪽지를 꺼내 보인다.<br>값은 꿈결 셋. 아니면 반 시간.` },
      ok:`쪽지를 먼저 받았다. 앉겠다고 하고 앉는 시늉만 했다. 무릎을 굽힌 채 엉덩이를 바닥에서 한 뼘 띄웠다.<br><br>그 사람이 일어나 계단을 내려간다. 내려가다 멈칫한다. 자리가 안 채워진 걸 안 것이다.<br>이쪽이 먼저 일어섰다. 계단참은 비었다. 빈자리를 놓고 흥정한 사람 중에 쪽지를 쥔 쪽은 하나다.`,
      win:{ exp:22, dream:3 } },
    { l:'③ 쪽지 뒷면을 보여 달라고 한다.', k:'sense', dc:20,
      ok:`앞면만 보여 주는 쪽지는 뒷면이 진짜다.<br><br>그 사람이 마지못해 뒤집는다. 뒷면에 같은 그림이 거꾸로 그려져 있다. 연필이 더 진하다. 나중에 고쳐 그린 것이다.<br>앞면은 처음 그린 길이다. 뒷면은 가 보고 나서 고친 길이다. 뒷면 그림만 외우고 돌려줬다. 값은 안 냈다. 안 산 것을 외웠을 뿐이다.`,
      ng:`뒷면을 보자는 말에 그 사람이 쪽지를 구겨 입에 넣는다.<br><br>씹는다. 삼킨다. 그리고 이쪽을 본다. 이제 길은 그 사람 배 속에만 있다.<br>계단 위에서 발소리가 내려온다. 셋. 쫓겨 내려가다 난간에 손목을 비틀었다.`,
      win:{ exp:16, dream:2, mind:6 }, lose:{ hp:-20, mind:-14 } }
  ] },

{ at:'B', t:'셔터 앞 — 하나만 내보내 주는 열쇠',
  x:`내려온 셔터 앞에 남자가 서 있다. 열쇠 꾸러미를 손가락에 걸고 돌린다.<br><br>
    하나만 내보내 준다고 한다. 누구든. 고르는 건 이쪽이 하라고.<br>
    팀이 서로 본다. 아무도 말을 안 한다. 말을 꺼내는 사람이 고르는 사람이 된다.<br><br>
    하나만 준다는 사람은 둘도 줄 수 있다. 셋을 주기 싫을 뿐이다.`,
  o:[
    { l:'① 하나를 고르지 않고 판을 키운다 — 다섯이 나가면 남자에게 무엇이 남는지.', k:'bond', dc:21,
      ok:`하나는 안 고르겠다고 했다. 대신 다섯이 다 나가면 남자에게 무엇이 남는지 말했다.<br><br>다섯이 나가면 셔터 안은 빈다. 빈 창고는 지킬 일이 없다. 지킬 일이 없는 사람은 오늘 밤 일찍 들어간다. 그 위에 말린 고기 한 묶음을 얹었다.<br>열쇠가 멈춘다. 남자가 한참 이쪽을 본다. 그리고 셔터를 허리 높이까지만 올린다. 다섯이 허리를 굽히고 지나갔다.<br><br>깎는 흥정만 해 왔다. 오늘은 판을 넓혔다. 나눌 것이 모자라면 판을 키우면 된다. 그 생각이 머리보다 입에 먼저 왔다.`,
      ng:`판을 키우자는 말에 남자가 열쇠를 주머니에 넣는다.<br><br><span style="color:#9fb4c8;">"그럼 아무도 안 나가는 걸로."</span><br>셔터 위 등이 꺼졌다. 어둠 속에서 남자 발소리가 멀어진다. 다른 발소리가 다가온다. 벽을 더듬어 물러나다 철제 선반에 이마를 박았다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-22, mind:-16 }, wake:1 },
    { l:'② 제일 다친 팀원을 고른다.', k:'heal', dc:20,
      ok:`제일 다친 팀원 등을 밀었다. 남자가 셔터를 한 사람 높이만큼 올린다.<br><br>그 팀원이 나가기 전에 돌아본다. 밖에서 기다리겠다고 한다. 셔터가 내려왔다.<br>한참 뒤 셔터 밑 틈으로 무언가 밀려 들어온다. 젖은 약초 한 뭉치. 밖에서 구해 온 것이다. 기다린다는 말은 거짓이 아니었다.`,
      ng:`고르는 순간 다른 팀원 얼굴이 굳는다. 왜 그 사람이냐는 얼굴이다.<br><br>셔터가 올라가고 다친 팀원이 나갔다. 남은 넷 사이에 금이 갔다. 아무도 이쪽 옆에 서지 않는다.<br>골라 준 쪽이 미움을 산다. 값은 팀 안에서 치렀다.`,
      win:{ exp:16, dream:2, item:'약초 뭉치' }, lose:{ mind:-16, spirit:-14 } }
  ] },

{ at:'B', t:'잠근 문 — 문 너머에 멈춘 발소리',
  x:`문을 잠갔다. 안에서. 문 너머에서 발소리가 멈췄다.<br><br>
    두드리지 않는다. 손잡이도 안 돌린다. 그냥 서 있다. 젖은 외투에서 물 떨어지는 소리가 문틈으로 들린다.<br>
    창은 없다. 문은 이것 하나다. 둘 중 하나가 먼저 지쳐야 한다.<br><br>
    협상가에게는 문을 사이에 둔 침묵도 흥정이다. 먼저 말하는 쪽이 조건을 정한다.`,
  o:[
    { l:'① 문에 대고 먼저 말을 건다.', k:'bond', dc:21,
      doom:{ title:'문 너머의 조건', what:'문 너머의 것에게 끌려갑니다', dc:17, sec:55,
        text:`문에 대고 말했다. 무엇을 원하냐고. 줄 수 있는 게 있다고.<br><br>문 너머에서 처음으로 소리가 난다. 웃음 같은 숨이다. 그리고 대답한다. 이쪽 목소리로.<br><span style="color:#9fb4c8;">"문 열어. 그게 다야."</span><br><br>팀원 하나가 그 목소리를 이쪽 말로 듣고 빗장을 올린다. 막을 새가 없었다. 문이 안쪽으로 열린다. 젖은 손이 들어와 제일 가까운 옷깃을 잡는다. 이쪽 옷깃이다.`,
        dieText:`조건은 먼저 말한 쪽이 정했다. 저쪽이 먼저 말했다. 이쪽 목소리로.<br><br>문은 다시 닫혔다. 빗장도 걸렸다.<br>남은 팀원들은 한참 동안 문 너머에서 이쪽 목소리를 들었다. 열어 달라고 했다. 아무도 안 열었다. 그게 맞았다.` },
      ok:`문에 대고 말했다. 여기는 다섯이 아니라 셋뿐이라고. 나머지 둘은 아래로 내려갔다고.<br><br>문 너머 숨이 멈춘다. 셈을 하는 것이다. 셋을 잡으러 들어오느냐, 둘을 쫓아 내려가느냐.<br>발소리가 계단 쪽으로 멀어진다. 둘이 더 비싸 보이게 말했다. 사람은 놓친 쪽을 더 쫓는다.<br><br>다섯이 숨을 내쉬었다. 거짓말이었다. 흥정판에서는 그걸 호가라고 부른다.`,
      win:{ exp:22, dream:3 } },
    { l:'② 아무 말 없이 버틴다.', k:'steady', dc:20,
      ok:`말하지 않았다. 팀원들에게도 손짓으로 입을 막게 했다.<br><br>문 너머 물소리가 계속된다. 똑, 똑. 그러다 그친다. 외투가 다 마를 만큼 서 있었다는 뜻이다.<br>발소리가 멀어진다. 문을 연 건 숨 백을 더 센 다음이다. 문 앞 바닥에 마른 자국이 남았다. 사람 발 모양이다.`,
      ng:`버티는데 팀원 하나가 기침을 참지 못한다.<br><br>문 너머 숨이 웃는다. 손잡이가 처음으로 돈다. 아주 천천히. 잠긴 걸 알면서.<br>밤새 손잡이를 붙들고 있었다. 손바닥 가죽이 벗겨졌다. 새벽에 손잡이가 멈췄다. 저쪽이 지쳐서가 아니다. 이쪽이 얼마나 버티는지 다 재서다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-22, mind:-15 } }
  ] },

{ at:'B', t:'쉬는 자리 — 두고 가자는 말',
  x:`쉬는 자리에서 팀원 하나가 낮게 말한다. 제일 느린 사람을 두고 가자고.<br><br>
    그 말을 들은 느린 사람은 자는 척한다. 자는 척하는 어깨가 굳어 있다.<br>
    시계는 이쪽 편이 아니다. 느린 사람 하나 때문에 다섯이 다 늦을 수 있다. 그것도 맞는 말이다.<br><br>
    맞는 말 둘이 부딪칠 때가 흥정하는 사람이 일하는 때다.`,
  o:[
    { l:'① 느린 사람에게 무엇을 내놓을 수 있는지 직접 묻는다.', k:'bond', dc:20,
      ok:`자는 척하는 어깨를 두드렸다. 다 들었으면 일어나라고 했다. 그리고 물었다. 데려갈 값으로 무엇을 낼 수 있냐고.<br><br>느린 사람이 한참 있다 주머니를 연다. 열쇠가 하나 나온다. 아까 주워 숨겨 둔 것이다. 혼자 쓰려고.<br>두고 가자던 팀원이 입을 다문다. 열쇠는 다섯 몫이 됐다. 느린 사람은 맨 앞에 섰다. 문을 여는 사람이니까.<br><br>값을 깎아 주지 않았다. 내게 했다. 무언가 내는 사람은 짐이 아니라 몫이 된다. 그 순서가 이제 몸에 붙었다.`,
      ng:`묻자 느린 사람이 눈을 뜬다. 낼 게 없다고 한다. 목이 멘다.<br><br>두고 가자던 팀원이 그것 보라는 얼굴을 한다. 판이 거기서 끝났다.<br>결국 다 같이 갔다. 아무도 말을 안 했다. 그 침묵이 무거워서 계단 하나를 헛디뎠다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-20, mind:-14 }, wake:1 },
    { l:'② 두고 가자던 팀원을 따로 불러 무엇이 무서운지 묻는다.', k:'gaze', dc:21,
      ok:`그 팀원을 구석으로 불렀다. 무엇이 무섭냐고 물었다.<br><br>시계가 아니었다. 아까 계단에서 느린 사람이 한 번 멈춰 서는 바람에 이 팀원이 맨 뒤에 남았었다. 그 몇 걸음이 무서웠던 것이다.<br>순서를 바꾸자고 했다. 느린 사람은 이쪽 바로 앞에서 걷는다. 그 팀원은 맨 앞. 고개를 끄덕였다. 무서운 걸 치워 주면 말이 바뀐다.`,
      ng:`구석으로 부르자 그 팀원이 이쪽도 느린 사람 편이냐고 묻는다.<br><br>편이 아니라고 하는 사이 목소리가 커졌다. 다른 팀원들이 다 깼다. 어딘가에서 문 열리는 소리가 났다.<br>쉬는 자리를 버리고 달렸다. 느린 사람이 제일 늦었다. 그 팔을 잡아끌다 같이 넘어졌다.`,
      win:{ exp:16, dream:2, mind:6 }, lose:{ hp:-24, spirit:-12 } }
  ] },

{ at:'B', t:'깜빡이는 간판 아래 — 두 번 팔린 길',
  x:`깜빡이는 간판 아래서 두 팀이 마주쳤다. 이쪽과 다른 팀.<br><br>
    둘 다 같은 사람에게 같은 길을 샀다. 쪽지 그림이 똑같다. 그 길은 한 팀이 지나가면 닫힌다고 들었다.<br>
    저쪽 반장이 먼저 칼자루에 손을 얹는다. 간판 불빛이 칼자루에 붉게 묻었다가 꺼진다.<br><br>
    판 사람은 이미 없다. 값은 두 번 받았다.`,
  o:[
    { l:'① 두 팀이 한 줄로 섞여 지나가면 한 팀으로 친다고 판을 짠다.', k:'bond', dc:21,
      ok:`한 팀이 지나가면 닫힌다고 했다. 그럼 열 사람이 한 줄로 지나가면 한 팀이다.<br><br>저쪽 반장이 칼자루에서 손을 뗀다. 말이 되는지 따지는 얼굴이다. 손을 내밀었다. 열이 한 줄로 섰다. 이쪽 셋, 저쪽 둘, 다시 이쪽 둘, 저쪽 셋. 섞어서. 누가 먼저 나가도 손해가 없게.<br>길은 정말 닫혔다. 맨 끝 사람 등 뒤에서.<br><br>두 팀을 한 팀으로 세었다. 셈법 하나를 바꿔서 싸움 하나를 없앴다. 손이 그 셈법을 기억한다.`,
      ng:`같이 가자는 말에 저쪽 반장이 웃는다. 열이 들어가면 닫히기 전에 끼어 막힐 거라고.<br><br>칼이 반쯤 나왔다. 그 사이 간판이 꺼졌다. 어둠 속에서 누가 먼저 뛰었다. 다들 뛰었다.<br>길 입구에서 열이 엉켰다. 누군가의 팔꿈치가 이쪽 갈비뼈에 박혔다. 길은 저쪽 셋이 지나간 뒤 닫혔다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-26, mind:-12 }, wake:1 },
    { l:'② 판 사람이 어디로 갔는지부터 묻는다.', k:'sense', dc:20,
      ok:`판 사람을 원망하는 대신 어디로 갔는지 물었다. 저쪽도 모른다고 한다. 그런데 저쪽 막내가 말한다. 그 사람 신발에 하얀 가루가 묻어 있었다고.<br><br>바닥을 봤다. 하얀 발자국이 간판 뒤로 이어진다. 따라가니 문이 하나 있다. 쪽지에 없는 문이다.<br>두 팀이 다 그 문으로 갔다. 그 문은 안 닫혔다. 파는 사람이 자기 쓰려고 남겨 둔 길은 늘 열려 있다.`,
      ng:`묻는 사이 저쪽 팀이 먼저 쪽지 길로 들어갔다.<br><br>길이 닫히는 소리가 났다. 쇠가 쇠를 무는 소리다. 이쪽 쪽지는 이제 그냥 종이다.<br>간판 아래 남아 다른 길을 찾았다. 빗물 고인 계단에서 미끄러져 허리를 찧었다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-22, mind:-13 } }
  ] },

{ at:'B', t:'좁은 방 — 질문 하나에 한 걸음',
  x:`좁은 방에 의자가 둘 있다. 하나에 누가 앉아 있다. 전등이 그 얼굴 위로 기울었다. 얼굴이 그늘이다.<br><br>
    그 사람이 빈 의자를 가리킨다. 앉으면 질문을 하겠다고 한다. 대답 하나에 문 쪽으로 한 걸음.<br>
    문까지 다섯 걸음이다.<br><br>
    질문하는 쪽이 값을 정한다. 의자에 앉으면 그 자리가 넘어간다.`,
  o:[
    { l:'① 앉아서 대답할 때마다 질문 하나를 되묻는다.', k:'bond', dc:21,
      ok:`앉았다. 첫 질문이 온다. 어디서 왔냐고.<br><br>대답하고 되물었다. 그쪽은 어디서 왔냐고. 그늘 속 얼굴이 멈칫한다. 질문을 받아 본 적이 없는 얼굴이다.<br>한 걸음. 두 번째 질문. 대답하고 되물었다. 한 걸음. 다섯 번 만에 문 앞에 섰다. 그 사람은 다섯 번 다 대답을 못 했다.<br><br>문을 열고 나오며 돌아봤다. 그 사람이 빈 의자를 보고 있다. 처음으로 무언가 궁금한 얼굴로.`,
      ng:`되묻자 그 사람이 전등을 이쪽으로 꺾는다.<br><br>눈앞이 하얘졌다. 질문이 빨라진다. 대답할 틈도 없이. 대답을 못 할 때마다 의자가 문에서 한 뼘씩 멀어진다. 누가 미는지 모른다.<br>겨우 문까지 기어갔다. 한동안 무엇을 봐도 전등 모양이 남았다.`,
      win:{ exp:20, dream:2 }, lose:{ mind:-16, spirit:-15 } },
    { l:'② 앉지 않고 선 채로 묻는다.', k:'steady', dc:20,
      ok:`앉지 않았다. 선 채로 물었다. 문을 열려면 몇 번 대답해야 하냐고.<br><br>그 사람이 오래 말이 없다. 선 사람에게는 질문을 못 한다. 그렇게 생긴 방이다.<br>침묵이 길어지자 그늘 속에서 그 사람이 일어난다. 이쪽 대신 빈 의자에 가 앉는다. 원래 의자가 비었다. 그 사이 문까지 걸었다. 다섯 걸음. 아무도 묻지 않았다.`,
      ng:`서서 묻는데 무릎이 저절로 꺾인다. 의자가 어느새 등 뒤에 와 있다.<br><br>앉았다. 첫 질문에 대답을 잘못했다. 의자가 한 뼘 물러났다. 다섯 걸음이 여섯이 됐다.<br>일곱 번째 질문에서 겨우 일어났다. 허벅지에 의자 모서리 자국이 깊다. 무릎이 계속 떨린다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-20, mind:-14 } }
  ] },

{ at:'B', t:'다리 밑 — 이쪽을 판 사람이 돌아왔다',
  x:`다리 밑에 아까 헤어진 사람이 서 있다. 다른 팀이다. 이쪽 길을 쫓는 쪽에 판 사람이다.<br><br>
    흠뻑 젖었다. 팔에 붕대를 감았다. 판 값을 받으러 갔다가 값 대신 다친 모양이다.<br>
    그 사람이 말한다. 이번엔 진짜 길을 안다고. 같이 가자고.<br><br>
    한 번 판 사람은 두 번 판다고들 한다. 그런데 한 번 팔고 버림받은 사람은 셈이 다르다.`,
  o:[
    { l:'① 조건을 붙여 받아 준다 — 맨 앞에서 걷게 한다.', k:'bond', dc:21,
      ok:`받아 주겠다고 했다. 대신 맨 앞에서 걸으라고. 길이 거짓이면 제일 먼저 아는 사람이 되라고.<br><br>그 사람이 고개를 끄덕인다. 망설이지 않았다. 그게 대답이었다.<br>맨 앞에서 걸었다. 두 번 멈춰 서서 손을 들었다. 두 번 다 앞에 무언가 있었다. 길은 진짜였다.<br><br>믿어 준 게 아니다. 안 믿어도 되는 자리에 세웠다. 그러면 믿음 없이도 같이 간다. 사람을 다시 쓰는 셈 하나가 손에 붙었다.`,
      ng:`맨 앞에 서라고 하자 그 사람이 웃는다. 쓴웃음이다.<br><br>맨 앞에 섰다. 세 번째 모퉁이에서 사라졌다. 남은 건 젖은 붕대 한 줄. 붕대에 피가 없었다.<br>다친 것도 연기였다. 모퉁이 너머에서 발소리가 여럿 온다. 뒤로 뛰다 팀원끼리 부딪쳐 어깨가 빠질 뻔했다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-26, mind:-14 }, wake:1 },
    { l:'② 붕대를 풀어 상처를 본다.', k:'gaze', dc:20,
      ok:`붕대를 풀어 보자고 했다. 그 사람이 팔을 내민다.<br><br>상처가 있다. 진짜다. 이빨 자국도 칼자국도 아니다. 손목을 한 바퀴 도는 쇠 자국이다. 묶여 있다가 빠져나왔다.<br>판 쪽에게 묶였다는 뜻이다. 판 값이 수갑이었다. 그 팔을 다시 감아 줬다. 이번엔 이쪽이 그 사람 값을 냈다. 붕대 한 줄.`,
      ng:`풀자는 말에 그 사람 얼굴이 굳는다. 못 믿겠으면 관두라고 한다.<br><br>그 사람이 빗속으로 사라졌다. 그 뒤로 길이 자꾸 막혔다. 누가 앞질러 가며 막는 것 같았다.<br>막힌 길 앞에서 돌아서다 빗물 고인 구덩이에 빠졌다. 정강이가 쇠 모서리에 찢겼다.`,
      win:{ exp:16, dream:2, hp:6 }, lose:{ hp:-22, spirit:-14 } }
  ] },

{ at:'B1', t:'경매장 — 늘 한 칸 더 부르는 비옷',
  x:`경매판 앞에 노란 비옷들이 둘러섰다. 분필로 번호를 적는다. 번호 옆에 값이 붙는다.<br><br>
    오늘 마지막 번호는 해무호 갑판 자리 하나다. 사는 사람은 정문을 안 지나고 배로 나간다.<br>
    값이 오른다. 누가 부를 때마다 맨 뒤 비옷 하나가 한 칸 더 부른다. 늘 한 칸.<br><br>
    협상가는 늘 한 칸 더 부르는 사람이 누구 편인지 안다. 파는 쪽이다.`,
  o:[
    { l:'① 바람잡이 비옷 옆에 붙어 따로 흥정한다.', k:'bond', dc:21,
      ok:`맨 뒤 비옷 옆으로 갔다. 남들이 못 듣게 말했다. 한 칸 더 안 부르면 무엇을 주겠다고.<br><br>비옷은 이쪽을 안 본다. 그런데 다음 호가에서 손을 안 든다. 경매꾼이 그쪽을 한 번 본다. 판이 멎었다.<br>그 칸에서 이쪽이 불렀다. 낙찰. 분필이 번호 옆에 이쪽 자리를 적는다.<br><br>나중에 비옷 소매에서 무언가 떨어진다. 말린 고기 한 묶음이다. 받은 값의 반을 돌려준 것이다. 그쪽도 사람 파는 일이 지겨웠던 모양이다.`,
      ng:`붙어서 말을 꺼내자 비옷이 손을 든다. 두 칸.<br><br>경매꾼이 웃는다. 비옷들이 이쪽을 본다. 경매장에서 흥정하러 다니는 사람은 물건이 된다.<br>등 뒤에서 장대 끝 갈고리가 외투 자락을 걸었다. 찢고 빠져나왔다. 쇠가 옆구리까지 긁고 지나갔다.`,
      win:{ exp:20, dream:3, item:'말린 고기' }, lose:{ hp:-25, mind:-13 } },
    { l:'② 부르지 않고 낙찰 직전까지 기다린다.', k:'steady', dc:20,
      ok:`안 불렀다. 값이 오르는 것을 끝까지 봤다.<br><br>마지막 진짜 손님이 손을 내린다. 바람잡이도 손을 내린다. 바람잡이 값에 낙찰될 판이다. 경매꾼 얼굴이 굳는다. 자기네 물건을 자기네가 사게 생겼다.<br>그때 한 칸 아래 값을 불렀다. 경매꾼이 받았다. 안 받으면 빈손이다. 깎는 건 끝에서 한다.`,
      ng:`기다리는 사이 경매꾼이 이쪽을 본다. 손을 안 드는 사람이 경매장에서는 제일 수상하다.<br><br>노란 비옷 둘이 다가와 양팔을 잡는다. 정중하게. 뿌리치다 손목이 꺾였다.<br>그 사이 갑판 자리는 팔렸다. 분필이 모르는 번호를 적는다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-22, spirit:-13 } }
  ] },

{ at:'B1', t:'냉동 창고 — 늙은 하역부의 품삯',
  x:`냉동 창고 구석에 늙은 하역부가 앉아 있다. 성에 낀 장갑으로 손을 비빈다.<br><br>
    정문 기계실 열쇠가 어디 있는지 안다고 한다. 서른 해를 여기서 짐을 졌다. 품삯은 한 번도 다 못 받았다.<br>
    밀린 품삯을 달라고 한다. 이쪽이 떼먹은 돈이 아니다. 그래도 달라고 한다.<br><br>
    남이 떼먹은 값을 받으러 온 사람은 돈보다 셈을 원한다.`,
  o:[
    { l:'① 밀린 품삯을 같이 세어 준다.', k:'bond', dc:20,
      ok:`같이 셌다. 몇 해, 몇 달, 하루 몇 짐. 노인이 손가락으로 세고 이쪽이 벽 성에 위에 금을 그었다.<br><br>금이 벽을 반쯤 채웠다. 다 세고 나서 노인이 한참 금을 본다. 이만큼이었구나, 한다. 그 말을 하고 나서야 어깨가 내려간다.<br>품삯은 못 줬다. 노인이 장갑을 벗더니 안쪽에 꿰맨 열쇠를 뜯어 준다.<br><br>값을 치르지 않고 값을 알아줬다. 받을 사람에게는 그게 반값쯤 된다. 다음 흥정에서는 그 셈을 먼저 꺼낼 것이다.`,
      ng:`같이 세다가 숫자가 틀렸다. 노인이 그걸 알아챈다.<br><br>너도 셈을 속이냐고 한다. 서른 해 동안 셈을 속인 얼굴들이 노인 눈에 다 겹친다. 노인이 갈고리를 쥔다.<br>뒷걸음치다 언 바닥에 미끄러졌다. 뒤통수가 쇠 레일에 부딪혔다. 한동안 머릿속에서 숫자가 혼자 셌다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-24, mind:-15 }, wake:1 },
    { l:'② 품삯 대신 이쪽 몫의 말린 고기를 다 내민다.', k:'luck', dc:20,
      ok:`이쪽 몫 고기를 다 내밀었다. 품삯은 아니지만 배는 부르다고.<br><br>노인이 고기를 보다가 반을 돌려준다. 반이면 된다고. 다 받으면 자기도 떼먹는 쪽이 된다고.<br>열쇠 자리는 말로 알려 줬다. 기계실 톱니 셋째 칸 밑. 노인이 덧붙인다. 톱니에 소매 걸리지 말라고. 그건 공짜라고.`,
      ng:`고기를 내밀자 노인이 웃는다. 서른 해를 고기 한 줌으로 치냐고.<br><br>노인이 등을 돌린다. 문 쪽에서 레일이 움직이는 소리가 난다. 노인은 그 소리를 알면서 말을 안 한다.<br>빈 갈고리가 어깨를 치고 지나갔다. 성에가 상처에 붙어 한참 얼얼했다.`,
      win:{ exp:16, dream:2, item:'말린 고기' }, lose:{ hp:-22, spirit:-13 } }
  ] },

{ at:'B1', t:'방파제 — 우산의 마지막 값',
  x:`방파제 끝에 검은 우산이 서 있다. 처음 데려다준 남자다. 아직 우산을 안 접었다.<br><br>
    장부를 가져왔냐고 묻는다. 배는 저쪽에 있다고 한다. 장부와 바꾸자고.<br>
    파도가 방파제를 넘는다. 우산 끝에서 물이 떨어진다. 우산 밑은 젖지 않았다.<br><br>
    처음 값을 부른 사람이 마지막 값을 바꾼다. 지금이 마지막이다.`,
  o:[
    { l:'① 장부를 넘기기 전에 우산 밑 얼굴을 보여 달라고 한다.', k:'bond', dc:22,
      doom:{ title:'우산 밑', what:'우산 밑으로 끌려 들어갑니다', dc:18, sec:50,
        text:`얼굴을 보여 달라고 했다. 흥정은 얼굴을 보고 한다고.<br><br>남자가 우산을 기울인다. 이쪽 쪽으로. 우산 밑이 넓다. 사람 하나 설 만큼이 아니다. 방 하나만 하다.<br>그 안에 얼굴이 없다. 젖지 않은 어둠만 있다. 우산 살이 이쪽 어깨 위로 내려온다. 비가 끊겼다.<br><br>밖에서 팀원이 이쪽 이름을 부른다. 빗소리 너머처럼 멀다.`,
        dieText:`검은 우산은 끝내 접히지 않았다.<br><br>방파제 끝에서 남자가 혼자 걸어 나간다. 우산 밑이 아까보다 조금 무겁다.<br>창고 칠판의 다섯 옆에 분필 점이 하나 늘었다. 모자라면 채울 것. 채웠다.` },
      ok:`얼굴을 보여 달라고 했다. 남자가 우산을 기울이려다 멈춘다.<br><br>그 멈춤이 대답이다. 얼굴을 못 보이는 쪽은 값을 못 올린다. 장부를 반만 내밀었다. 나머지 반은 배에 오른 다음에.<br>남자가 반을 받는다. 우산 밑에서 처음으로 사람 목소리가 난다. 피곤한 목소리다. 다들 그렇게 하더라고.<br><br>배로 가는 판자가 놓였다. 남자는 끝까지 우산을 안 접었다. 이쪽도 장부 반을 끝까지 안 놓았다.`,
      win:{ exp:24, dream:4 } },
    { l:'② 장부를 바다 위로 내밀고 배부터 대라고 한다.', k:'gaze', dc:21,
      ok:`장부를 방파제 끝에 내밀었다. 파도 위로. 배를 먼저 대라고 했다.<br><br>우산이 처음으로 흔들린다. 남자가 원하는 건 배도 이쪽도 아니다. 장부다. 그걸 보고 나니 판이 이쪽으로 넘어왔다.<br>배가 먼저 왔다. 판자가 놓였다. 장부는 판자를 다 건넌 다음에 우산 밑으로 던졌다. 남자는 그걸 받아 품에 넣었다. 젖지 않게.`,
      ng:`던지겠다고 하자 남자가 웃는다. 던지라고 한다.<br><br>장부는 핑계였다. 남자가 원한 건 처음부터 장부가 아니었다. 우산 밑에서 무언가 이쪽 손목을 본다.<br>파도가 방파제를 넘었다. 휩쓸려 무릎이 콘크리트에 갈렸다. 장부는 바다에 떨어졌다. 아무도 줍지 않았다.`,
      win:{ exp:18, dream:3 }, lose:{ hp:-28, mind:-14 } }
  ] },

{ at:'B1', t:'경비 초소 — 자는 척하는 경비',
  x:`정문 앞 경비 초소에 불이 켜져 있다. 경비가 의자에 기대 잔다. 모자를 눈까지 눌러썼다.<br><br>
    책상 위 라디오가 작게 켜져 있다. 잡음 사이로 일기 예보가 나온다. 새벽까지 비.<br>
    경비 손이 무릎 위에 있다. 손가락이 라디오 박자를 탄다. 자는 손이 아니다.<br><br>
    자는 척하는 사람이 기다리는 건 이유다. 안 깨어나도 되는 이유.`,
  o:[
    { l:'① 깨우지 않고 책상 위에 값을 놓고 지나간다.', k:'bond', dc:21,
      ok:`책상 위 라디오 옆에 말린 고기 한 점을 놓았다. 소리 없이.<br><br>경비 손가락이 한 번 멈췄다가 다시 박자를 탄다. 받았다는 뜻이다.<br>다섯이 초소 앞을 지났다. 경비는 끝까지 자는 척했다. 안 깨어나는 값은 안 깨우고 치러야 한다. 깨우면 깨어난 사람 값으로 오른다.`,
      ng:`고기를 놓는데 라디오가 끊긴다. 잡음도 없이.<br><br>경비 손가락이 멈춘 채 다시 안 움직인다. 고기가 모자란 것이다. 아니면 고기를 원한 게 아니다.<br>초소 창이 열리고 손전등이 켜졌다. 정문 쪽으로 뛰었다. 젖은 철망에 손바닥이 찢겼다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-24, mind:-12 } },
    { l:'② 경비에게 들리게 혼잣말로 핑계를 만들어 준다.', k:'gaze', dc:20,
      ok:`초소 앞에서 팀원에게 말하는 척했다. 들리게. 저 경비는 비 오는 밤마다 졸아서 아무것도 못 본다더라고. 그러니 오늘도 아무 일 없을 거라고.<br><br>경비 손가락이 박자를 한 번 놓친다. 그리고 다시 탄다. 아무것도 못 본 사람이 되기로 한 것이다. 핑계를 받았다.<br>정문을 지나며 봤다. 모자 밑으로 입꼬리가 조금 올라가 있다. 남이 만들어 준 핑계는 공짜라서 좋다.`,
      ng:`혼잣말을 하는데 경비가 모자를 들어 올린다.<br><br>자는 척하는 사람에게 자는 척하라고 하면 그건 모욕이다. 경비가 일어선다. 책상 밑에서 곤봉을 꺼낸다.<br>달려 나가다 곤봉에 어깨를 맞았다. 팔이 한동안 안 올라갔다.`,
      win:{ exp:18, dream:3, spirit:6 }, lose:{ hp:-26, spirit:-12 } }
  ] },

{ at:'B2', t:'퇴원 창구 — 보호자 서명란',
  x:`원무과 퇴원 창구가 열려 있다. 직원 하나가 앉아 서류를 내민다.<br><br>
    퇴원 신청서. 맨 아래에 보호자 서명란이 있다. 보호자가 없으면 퇴원이 안 된다.<br>
    직원 손톱이 그 칸을 두드린다. 똑, 똑. 뒤로 줄이 생기기 시작한다. 번호표를 쥔 사람들. 얼굴이 다 창구를 본다.<br><br>
    협상가는 안다. 빈칸을 채우는 건 사람이 아니라 말이다.`,
  o:[
    { l:'① 팀원끼리 돌아가며 서로의 보호자로 서명한다.', k:'bond', dc:21,
      ok:`첫째가 둘째 서류에 서명했다. 둘째가 셋째 것에. 마지막이 첫째 것에. 원으로.<br><br>직원이 서류를 넘겨 본다. 보호자도 환자도 한 일행이다. 그런데 칸은 다 찼다. 그러면 안 된다는 줄은 어디에도 없다.<br>도장이 찍혔다. 쾅, 다섯 번.<br><br>누가 누구를 책임지는지 서로 정해 줬다. 원으로 엮인 셈은 끊을 데가 없다. 사람끼리 엮어 값을 대신 치르게 하는 법이 하나 손에 붙었다.`,
      ng:`서명을 돌리는데 마지막 사람 펜이 안 나온다. 잉크가 말랐다.<br><br>직원이 손톱을 멈춘다. 서류를 반으로 접는다. 다음 번호를 부른다. 뒤에 선 사람들이 이쪽을 밀고 창구로 몰린다.<br>밀려 넘어지며 대기석 의자 모서리에 옆구리를 박았다. 손에 번호표가 하나 쥐여 있다. 언제 쥐었는지 모른다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-22, mind:-15 }, wake:1 },
    { l:'② 보호자가 오는 중이라고 하고 시간을 번다.', k:'steady', dc:20,
      ok:`보호자가 오는 중이라고 했다. 비 때문에 늦는다고.<br><br>직원이 시계를 본다. 비 오는 밤에 늦는 보호자는 흔하다. 서류를 옆으로 밀어 두고 다음 번호를 부른다.<br>그 사이 창구 뒤 문이 한 번 열렸다 닫혔다. 직원이 다음 서류를 받으러 돌아선 틈이다. 그 문으로 갔다. 서류는 창구 위에 아직 보호자를 기다린다.`,
      ng:`오는 중이라고 하자 직원이 수화기를 든다. 보호자에게 전화해 주겠다고. 번호를 대라고.<br><br>아무 번호나 댔다. 직원이 누른다. 신호가 간다. 누가 받는다.<br><span style="color:#9fb4c8;">"네, 지금 가요."</span> 이쪽 목소리였다. 수화기를 빼앗아 내려놓았다. 손이 한참 떨렸다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-16, spirit:-15 } }
  ] },

{ at:'B2', t:'휴게실 — 종이학 하나에 한 줄',
  x:`휴게실 창가에서 노인이 종이학을 접는다. 약 봉투를 펴서.<br><br>
    노인이 학 하나를 이쪽 앞에 놓는다. 그리고 손바닥을 편다.<br>
    학을 받으려면 무엇을 내야 한다. 날개 안쪽에 무언가 적혀 있다. 글씨가 작다.<br><br>
    여기서는 오래 있던 사람들이 값을 정한다. 그 값은 대개 돈이 아니다.`,
  o:[
    { l:'① 무엇을 원하는지 묻지 않고 그냥 기다린다.', k:'bond', dc:20,
      ok:`아무것도 안 내밀었다. 편 손바닥 앞에 그냥 앉아 있었다.<br><br>노인이 한참 이쪽을 본다. 그리고 그 손바닥으로 이쪽 손등을 덮는다. 따뜻하다. 원한 건 이거였다. 누가 손을 안 빼는 것.<br>학을 받았다. 날개 안쪽에 적혀 있다. 『3시 교대 · 세탁물 투입구 아래』.<br><br>노인이 새 학을 접기 시작한다. 이번엔 이쪽을 안 본다. 값은 다 받았다는 뜻이다.`,
      ng:`기다리는데 복도에서 딸깍 소리가 다가온다.<br><br>노인이 손바닥을 접는다. 학을 도로 가져간다. 기다리는 값은 시간이었다. 이쪽에는 그 시간이 없었다.<br>문 뒤에 숨어 계수기 소리가 지나가길 기다렸다. 숨을 너무 오래 참아 눈앞이 하얗게 탔다.`,
      win:{ exp:18, dream:2, mind:8 }, lose:{ mind:-16, spirit:-12 } },
    { l:'② 가짜 이름 하나를 값으로 낸다.', k:'luck', dc:21,
      ok:`이름을 알려 줬다. 진짜 말고 아무 이름이나. 노인이 그걸 학 날개에 적는다.<br><br>노인이 웃는다. 가짜인 걸 안다. 그래도 받는다. 여기서는 진짜 이름이 제일 위험하다. 가짜 이름을 낼 줄 아는 사람에게만 학을 준다.<br>받은 학 날개 안쪽에 적혀 있다. 『부르면 번호로 대답』. 노인 손가락에 볼펜 자국이 많다. 학을 많이 줬다.`,
      ng:`이름을 대는데 입에서 진짜 이름이 나왔다.<br><br>노인 손이 멈춘다. 학 날개에 그 이름을 천천히 적는다. 그리고 창틀 학들 사이에 끼운다. 스물한 번째.<br>왜 그러냐고 묻는데 노인이 고개를 젓는다. 머리 안쪽이 오래 울렸다. 누가 그 이름을 부르면 대답해 버릴 것 같다.`,
      win:{ exp:16, dream:2, item:'꿀 한 줌' }, lose:{ mind:-15, spirit:-16 } }
  ] },

{ at:'B2', t:'정각 십 분 전 — 같이 나가자는 사람',
  x:`정각까지 십 분. 옆 침대 사람이 이쪽 소매를 잡는다.<br><br>
    같이 나가고 싶다고 한다. 목소리가 작다. 화이트보드 숫자에 이 사람도 들어 있다.<br>
    이 사람이 나가면 빈 침대가 하나 는다. 빈 침대를 세는 것은 찾으러 온다.<br><br>
    숫자를 맞추는 길은 둘이다. 하나 빼고 하나 넣는 것. 아니면 셈 자체를 바꾸는 것.`,
  o:[
    { l:'① 그 사람 대신 대답해 줄 사람을 병동에서 찾는다.', k:'bond', dc:21,
      ok:`병실을 돌았다. 깨어 있는 사람에게 물었다. 정각에 두 번 대답해 줄 수 있냐고. 자기 이름 한 번, 빈 침대 이름 한 번.<br><br>달력에 금 긋던 여자가 손을 든다. 대신 무엇을 줄 거냐고는 묻지 않는다. 나간 사람이 밖에서 비 냄새를 한 번 맡아 주면 된다고 한다.<br>정각에 여자가 두 번 대답했다. 목소리를 바꿔서. 계수기가 두 번 딸깍했다. 숫자는 맞았다.<br><br>내는 사람과 받는 사람을 다르게 짰다. 셋이 하는 흥정이다. 판이 둘이 아니라 셋이어도 맞출 수 있다는 걸 손이 먼저 알았다.`,
      ng:`깨어 있는 사람을 찾는데 다들 고개를 돌린다. 두 번 대답하다 걸리면 자기가 빈 침대가 된다.<br><br>정각이 왔다. 계수기 소리가 복도를 돈다. 소매를 잡았던 손이 놓인다. 그 사람은 침대로 돌아가 이불을 덮었다.<br>딸깍. 그 사람이 대답한다. 목소리가 떨렸다. 그 떨림이 오래 귀에 남았다.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-18, spirit:-16 }, wake:1 },
    { l:'② 데려가는 대신 이불을 말아 그 침대를 채운다.', k:'fix', dc:20,
      ok:`이불을 말아 사람 모양을 만들었다. 그 사람이 직접 고쳐 준다. 무릎을 조금 굽히고, 손 하나를 이불 밖으로.<br><br>자기 침대를 자기가 채웠다. 오래 누워 있던 사람만 아는 모양이다.<br>정각에 이불은 대답하지 않았다. 계수기는 이불 밖 손을 보고 딸깍했다. 이 셈은 대답이 아니라 모양을 센다. 그 사람은 이쪽 등 뒤에서 숨을 죽이고 있었다.`,
      ng:`마는 사이 정각이 왔다. 계수기 소리가 문 앞에 섰다.<br><br>그 사람이 반쯤 만 이불 옆에 그대로 누웠다. 한 침대에 둘이. 딸깍, 딸깍. 두 번.<br>한 침대에서 둘이 세어졌다. 간호사가 수첩에 무언가 적는다. 이쪽 침대 명패를 보면서. 등에 식은땀이 줄을 그었다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-20, mind:-16 } }
  ] },

{ at:'B2', t:'기록 보관실 창가 — 무전기와 사진',
  x:`기록 보관실 창가에 경비원이 서 있다. 밖의 비를 본다. 허리에 무전기가 걸렸다.<br><br>
    여기를 지나야 계단이다. 경비원이 돌아보면 무전기를 든다. 들면 직원이 온다.<br>
    경비원 손에 사진 한 장이 들려 있다. 젖지 않게 비닐에 쌌다. 아이 사진이다.<br><br>
    협상가는 사진을 쥔 사람이 무엇을 사고 싶어 하는지 안다. 바깥이다.`,
  o:[
    { l:'① 다가가서 밖에 나가면 그 아이에게 무엇이든 전해 주겠다고 한다.', k:'bond', dc:22,
      doom:{ title:'무전기', what:'흰 가운들에게 끌려갑니다', dc:17, sec:50,
        text:`다가가서 말했다. 나가면 사진 속 아이에게 무엇이든 전해 주겠다고.<br><br>경비원이 돌아본다. 눈이 젖었다. 그리고 무전기를 든다. 천천히. 미안하다는 얼굴로.<br><span style="color:#9fb4c8;">"7층 하나 내려왔습니다."</span><br><br>복도 양쪽 문이 한꺼번에 열린다. 흰 가운들이 걸어 나온다. 서두르지 않는다. 양팔을 잡힌다. 차고 가볍고 안 놓는다.`,
        dieText:`경비원은 사진을 비닐째 주머니에 넣었다.<br><br>밖으로 나가는 값은 안에 남을 사람 하나다. 경비원도 그 값을 냈었다. 오래전에.<br>7층 화이트보드 숫자가 맞았다. 볼펜 자국 하나가 지워졌다.` },
      ok:`다가가서 말했다. 나가면 사진 속 아이에게 무엇이든 전해 주겠다고.<br><br>경비원이 한참 사진을 본다. 무전기에 손을 얹었다가 뗀다. 사진 뒤에 볼펜으로 한 줄 적는다. 『아빠 아직 근무 중.』<br>사진을 받았다. 경비원이 다시 창 쪽으로 돌아선다. 그 등 뒤로 계단까지 갔다. 무전기는 끝까지 안 울렸다.`,
      win:{ exp:24, dream:4 } },
    { l:'② 경비원이 사진을 보며 쉬는 숨에 맞춰 지나간다.', k:'hide', dc:21,
      ok:`경비원이 사진을 볼 때마다 어깨가 조금 내려간다. 숨 쉬는 박자다. 길게 들이쉬고 길게 내쉰다.<br><br>내쉬는 동안 한 사람씩 지났다. 다섯 번 내쉬었다. 다섯이 지났다.<br>계단 문을 닫으며 봤다. 경비원 손가락이 사진 속 얼굴을 쓰다듬는다. 그 사람도 아무도 못 지나가길 바란 건 아니었다.`,
      ng:`넷째가 지날 때 경비원 숨이 멈춘다. 창에 비친 것이다.<br><br>무전기가 반쯤 들린다. 내려간다. 다시 들린다. 그 망설임 사이로 넷째와 다섯째가 뛰어 지났다.<br>계단에서 돌아보니 경비원이 무전기를 귀에 대고 서 있다. 아무 말도 안 하고. 세 층을 달려 내려가다 발목을 접질렀다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-24, mind:-14 } }
  ] },

{ at:'B3', t:'식당칸 — 표를 바꾸자는 빨간 외투',
  x:`식당칸 창가에 빨간 외투를 입은 손님이 앉아 있다. 맞은편 의자를 손으로 가리킨다.<br><br>
    표를 바꾸자고 한다. 자기 표는 다음 역에서 내리는 표라고. 이쪽 표는 행선지 칸이 비었다.<br>
    손님 표를 봤다. 행선지 칸에 역 이름이 찍혀 있다. 잉크가 아직 번진다.<br><br>
    바꾸자는 물건은 뒷면부터 봐야 한다. 앞면은 파는 쪽이 고른 면이다.`,
  o:[
    { l:'① 표를 뒤집어 보여 달라고 한다.', k:'gaze', dc:20,
      ok:`뒷면을 보자고 했다. 손님이 웃으며 뒤집는다.<br><br>뒷면에 개찰 구멍이 다섯 개 있다. 다 다른 모양이다. 옆얼굴, 옆얼굴, 옆얼굴. 다섯 사람이 이 표를 들고 탔다. 다섯 다 못 내렸다.<br>바꾸지 않았다. 손님이 표를 외투 안에 넣는다. 다음 사람을 기다리는 얼굴이다. 외투 안쪽이 두툼하다.`,
      ng:`뒤집어 달라고 하자 손님이 표를 탁자에 엎어 놓는다.<br><br>뒷면에 구멍이 없다. 깨끗하다. 진짜 같다. 손을 뻗는 순간 손님 손이 이쪽 손목을 덮는다. 차다.<br>뿌리쳤다. 손목에 손가락 자국이 하얗게 남았다. 창에 비친 손님 얼굴이 이쪽 얼굴이다. 한 박자 늦게 원래대로 돌아온다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-15, spirit:-16 } },
    { l:'② 바꾸지 말고 다음 역까지만 빌리자고 한다.', k:'bond', dc:21,
      ok:`바꾸지 말고 빌리자고 했다. 다음 역까지만. 그동안 이쪽 것을 하나 맡기겠다고.<br><br>손님 웃음이 처음으로 멎는다. 빌린 사람은 돌려줘야 한다. 돌려주는 사람은 표 주인이 되지 않는다. 손님은 그 셈을 안다. 그래서 싫어한다.<br>손님이 표를 거둔다. 바꾸는 흥정만 받는 손님이었다. 바꾸면 이쪽이 저쪽이 된다. 빌리면 안 된다.<br><br>사고팔기 말고 빌리고 돌려주기. 판의 모양을 바꾸면 상대 속셈이 드러난다. 손이 그 모양을 하나 더 외웠다.`,
      ng:`빌리자는 말에 손님이 표를 선뜻 내민다.<br><br>받는 순간 표가 손바닥에 붙는다. 젖은 종이처럼. 어느새 손님 외투가 이쪽 어깨에 걸쳐져 있다.<br>외투를 벗어 던지고 표를 떼어 냈다. 손바닥 가죽이 표 모양으로 벗겨졌다. 손님은 외투를 주워 입고 다른 칸으로 갔다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-22, spirit:-16 }, wake:1 },
    { l:'③ 대답 없이 맞은편에 앉아 밥부터 시킨다.', k:'luck', dc:20,
      ok:`앉았다. 표 얘기는 안 했다. 지나가는 급사에게 밥을 시켰다.<br><br>손님이 기다린다. 먹는 사람은 재촉할 수 없다. 흥정에도 예의가 있다.<br>밥은 따뜻했다. 접시 밑에 접힌 냅킨이 있다. 펴 보니 연필로 적혀 있다. 『빨간 외투랑 바꾸지 마세요 — 주방』. 다 먹고 일어섰다. 손님이 처음으로 혀를 찼다.`,
      ng:`앉았는데 밥이 안 온다. 급사가 이쪽을 세 번 지나친다.<br><br>손님이 웃는다. 여기선 표 없는 사람에게 밥을 안 준다고. 바꾸면 준다고.<br>배가 등에 붙었다. 일어서다 어지러워 탁자 모서리를 짚었다. 깨진 접시에 손바닥이 베였다.`,
      win:{ exp:16, dream:2, hp:8 }, lose:{ hp:-20, mind:-14 } }
  ] },

{ at:'B3', t:'차장실 — 조는 차장과 열쇠 꾸러미',
  x:`차장실 문이 반쯤 열려 있다. 차장이 의자에서 꾸벅꾸벅 존다. 허리에 열쇠 꾸러미가 달렸다.<br><br>
    앞 칸 문은 그 열쇠로 연다. 탁자에 운행표가 펴져 있다. 지나간 역마다 동그라미가 쳐 있다.<br>
    차장이 졸다가 눈을 뜬다. 이쪽을 보고도 놀라지 않는다.<br><br>
    <span style="color:#9fb4c8;">"표 확인은 끝났습니다."</span> 그리고 다시 눈을 감는다.`,
  o:[
    { l:'① 이 열차에서 무엇을 지키고 있는지 묻는다.', k:'bond', dc:21,
      ok:`눈을 감은 차장에게 물었다. 이 열차에서 뭘 지키고 있냐고.<br><br>차장이 눈을 감은 채 운행표를 짚는다. 맨 아래. 종착 04:44. 그 칸만 동그라미가 없다.<br>제시간에 닿는 것. 그것만 지킨다고 한다. 누가 내리든 말든. 그럼 앞 칸 문이 열려도 시간은 안 늦는다고 말했다. 차장이 꾸러미에서 열쇠 하나를 빼 탁자에 놓는다. 눈은 끝까지 안 떴다.`,
      ng:`묻자 차장이 눈을 뜬다. 지키는 건 이 열차에 탄 사람 수라고 한다. 처음부터 끝까지 같은 수.<br><br>차장이 일어서서 이쪽 일행을 센다. 손가락으로. 하나, 둘, 셋, 넷, 다섯, 여섯.<br>여섯이다. 하나가 많다. 누가 많은지 아무도 모른다. 서로 얼굴을 보다 다들 한 발씩 물러섰다. 그 숫자가 밤새 머리에서 안 떠났다.`,
      win:{ exp:20, dream:3 }, lose:{ mind:-17, spirit:-16 } },
    { l:'② 운행표의 동그라미를 센다.', k:'gaze', dc:20,
      ok:`운행표를 봤다. 동그라미가 역마다 하나가 아니다. 저녁재에 셋, 가는골에 둘.<br><br>내린 사람 수다. 서지 않는 역에서 내린 사람. 차장은 그걸 센다. 내려도 센다. 내린 사람은 돌아오지 않는다.<br>종착역 칸 옆에 연필로 작게 적혀 있다. 『기관실 앞 문 — 04:39 이후 열림』. 차장 글씨다. 일부러 펴 둔 운행표였다.`,
      ng:`세는데 동그라미가 는다. 이쪽이 셀 때마다 하나씩.<br><br>차장이 연필을 쥐고 있다. 눈을 감은 채 그린다. 이쪽 손가락이 짚는 칸에.<br>손을 뗐다. 손가락이 닿았던 칸마다 동그라미가 생겼다. 다음 역에 하나. 그다음 역에 하나. 손끝이 한참 차가웠다.`,
      win:{ exp:18, dream:2, mind:6 }, lose:{ mind:-15, spirit:-14 } }
  ] },

{ at:'B3', t:'특실 — 문을 열어 주면 알려 준다는 목소리',
  x:`특실 문 너머에서 목소리가 난다. 작고 또박또박.<br><br>
    문을 열어 주면 얼굴 바꾸는 손님이 지금 어느 칸에 있는지 알려 주겠다고 한다. 자기는 그 손님에게 갇혔다고.<br>
    문은 밖에서 걸쇠가 걸렸다. 걸쇠 위에 빗물 묻은 손자국이 있다.<br><br>
    문 하나 사이의 흥정은 문이 열리는 순간 끝난다. 열기 전에 다 받아야 한다.`,
  o:[
    { l:'① 열기 전에 문틈으로 먼저 말하게 한다.', k:'bond', dc:21,
      ok:`열기 전에 먼저 말하라고 했다. 절반만이라도. 나머지는 열고 나서.<br><br>목소리가 한참 망설인다. 그리고 말한다. 그 손님은 지금 4호차 복도에 있다고. 검표원 얼굴로.<br>4호차 쪽을 봤다. 검표원이 걸어온다. 구두에 물기가 없다. 맞다.<br><br>걸쇠를 풀었다. 나머지 절반은 필요 없었다. 그래도 열었다. 먼저 받은 쪽이 끝까지 치르면 다음 판이 쉬워진다. 판과 판을 잇는 셈이 이제 손에 있다.`,
      ng:`먼저 말하라고 하자 목소리가 그친다. 오래.<br><br>그리고 문 아래 틈으로 종이가 밀려 나온다. 『4호차』. 그 사이 등 뒤에서 구두 소리가 난다. 물기 없는 구두.<br>돌아보니 검표원이 서 있다. 종이는 미끼였다. 문 안과 문 밖이 한편이었다. 집게가 손등 살을 물었다. 반달 모양으로.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-24, spirit:-15 }, wake:1 },
    { l:'② 걸쇠 위 손자국을 본다.', k:'gaze', dc:20,
      ok:`손자국을 봤다. 빗물이 덜 말랐다. 손가락이 길다. 엄지 자리가 걸쇠 아래쪽에 찍혔다.<br><br>밖에서 잠그는 손은 엄지가 위에 온다. 이건 안에서 문틈으로 손을 빼서 잠근 자국이다.<br>갇힌 사람이 아니다. 스스로 잠그고 기다리는 사람이다. 걸쇠를 안 풀었다. 문 너머 목소리가 또박또박 이쪽 이름을 부르기 시작했다. 돌아보지 않았다.`,
      ng:`손자국을 보는데 문틈으로 손가락이 나온다. 걸쇠 쪽으로.<br><br>안에서 걸쇠가 풀린다. 이쪽 눈앞에서. 문이 한 뼘 열린다. 그 틈으로 이쪽 얼굴이 보인다. 이쪽을 보고 있다.<br>몸으로 문을 밀어 닫았다. 걸쇠에 손가락이 끼었다. 손톱 하나가 까맣게 죽었다.`,
      win:{ exp:18, dream:3, spirit:6 }, lose:{ hp:-22, mind:-15 } }
  ] },

{ at:'B3', t:'탄수차 끝 — 화부와의 셈',
  x:`탄수차 끝에 화부가 쪼그려 앉아 있다. 얼굴이 검댕투성이다. 삽을 무릎에 눕혔다.<br><br>
    기관실 문은 화부 뒤에 있다. 화부는 비켜 주지 않는다. 대신 묻는다. 내릴 거냐고.<br>
    내릴 거면 자기도 데려가 달라고 한다. 그 값으로 열차를 한 번 늦춰 주겠다고. 석탄을 덜 넣으면 된다고.<br><br>
    같이 내리자는 사람은 같이 남자는 사람도 될 수 있다.`,
  o:[
    { l:'① 먼저 늦추면 데려가겠다고 한다.', k:'bond', dc:22,
      doom:{ title:'화실 앞의 셈', what:'화실 쪽으로 밀려납니다', dc:18, sec:45,
        text:`먼저 늦추라고 했다. 그러면 데려가겠다고.<br><br>화부가 삽을 든다. 석탄을 뜨지 않는다. 삽날이 이쪽을 향한다. 화부 얼굴의 검댕이 땀에 흘러내린다. 그 밑에 다른 얼굴이 있다. 식당칸 빨간 외투의 얼굴.<br>먼저 늦출 생각은 처음부터 없었다. 화실 문이 열린다. 뜨거운 바람이 이쪽 등을 민다.<br><br>삽자루가 가슴을 밀어낸다. 발꿈치가 화실 문턱에 닿았다.`,
        dieText:`열차는 한 번 늦어졌다. 화실에 석탄 대신 다른 것이 들어간 동안.<br><br>그리고 다시 빨라졌다. 04:44에 닿아야 하니까.<br>탄수차 끝에 화부가 쪼그려 앉아 있다. 얼굴이 검댕투성이다. 이번엔 조금 낯익은 얼굴이다.` },
      ok:`먼저 늦추라고 했다. 화부가 이쪽을 오래 본다.<br><br>그리고 삽을 내려놓는다. 석탄을 안 넣는다. 압력계 바늘이 천천히 내려간다. 덜컹과 덜컹 사이가 벌어진다.<br>약속을 먼저 지킨 쪽은 화부였다. 기관실 문을 열 때 화부 팔을 잡아 같이 끌었다. 손바닥이 뜨겁다. 진짜 사람 손이다. 검댕 밑 얼굴은 한 번도 안 바뀌었다.`,
      win:{ exp:24, dream:4 } },
    { l:'② 화부가 쉬는 동안 이쪽이 석탄을 퍼 주겠다고 한다.', k:'steady', dc:21,
      ok:`삽을 달라고 했다. 화부가 쉬는 동안 이쪽이 퍼 주겠다고. 늦추는 건 화부가 정하라고.<br><br>석탄을 펐다. 팔이 금방 끊어질 것 같다. 화부가 옆에서 본다. 처음으로 쉬는 얼굴이다.<br>열 삽째에 화부가 손을 든다. 그만. 압력계를 보고 고개를 끄덕인다. 이쪽 삽질이 서툴러서 속도가 저절로 떨어졌다. 화부가 웃었다. 그리고 기관실 문을 비켜 줬다.`,
      ng:`삽을 받았는데 석탄이 젖었다. 퍼 넣자 화실에서 김이 터진다.<br><br>얼굴과 팔이 데었다. 화부가 삽을 빼앗아 간다. 서툰 손에 맡긴 자기 잘못이라고 한다.<br>기관실 문은 그대로 막혀 있다. 데인 자리가 부풀어 오른다. 시계는 04:31.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-28, mind:-12 } }
  ] }

]);

// ──────────────────────────────────────────
// 결속술사 (binder) · 마력
// ──────────────────────────────────────────
kJob('binder', 'B', [

{ at:'B', t:'잠긴 문 — 바늘 하나 들어갈 구멍',
  x:`문이 잠겼다. 저쪽에서 빗장 걸리는 소리가 났다. 이쪽에는 손잡이도 없다.<br><br>
    열쇠 구멍이 하나 있다. 바늘 하나 들어갈 만하다. 구멍으로 바람이 새어 나온다. 저쪽은 트인 데다.<br>
    복도 끝에서 발소리가 꺾여 들어온다. 서두르지 않는다. 서두를 필요가 없는 발소리다.<br><br>
    실은 바늘보다 가늘다. 결속술사는 그 사실을 오늘 처음 다르게 생각한다.`,
  o:[
    { l:'① 마력 실을 구멍에 밀어 넣어 저쪽 빗장을 감아 당긴다.', k:'bond', dc:21, cost:{ mana:22 },
      ok:`실 끝을 꼬아 빳빳하게 세웠다. 열쇠 구멍에 밀어 넣었다. 마력이 실을 타고 문 너머로 간다.<br><br>저쪽은 안 보인다. 실 끝이 대신 더듬는다. 차가운 쇠. 둥근 머리. 빗장이다. 한 바퀴 감고 당겼다. 한 칸. 두 칸. 철컥.<br>문이 열렸다. 발소리가 모퉁이를 돌기 직전이었다.<br><br>실은 묶는 것이었다. 오늘은 손가락이었다. 안 보이는 데서 무언가를 쥐고 당기는 손가락. 손목에서 그 감각이 한참 안 빠졌다.`,
      ng:`실이 구멍 안에서 꺾였다. 다시 밀었다. 마력이 실 끝에서 흩어진다.<br><br>발소리가 모퉁이를 돌았다. 손전등이 이쪽 손등에 닿는다. 실을 거두며 옆 계단으로 뛰었다.<br>난간에 손목을 긁혔다. 실이 감겨 있던 자리다. 한참 저렸다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-22, mind:-14 }, wake:1 },
    { l:'② 문 아래 틈으로 실을 흘려 저쪽을 더듬는다.', k:'sense', dc:20,
      ok:`문 밑 틈으로 실을 흘렸다. 실 끝이 바닥을 기어간다.<br><br>젖은 바닥. 신발 한 짝. 계단 첫 칸. 문 옆 벽을 더듬던 실이 무언가에 걸린다. 두꺼비집이다.<br>실로 스위치를 내렸다. 복도 불이 다 나갔다. 발소리가 멈췄다. 어둠 속에서 문을 더듬었다. 경첩 핀이 헐겁다. 뽑았다.`,
      ng:`실 끝이 저쪽 바닥을 기어가는데 무언가 실을 밟는다.<br><br>밟고 안 놓는다. 저쪽에도 누가 있다. 실을 끊는 순간 손목이 홱 당겨졌다. 문짝에 얼굴을 박았다.<br>저쪽 사람이 실 끝을 쥐고 있다. 이쪽 손목이 어디 있는지 이제 안다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-24, spirit:-12 } }
  ] },

{ at:'B', t:'긴 복도 — 실을 거는 높이',
  x:`긴 복도다. 등이 한 칸 걸러 꺼졌다. 뒤에서 발소리가 따라온다. 거리가 줄지도 늘지도 않는다.<br><br>
    쫓는 쪽은 서두르지 않는다. 이쪽이 먼저 지칠 걸 안다.<br>
    손목에 실이 다섯 가닥 감겨 있다. 하나를 풀어 복도에 걸 수 있다. 발목 높이로.<br><br>
    아니면 저것 발목에 직접 감을 수도 있다.`,
  o:[
    { l:'① 실을 발목 높이로 복도에 가로질러 건다.', k:'fix', dc:20,
      ok:`등이 꺼진 칸에 실을 걸었다. 벽 배관에서 맞은편 문고리까지. 발목 높이. 팽팽하게.<br><br>모퉁이를 돌아 숨을 죽였다. 발소리가 온다. 일정하다. 그러다 끊긴다. 무거운 것이 바닥을 치는 소리.<br>다시 일어나는 데 오래 걸렸다. 그다음 발소리는 일정하지 않았다. 절뚝인다. 이제 거리가 벌어지기 시작한다.`,
      ng:`실을 거는데 꺼진 등이 켜진다. 이쪽 그림자가 복도에 길게 눕는다.<br><br>발소리가 처음으로 빨라졌다. 실을 다 못 걸고 뛰었다. 반쯤 걸린 실이 이쪽 발목에 감겼다. 넘어지며 턱을 바닥에 찧었다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-24, mind:-12 } },
    { l:'② 쫓는 것의 발목에 실을 감아 배관에 묶는다.', k:'bond', dc:21,
      doom:{ title:'묶인 쫓는 자', what:'실째로 끌려갑니다', dc:17, sec:55,
        text:`모퉁이에 붙어 기다렸다. 발이 보이는 순간 실을 던졌다. 발목에 감겼다. 끝을 배관에 묶었다.<br><br>발소리가 멈춘다. 그리고 다시 걷는다. 같은 박자로. 배관이 뜯겨 나온다. 실은 안 끊어졌다.<br>실은 양쪽을 다 묶는다. 저쪽 발목과 이쪽 손목. 저것이 한 걸음 걸을 때마다 이쪽이 한 걸음 끌려간다.<br><br>손목 매듭을 풀려는데 이쪽 쪽에서 조인다. 이쪽이 맨 매듭이다. 잘 맸다.`,
        dieText:`복도 끝으로 발소리가 멀어진다. 같은 박자로.<br><br>그 뒤로 무언가 끌리는 소리가 한참 따라갔다.<br>배관이 뜯긴 자리에 실 한 가닥이 남았다. 흐릿하게 빛나다가 꺼졌다.` },
      ok:`모퉁이에 붙어 기다렸다. 발이 보이는 순간 실을 던졌다. 발목에 감겼다. 끝을 배관에 묶었다. 이쪽 손목에서는 미리 풀어 두었다.<br><br>발소리가 멈춘다. 다시 걷는다. 배관이 운다. 버틴다. 저것이 처음으로 제 발목을 내려다본다.<br>그 사이 복도 끝 문을 지났다. 문을 닫으며 배관 뜯기는 소리를 들었다. 시간이 조금 남았다. 실 한 가닥 값이다.`,
      win:{ exp:22, dream:3 } }
  ] },

{ at:'B', t:'손목 — 여섯째 가닥',
  x:`계단을 내려오다 손목을 봤다. 실이 여섯 가닥이다.<br><br>
    팀은 다섯이다. 이쪽까지 다섯. 감은 것도 다섯이다.<br>
    여섯째 가닥이 팽팽하다. 어디론가 이어져 있다. 계단 아래. 아니면 팀원들 사이 어딘가.<br><br>
    누가 이쪽 손목에 실을 걸었다. 이쪽이 감지 않은 실이다.`,
  o:[
    { l:'① 실마다 한 번씩 당겨 돌아오는 대답을 듣는다.', k:'bond', dc:21,
      ok:`한 가닥씩 짧게 당겼다.<br><br>첫째가 돌아본다. 둘째가 손을 든다. 셋째는 소매를 당긴다. 넷째는 한 번 되당긴다. 다 다르다. 사람마다 당겨진 실에 대답하는 버릇이 있다.<br>여섯째를 당겼다. 되당기지 않는다. 대신 조금 느슨해진다. 다가오고 있다는 뜻이다. 계단 아래에서.<br><br>그 실을 끊고 뛰었다. 실은 매는 것만이 아니다. 당겨서 듣는 것이기도 하다. 다섯 가닥의 대답을 손목이 하나씩 외웠다.`,
      ng:`하나씩 당기는데 여섯째가 먼저 당긴다. 세게.<br><br>손목이 꺾이며 팔이 난간 밖으로 빨려 나갔다. 팀원 둘이 허리를 잡아 끌어올렸다.<br>여섯째 가닥은 그사이 풀려 사라졌다. 손목에 붉은 줄이 하나 더 남았다. 감은 적 없는 줄이다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-26, mind:-14 }, wake:1 },
    { l:'② 여섯째 가닥을 따라 내려가 본다.', k:'sense', dc:21,
      ok:`실을 손가락에 걸고 혼자 내려갔다. 팀원들은 위에 세웠다.<br><br>두 층 아래 계단참 기둥에 실이 묶여 있다. 기둥 뒤에 아무도 없다. 매듭 옆에 젖은 장갑 한 짝이 떨어져 있다.<br>매듭 모양이 서툴다. 실을 다룰 줄 모르는 손이 흉내 낸 매듭이다. 흉내 낼 줄 아는 것이 이쪽을 따라오고 있다. 그걸 알고 올라왔다.`,
      ng:`따라 내려가는데 실이 짧아진다. 저쪽에서 감고 있다.<br><br>멈췄다. 실이 계속 감긴다. 손목이 앞으로 끌린다. 계단 모서리에 정강이를 몇 번이나 찍으며 버텼다.<br>실을 이로 끊었다. 입안에 쇠 맛이 돌았다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-24, spirit:-13 } },
    { l:'③ 여섯째 가닥을 바로 끊는다.', k:'break', dc:20,
      ok:`생각하지 않았다. 손톱으로 끊었다.<br><br>끊긴 실이 계단 아래로 휙 빨려 내려간다. 저쪽에서 당기고 있었다.<br>팀원들을 세어 봤다. 다섯. 손목의 실도 다섯. 맞는다. 끊고 나서야 맞았다.`,
      ng:`끊었는데 손목에서 실이 안 떨어진다. 끊긴 끝이 살에 파고들어 있다.<br><br>뽑아냈다. 피가 맺혔다. 남은 반 토막이 손목 안에서 한동안 욱신거렸다. 끊긴 쪽 끝은 계단 아래로 사라졌다.`,
      win:{ exp:14, dream:2 }, lose:{ hp:-20, spirit:-14 } }
  ] },

{ at:'B', t:'빈방 — 의자에 묶인 사람',
  x:`빈방 가운데 의자가 있다. 사람이 묶여 있다. 손목, 발목, 가슴. 밧줄이다.<br><br>
    입에 천이 물렸다. 눈이 이쪽을 본다. 살려 달라는 눈이다.<br>
    묶는 사람마다 매듭이 다르다. 이 매듭은 잘 묶었다. 너무 잘.<br><br>
    방문은 열려 있다. 아무도 지키지 않는다. 그게 제일 이상하다.`,
  o:[
    { l:'① 매듭을 하나씩 읽는다.', k:'gaze', dc:20,
      ok:`손목 매듭은 당기면 조인다. 발목도. 가슴 매듭만 다르다. 당기면 풀린다. 묶인 사람 손가락이 닿는 데에 끝이 나와 있다.<br><br>스스로 풀 수 있게 묶었다. 그런데 안 풀고 앉아 있다. 미끼다. 풀어 주러 다가가는 사람 등 뒤에서 문이 닫히게.<br>문 경첩 위에 줄이 걸려 있다. 의자 다리까지 이어진다. 손대지 않고 물러났다. 묶인 사람 눈이 바뀐다. 실망한 눈이다.`,
      ng:`매듭을 보려고 다가간 한 걸음이 너무 깊었다.<br><br>묶인 사람이 가슴 매듭을 스스로 당긴다. 의자가 뒤로 넘어간다. 의자 다리에 이어진 줄이 당겨지며 등 뒤 문이 닫혔다.<br>문을 어깨로 받아 열었다. 어깨가 빠지는 줄 알았다. 묶였던 사람은 이미 창밖으로 사라졌다.`,
      win:{ exp:18, dream:2, spirit:6 }, lose:{ hp:-26, mind:-12 } },
    { l:'② 다른 매듭은 두고 입의 천부터 푼다.', k:'bond', dc:21,
      ok:`입의 천만 풀었다.<br><br>묶인 사람이 숨을 몰아쉰다. 그리고 말한다. 자기를 풀면 문이 닫힌다고. 묶은 쪽이 그렇게 해 두었다고. 그 말을 못 하게 입을 막은 것이다.<br>의자 다리 줄을 먼저 끊고 문을 받쳐 두었다. 그다음 다 풀었다. 그 사람이 손목을 비비며 말한다. 남을 풀어 주는 사람이 이렇게 느린 건 처음 본다고.`,
      ng:`천을 푸는데 묶인 사람이 소리를 지른다. 크게. 누군가의 이름이다.<br><br>미끼였다. 부르면 오는 쪽이 있다. 복도 끝에서 발소리가 뛰어온다.<br>창으로 빠져나가다 깨진 유리에 팔뚝이 길게 그였다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-24, mind:-14 } }
  ] },

{ at:'B', t:'쉬는 자리 — 실을 풀어 달라는 팀원',
  x:`쉬는 자리에서 팀원 하나가 손목을 내민다. 실을 풀어 달라고 한다.<br><br>
    따로 가겠다고 한다. 다섯이 같이 다니면 눈에 띈다고. 혼자가 빠르다고.<br>
    그것도 맞는 말이다. 쫓는 쪽은 다섯을 쫓는다. 하나는 덜 쫓는다.<br><br>
    묶을 때 물었다. 풀 때도 물어야 한다.`,
  o:[
    { l:'① 풀어 주되 손목에 헐거운 고리 하나를 남긴다.', k:'bond', dc:20,
      ok:`실을 풀었다. 대신 그 사람 손목에 고리를 하나 남겼다. 헐겁다. 묶지 않았다.<br><br>이건 뭐냐고 묻는다. 당기면 이쪽 손목으로 이어지는 고리라고 했다. 안 당기면 아무것도 아니라고.<br>그 사람이 혼자 갔다. 한 시간 뒤 손목이 짧게 한 번 당겨졌다. 실을 따라가니 그 사람이 막다른 계단에 웅크리고 있었다.<br><br>묶는 건 이쪽이 했다. 잇는 건 저쪽이 골랐다. 고를 수 있게 남겨 둔 실이 더 질기다. 손가락에 새 매듭이 하나 생겼다.`,
      ng:`풀어 주자 그 사람이 손목을 비비며 고맙다고 한다. 그리고 다른 팀원들 짐에서 말린 고기를 다 챙긴다.<br><br>말릴 새도 없이 갔다. 따로 가겠다던 건 핑계였다. 처음부터 짐이었다.<br>남은 넷이 빈 짐을 내려다봤다. 아무도 이쪽을 탓하지 않았다. 그게 더 무거웠다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-16, spirit:-15 }, wake:1 },
    { l:'② 못 푼다고 하고 진짜 이유를 묻는다.', k:'gaze', dc:21,
      ok:`못 푼다고 했다. 대신 진짜 이유를 말하면 생각해 보겠다고.<br><br>그 사람이 한참 있다 말한다. 아까 실이 당겨질 때 무서웠다고. 묶인 게 아니라 끌려가는 것 같았다고.<br>그 사람 실만 길게 늘였다. 다섯 걸음만큼. 그만큼은 혼자 걷게. 그 사람이 고개를 끄덕였다. 무서운 건 실이 아니라 짧은 실이었다.`,
      ng:`못 푼다고 하자 그 사람 얼굴이 굳는다. 이건 묶은 게 아니라 잡아 둔 거라고 한다.<br><br>그 사람이 손톱으로 실을 끊었다. 그 사람 손목에서 피가 난다. 이쪽 손목에서도 났다. 실은 양쪽이 같이 아프다.<br>그 사람은 따로 갔다. 다시 만나지 못했다.`,
      win:{ exp:18, dream:2, mind:6 }, lose:{ hp:-20, spirit:-16 } }
  ] },

{ at:'B', t:'비상계단 — 젖은 난간 밖의 손',
  x:`비상계단 난간이 젖었다. 쇠가 빗물에 미끄럽다.<br><br>
    팀원 하나가 난간 밖으로 미끄러졌다. 두 손으로 난간 끝을 붙들고 매달려 있다. 아래는 어둡다. 네온 간판 하나가 까마득히 깜빡인다.<br>
    손목의 실이 팽팽하다. 실 하나로는 사람 무게를 못 버틴다. 마력을 부으면 버틸지도 모른다.<br><br>
    위층에서 문 열리는 소리가 났다.`,
  o:[
    { l:'① 마력을 실에 부어 끌어올린다.', k:'bond', dc:21, cost:{ mana:26 },
      doom:{ title:'젖은 난간', what:'난간 너머로 끌려 떨어집니다', dc:17, sec:55,
        text:`실에 마력을 부었다. 실이 굵어진다. 손목에 감고 뒤로 몸을 젖혔다.<br><br>팀원이 한 뼘 올라온다. 그때 실이 아래로 한 번 더 당겨진다. 팀원 무게가 아니다. 팀원 발목에 무언가 매달렸다. 아래 어둠에서 올라온 손이다.<br>실은 안 끊는 게 일이다. 끊으면 팀원이 떨어진다. 안 끊으면 이쪽이 난간을 넘는다.<br><br>젖은 난간에 배가 걸렸다. 발이 바닥에서 뜬다.`,
        dieText:`실은 끝까지 안 끊어졌다.<br><br>까마득히 아래 네온 간판이 한 번 크게 깜빡였다. 그리고 다시 같은 박자로.<br>비상계단 난간에 손자국이 둘 남았다. 빗물이 금방 지웠다.` },
      ok:`실에 마력을 부었다. 실이 굵어진다. 손목에 감고 뒤로 몸을 젖혔다.<br><br>팀원이 한 뼘씩 올라온다. 손목 살이 실에 갈린다. 다른 팀원이 이쪽 허리를 잡았다. 셋이 한 줄이 됐다.<br>팀원이 난간을 넘어 들어왔다. 다 같이 젖은 계단에 쓰러졌다. 위층 문소리가 내려오기 전에 일어나 뛰었다.<br><br>손목에 실 자국이 깊다. 버틴 건 실이 아니라 손목이다.`,
      win:{ exp:24, dream:3 } },
    { l:'② 실을 난간 기둥에 감아 팀원이 스스로 올라오게 한다.', k:'fix', dc:20,
      ok:`실 끝을 난간 기둥에 감았다. 다른 끝을 팀원 손목에. 이쪽 손목에는 안 감았다.<br><br>팀원이 실을 잡고 발을 벽에 붙였다. 한 걸음씩 걸어 올라온다. 무게는 사람이 아니라 기둥이 진다.<br>올라온 팀원이 숨을 몰아쉬며 묻는다. 왜 손목에 안 감았냐고. 둘 다 떨어질까 봐. 그 대답에 팀원이 웃었다.`,
      ng:`기둥에 감는데 실이 빗물에 미끄러진다. 한 바퀴가 풀렸다.<br><br>팀원이 반 길 떨어져 아래층 난간에 걸렸다. 갈비뼈가 쇠에 부딪는 소리가 났다.<br>내려가 끌어올렸다. 숨 쉴 때마다 그 팀원이 얼굴을 찡그린다. 위층 문소리가 가까워졌다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-26, mind:-12 } }
  ] },

{ at:'B', t:'깨어 보니 — 남과 채워진 수갑',
  x:`팀원 하나가 깨어 보니 손목에 수갑이 채워져 있다. 다른 쪽 고리는 낯선 사람 손목에 있다.<br><br>
    낯선 사람은 아직 잔다. 아니면 자는 척한다. 외투가 젖었다. 구두는 말랐다.<br>
    열쇠는 없다. 시계는 간다. 사슬은 짧다. 팔 하나 길이.<br><br>
    쇠로 묶은 것도 묶은 것이다. 묶은 것은 다 풀 수 있다.`,
  o:[
    { l:'① 마력 실을 잠금쇠에 넣어 수갑을 연다.', k:'fix', dc:21, cost:{ mana:24 },
      ok:`실 끝을 꼬아 잠금쇠 구멍에 넣었다. 안쪽 톱니를 하나씩 셌다. 셋째 톱니에 실을 걸고 비틀었다. 딸깍.<br><br>팀원 쪽 고리가 열렸다. 빈 고리를 침대 다리에 채웠다. 낯선 사람 쪽은 그대로 두었다.<br>조용히 일어섰다. 문을 닫는데 낯선 사람이 눈을 뜬다. 자기 손목과 침대 다리를 본다. 웃는다. 이제 누가 묶였는지 아는 웃음이다.`,
      ng:`실을 넣고 비트는데 톱니가 실을 문다. 안 놓는다.<br><br>마력이 실을 타고 새어 나간다. 끊었다. 잠금쇠 안에 실 끝이 남았다. 그 사이 낯선 사람이 눈을 떴다.<br>사슬을 당긴다. 팀원이 끌려간다. 셋이 달려들어 겨우 붙잡았다. 손목들이 다 쇠에 긁혔다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-24, mind:-14 } },
    { l:'② 낯선 사람 손목에도 실을 감아 일행으로 묶어 데려간다.', k:'bond', dc:21,
      ok:`수갑은 안 풀었다. 대신 낯선 사람 손목에 실을 감았다. 여섯째 가닥으로.<br><br>그 사람이 눈을 뜨고 실을 내려다본다. 쇠는 자기가 채웠다. 실은 남이 감았다. 실은 쇠와 다르다. 당기면 안다. 어디로 가려는지, 언제 멈추는지.<br>같이 걸었다. 그 사람이 두 번 다른 길로 새려 했다. 두 번 다 손목이 먼저 알았다. 세 번째 갈림길에서 그 사람이 열쇠를 꺼내 수갑을 풀었다. 이쪽 실이 더 귀찮았던 것이다.<br><br>남을 묶어 일행으로 들였다. 묶어 둔 쪽이 오히려 묶인다. 손목이 그 법을 하나 익혔다.`,
      ng:`실을 감자 그 사람이 눈을 뜨고 실을 쥔다. 거꾸로 당긴다. 이쪽 손목이 그 사람 쪽으로 끌려간다.<br><br>이제 셋이 묶였다. 쇠로 하나, 실로 하나. 그 사람이 일어나 걷는다. 다 같이 끌려간다.<br>실을 끊었다. 손목이 찢어졌다. 팀원은 그 사람과 같이 문밖으로 끌려 나가다 문틀을 붙들었다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-26, spirit:-14 }, wake:1 },
    { l:'③ 낯선 사람 얼굴을 들여다본다.', k:'gaze', dc:20,
      ok:`눈꺼풀이 떨리지 않는다. 숨이 너무 고르다. 자는 척이다.<br><br>그런데 손이 다르다. 수갑 찬 손목 안쪽에 오래된 자국이 있다. 이 사람도 전에 누군가와 채워졌다. 같은 수갑으로.<br>그 사람 귀에 대고 그 자국을 알아본다고 말했다. 눈꺼풀이 처음 떨린다. 주머니에서 열쇠를 꺼내 바닥에 놓고 다시 눈을 감았다.`,
      ng:`들여다보는데 그 사람이 눈을 뜬다. 코앞에서.<br><br>이마로 이쪽 코를 들이받았다. 코피가 터졌다. 그 사람은 다시 눈을 감는다. 아무 일 없던 것처럼.<br>열쇠는 끝내 없었다. 팀원이 그 사람을 반쯤 끌고 다음 방까지 갔다.`,
      win:{ exp:18, dream:2, spirit:6 }, lose:{ hp:-22, mind:-14 } }
  ] },

{ at:'B', t:'두 팀의 쉬는 자리 — 등을 찌르면 조이는 매듭',
  x:`다른 팀과 같이 쉬게 됐다. 서로 못 믿는다. 같이 가야 나갈 수 있는 길이다.<br><br>
    저쪽 반장이 결속술사를 알아본다. 매듭을 하나 매 달라고 한다. 누가 먼저 등을 찌르면 그 손목이 조이는 매듭.<br>
    그런 매듭은 있다. 매 본 적은 없다. 조이는 매듭은 누가 배신했는지 모른다. 손목만 안다.<br><br>
    두 팀이 손목을 내민다. 열 개.`,
  o:[
    { l:'① 배신하면 조이는 대신 넘어지면 조이는 매듭을 맨다.', k:'bond', dc:21,
      ok:`열 손목을 이었다. 누가 넘어지면 나머지 아홉 손목이 한꺼번에 조인다.<br><br>저쪽 반장이 이게 뭐냐고 묻는다. 누가 찌르는지는 손목이 몰라도 누가 넘어지는지는 안다고 했다. 넘어진 사람을 다 같이 알면 찌를 틈이 없다.<br>가는 동안 손목이 세 번 조였다. 세 번 다 누가 넘어졌다. 세 번 다 아홉이 돌아봤다. 아무도 등을 찌르지 않았다. 볼 눈이 너무 많았다.<br><br>벌주는 매듭 대신 돌아보게 하는 매듭. 처음 매 본 모양인데 손가락이 벌써 기억한다.`,
      ng:`매듭을 매는데 저쪽 반장이 손목을 뺀다. 배신 매듭이 아니면 싫다고.<br><br>판이 깨졌다. 두 팀이 같은 길을 따로 갔다. 좁은 데서 저쪽이 먼저 지나가려고 이쪽 팀원을 밀쳤다. 팀원이 계단 셋을 굴렀다.<br>매듭이 없으니 아무도 안 돌아봤다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-24, mind:-14 }, wake:1 },
    { l:'② 원하는 대로 조이는 매듭을 맨다.', k:'luck', dc:21,
      ok:`원하는 대로 맸다. 열 손목.<br><br>다들 길을 가는 내내 서로 손목만 본다. 누가 조일까. 아무도 안 조였다. 조일까 봐 아무것도 안 했다.<br>무사히 지났다. 다들 손목이 저렸다. 마음이 아니라 손목으로 지킨 판이다. 운이 좋았다.`,
      ng:`맸다. 한 시간쯤 지나 이쪽 팀원 손목이 조였다. 그 팀원은 아무것도 안 했다.<br><br>자다가 몸을 뒤척였을 뿐이다. 저쪽이 칼을 뽑았다. 배신자라고. 매듭은 이유를 말해 주지 않는다.<br>떼어 놓다가 팔뚝이 베였다. 칼로 매듭을 끊었다. 열 손목에서 동시에 피가 났다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-26, spirit:-14 } }
  ] },

{ at:'B1', t:'3번 창고 — 숨 쉬는 소금 자루',
  x:`창고 구석에 자루가 쌓였다. 생선 절이는 소금 자루다. 끈으로 아가리를 묶었다.<br><br>
    그중 하나가 부풀었다 꺼진다. 아주 느리게. 숨 쉬는 박자다.<br>
    결속술사는 끈부터 본다. 다른 자루는 하역부 매듭이다. 굵고 투박하다. 이 자루만 다르다. 얇고 단정하다. 끝을 가위로 잘랐다.<br><br>
    멀리서 고무장화가 뽀득, 하고 운다.`,
  o:[
    { l:'① 단정한 매듭을 소리 없이 거꾸로 짚어 푼다.', k:'bond', dc:21,
      ok:`매듭이 단정한 만큼 순서도 단정하다. 손톱으로 끝을 들고 거꾸로 짚어 풀었다.<br><br>자루 안에서 사람이 나온다. 하역부 옷이다. 입이 테이프로 막혔다. 눈이 이쪽을 보고 바로 셔터 쪽을 본다. 그쪽에서 온다는 뜻이다.<br>자루에 소금을 채워 다시 묶었다. 같은 단정한 매듭으로. 숨 쉬는 박자는 없다. 무게는 같다.<br><br>나중에 그 하역부가 소금 덩이 하나를 쥐여 줬다. 자루 안에서 쥐고 있던 것이다.`,
      ng:`푸는데 매듭 안쪽에 실 하나가 더 숨어 있다. 그게 당겨지며 자루 위 깡통이 떨어진다.<br><br>깡통 소리가 창고를 굴러간다. 고무장화 소리가 멈췄다. 그리고 빨라졌다.<br>자루째 끌고 상자 뒤로 숨었다. 상자 모서리에 등을 갈았다. 단정한 매듭에는 단정하게 덫까지 달려 있었다.`,
      win:{ exp:22, dream:3, item:'소금 덩이' }, lose:{ hp:-24, mind:-13 } },
    { l:'② 매듭 속으로 실 한 가닥을 흘려 안을 읽는다.', k:'gaze', dc:20,
      ok:`실 한 가닥을 매듭 틈에 흘렸다. 끈을 타고 자루 안으로.<br><br>사람이다. 살아 있다. 다친 데는 없다. 그런데 손이 안 묶였다. 스스로 들어간 것이다. 숨으려고. 밖에서 묶어 준 사람이 따로 있다.<br>매듭을 건드리지 않았다. 자루 옆에 말린 고기 한 점을 놓았다. 자루 숨이 한 번 멎었다가 이어진다. 들었다는 뜻이다.`,
      ng:`실을 흘렸는데 안에서 무언가 실을 쥔다. 차다.<br><br>사람 손이 아니다. 실을 타고 냉기가 올라온다. 손목이 하얗게 언다. 실을 끊었다.<br>그 자루는 숨을 멈췄다. 처음부터 숨 쉬는 척이었다. 손목이 한참 녹지 않았다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-22, spirit:-14 } }
  ] },

{ at:'B1', t:'방파제 수로 — 창살 쪽으로 쓸려 가는 팀원',
  x:`방파제 수로로 내려왔다. 물이 허리까지 온다. 물살이 바다 쪽으로 당긴다.<br><br>
    앞서 가던 팀원이 미끄러졌다. 물살에 쓸려 간다. 그 앞에 쇠창살이 있다. 물은 창살 사이로 빠지고 사람은 걸린다. 걸리면 물 밑으로 눌린다.<br>
    팀원까지 열 걸음.<br><br>
    실은 물에 약하다. 마력을 부으면 조금 덜 약하다.`,
  o:[
    { l:'① 마력을 부은 실을 던져 팀원을 감아 붙든다.', k:'bond', dc:22, cost:{ mana:26 },
      doom:{ title:'창살 밑', what:'창살 밑 물속으로 끌려 들어갑니다', dc:17, sec:50,
        text:`실에 마력을 부어 던졌다. 팀원 허리에 감겼다. 당겼다.<br><br>팀원이 멈춘다. 대신 물살이 실을 당긴다. 이쪽 발이 바닥에서 미끄러진다. 수로 바닥이 이끼다.<br>둘이 같이 쓸려 간다. 창살이 다가온다. 팀원 먼저, 이쪽이 그 뒤에.<br><br>창살에 등이 닿았다. 물이 머리 위로 넘어온다.`,
        dieText:`수로의 물은 바다로 간다.<br><br>창살 앞에 실 두 가닥이 엉켜 있다. 마력이 다 빠져 흐릿하다. 물살이 그걸 오래 흔들었다.<br>팀원은 다른 팀원들이 창살에서 떼어 냈다. 이쪽은 실 끝을 끝내 안 놓았다.` },
      ok:`실에 마력을 부어 던졌다. 팀원 허리에 감겼다. 다른 끝을 수로 벽 쇠사다리에 감았다. 이쪽 손목 말고.<br><br>팀원이 멈춘다. 물살이 실을 당긴다. 사다리가 운다. 버틴다. 실이 사람 대신 쇠를 붙들었다.<br>팀원이 실을 잡고 거슬러 왔다. 한 뼘씩. 창살 바로 앞에서 돌아섰다.<br><br>사다리에 실을 감던 손을 손목이 기억한다. 무게는 묶은 사람이 아니라 묶어 둔 데가 진다.`,
      win:{ exp:24, dream:4 } },
    { l:'② 남은 넷의 손목을 이어 수로를 가로막고 선다.', k:'fix', dc:21,
      ok:`남은 넷 손목을 실로 이었다. 수로를 가로질러 섰다. 벽에서 벽까지.<br><br>쓸려 오던 팀원이 사슬에 걸렸다. 넷이 동시에 휘청였다. 버텼다. 물이 다섯을 한 덩어리로 민다.<br>천천히 벽으로 옮겨 갔다. 다 사다리를 잡았을 때 손목마다 붉은 줄이 났다. 같은 굵기로.`,
      ng:`사슬로 섰는데 쓸려 온 팀원 무게에 맨 끝 사람이 넘어졌다.<br><br>다섯이 다 물에 잠겼다. 실로 이어져 있어서 다 같이. 창살 바로 앞에서 사다리를 잡았다.<br>물을 너무 먹었다. 한참 짠물을 토했다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-28, mind:-12 } }
  ] },

{ at:'B1', t:'컨테이너 야적장 — 철사 봉인',
  x:`컨테이너 문에 철사 봉인이 감겨 있다. 납 덩이에 번호가 찍혔다. 뜯으면 표가 난다.<br><br>
    안에서 두드리는 소리가 난다. 약하게. 셋, 쉼, 셋.<br>
    탐조등이 야적장을 한 바퀴 도는 데 숨 마흔. 문을 열고 닫기엔 충분하다. 뜯은 자국을 숨기기엔 모자라다.<br><br>
    결속술사에게는 철사도 매듭이다. 감은 것은 풀고 다시 감을 수 있다.`,
  o:[
    { l:'① 봉인 철사를 풀고 똑같은 모양으로 다시 감는다.', k:'bond', dc:21,
      ok:`철사 감긴 순서를 손끝으로 외웠다. 왼쪽 세 번, 꼬아서 두 번, 납 덩이 구멍으로 한 번. 그 반대로 풀었다.<br><br>문이 열렸다. 안에 사람 둘이 웅크리고 있다. 다른 팀이다. 끌어냈다. 문을 닫고 철사를 외운 대로 감았다. 마지막에 납 덩이 번호가 위로 오게.<br>탐조등이 돌아왔다. 봉인은 그대로다. 누가 열었는지 아무도 모른다.<br><br>푼 것을 푼 줄 모르게 다시 묶었다. 매듭은 흔적이 남는다. 매듭을 지운 자리는 안 남는다. 손끝이 그걸 한 번에 익혔다.`,
      ng:`풀다가 순서 하나를 놓쳤다. 다시 감은 철사가 반 바퀴 모자란다.<br><br>탐조등이 돌아와 문에 멈췄다. 오래. 노란 비옷 둘이 야적장을 가로질러 온다.<br>컨테이너 사이로 달렸다. 꺼낸 둘 중 하나가 철판 모서리에 다리를 찢었다. 업고 갔다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-25, mind:-14 }, wake:1 },
    { l:'② 문틈으로 실을 흘려 안을 먼저 더듬는다.', k:'sense', dc:20,
      ok:`문틈으로 실을 흘렸다. 안이 넓다. 사람이 둘. 숨이 둘 다 약하다.<br><br>그리고 셋째가 있다. 숨이 없다. 문 바로 안쪽에 서 있다. 문이 열리면 제일 먼저 닿는 자리.<br>철사를 안 풀었다. 컨테이너 뒤쪽 환기구에 실을 넣었다. 두 사람 손목에 감아 그쪽으로 끌어냈다. 셋째는 문 앞에서 아직 기다린다.`,
      ng:`실이 안을 더듬다 무언가에 감긴다. 실을 타고 무게가 온다.<br><br>손목이 문틈에 끼었다. 철판이 살을 문다. 실을 끊고 손을 뺐다. 손목뼈가 울렸다.<br>안의 두드림이 그쳤다. 이쪽 손목이 대신 두드리듯 욱신거렸다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-24, spirit:-13 } }
  ] },

{ at:'B1', t:'해무호 선착장 — 풀려 나가는 계류줄',
  x:`해무호가 부두에서 떨어지기 시작한다. 고동이 한 번 운다.<br><br>
    계류줄 하나가 말뚝에서 풀려 나간다. 갑판에서 누가 마지막 줄을 감는다. 선체와 부두 사이가 한 뼘씩 벌어진다.<br>
    팀은 아직 부두에 있다. 갑판 난간까지 두 걸음. 곧 세 걸음이 된다.<br><br>
    배를 붙든 줄은 이제 하나다.`,
  o:[
    { l:'① 마력 실로 계류줄을 말뚝에 다시 묶어 붙든다.', k:'steady', dc:21, cost:{ mana:28 },
      ok:`실을 풀린 계류줄 끝에 던졌다. 감겼다. 다른 끝을 말뚝에 여덟 자로 감았다. 마력을 부었다.<br><br>배가 멈칫한다. 엔진이 운다. 실이 빛나며 떤다. 숨 열.<br>그 열 사이에 다섯이 다 뛰었다. 이쪽이 마지막이다. 실을 놓는 순간 배가 미끄러졌다. 갑판 난간을 잡았다. 발끝이 물에 닿았다 올라왔다.`,
      ng:`실을 감았는데 배 힘이 실보다 세다. 말뚝 위에서 실이 미끄러진다.<br><br>실이 끊어지며 손목을 채찍처럼 쳤다. 살이 터졌다. 배는 한 뼘 더 멀어졌다.<br>팀원들이 이쪽을 끌고 뛰었다. 마지막 사람은 난간에 매달려 끌어올려졌다. 무릎이 선체에 갈렸다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-28, mind:-12 } },
    { l:'② 다섯 손목을 한 줄로 이어 한꺼번에 뛴다.', k:'bond', dc:21,
      ok:`다섯 손목을 이었다. 하나, 둘, 셋에 다 같이 뛰었다.<br><br>앞의 셋이 난간을 넘었다. 넷째가 모자랐다. 다섯째인 이쪽은 더 모자랐다. 그런데 실이 있다. 넘어간 셋이 당겼다. 둘이 허공에서 갑판으로 끌려 들어갔다.<br>혼자 뛰는 거리와 다섯이 뛰는 거리는 다르다. 실이 그 차이를 메웠다.`,
      ng:`하나, 둘에 한 사람이 먼저 뛰었다. 박자가 어긋났다.<br><br>실이 엉켜 둘이 부두 끝에서 넘어졌다. 하나가 물 쪽으로 미끄러지자 다들 실째 끌려갔다. 부두 모서리를 겨우 잡았다.<br>다시 뛰었다. 이번엔 박자가 맞았다. 다들 정강이가 피투성이였다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-26, spirit:-13 } }
  ] },

{ at:'B2', t:'처치실 — 스스로 채운 억제대',
  x:`처치실 침대에 사람이 누워 있다. 손목, 발목, 허리에 억제대가 채워졌다. 가죽 띠에 쇠 버클.<br><br>
    그 사람이 이쪽을 보고 고개를 젓는다. 풀지 말라는 뜻이다.<br>
    결속술사는 버클 방향을 본다. 남이 채운 억제대는 버클이 침대 바깥쪽을 향한다. 이건 안쪽이다.<br><br>
    스스로 채웠다. 왜 그랬는지 물어야 한다.`,
  o:[
    { l:'① 허리 버클 하나만 풀고 이유를 묻는다.', k:'bond', dc:21,
      ok:`허리 버클 하나만 풀었다. 그 사람이 숨을 크게 쉰다. 그리고 말한다.<br><br>정각에 묶여 있는 사람은 안 데려간다고. 데려가려면 침대째 밀고 가야 하는데 바퀴가 다 빠졌다고. 자기가 뺐다고.<br>버클을 다시 채워 줬다. 더 단단히. 나가면서 봤다. 침대 밑에 바퀴 넷이 가지런히 놓여 있다. 그 옆에 생수 한 병. 그 사람이 턱으로 가리킨다. 가져가라고.`,
      ng:`버클 하나를 풀자 그 사람이 비명을 지른다. 다시 채우라고.<br><br>비명에 복도 끝 딸깍 소리가 멈춘다. 다시 채우는 손이 떨려 버클이 안 맞는다. 커튼 뒤로 숨었다.<br>들어온 간호사가 침대를 오래 본다. 커튼 밑으로 이쪽 신발 끝이 나와 있었다. 겨우 당겨 넣었다. 심장이 귀에서 뛰었다.`,
      win:{ exp:20, dream:2, item:'맑은 물' }, lose:{ mind:-16, spirit:-15 } },
    { l:'② 가죽 띠에 남은 구멍 자국을 읽는다.', k:'gaze', dc:20,
      ok:`가죽 띠 구멍마다 늘어난 정도가 다르다.<br><br>밤마다 한 칸씩 조였다. 무언가 밤마다 조금 더 세게 끌었다는 뜻이다. 이 사람은 그만큼 더 조여서 버텼다.<br>마지막 구멍까지 왔다. 더 조일 칸이 없다. 오늘 밤이 마지막이다. 그 사람 손목 옆에 실 한 가닥을 감아 침대 다리에 묶어 줬다. 구멍 하나 몫이다.`,
      ng:`읽는데 가죽 띠가 저절로 한 칸 조인다. 그 사람이 숨을 들이켠다.<br><br>무언가 지금 끌고 있다. 침대 반대편 커튼 밑으로 하얀 신발이 보인다. 젖지 않았다.<br>뒷걸음질 치다 약품 수레를 쓰러뜨렸다. 유리병이 깨지며 정강이에 박혔다.`,
      win:{ exp:18, dream:2, spirit:6 }, lose:{ hp:-22, mind:-14 } }
  ] },

{ at:'B2', t:'세탁실 — 시트로 꼰 줄',
  x:`세탁실 창은 철망이 반쯤 떨어져 있다. 밖은 비다. 창 아래로 빨래 건조대 철골이 이어진다. 두 층 아래가 지붕이다.<br><br>
    다림질된 시트가 선반에 쌓여 있다. 빳빳하다. 꼬면 줄이 된다.<br>
    문제는 매듭이다. 시트 매듭은 젖으면 미끄러진다. 밖은 비다.<br><br>
    세탁기 드럼 하나가 혼자 돈다. 안에 든 것이 무겁게 부딪친다.`,
  o:[
    { l:'① 시트를 꼬고 매듭마다 마력을 부어 굳힌다.', k:'bond', dc:21, cost:{ mana:24 },
      ok:`시트를 셋씩 꼬았다. 매듭마다 실 한 가닥을 감고 마력을 부었다. 빳빳한 천이 더 빳빳해진다.<br><br>창틀에 묶고 던졌다. 빗속으로 흰 줄이 늘어진다. 한 사람씩 내려갔다. 젖어도 매듭이 안 미끄러진다.<br>마지막으로 내려와 줄을 당겼다. 위쪽 매듭 하나가 풀려 줄이 통째로 떨어진다. 그렇게 묶어 두었다. 따라 내려올 줄은 남기지 않는다.`,
      ng:`마력을 부었는데 다림질 열이 남은 시트가 마력을 먹는다. 매듭이 축축하게 풀어진다.<br><br>둘째가 내려가다 매듭이 빠졌다. 건조대 철골에 떨어졌다. 철골이 크게 운다.<br>드럼 돌던 소리가 멈췄다. 남은 사람들은 줄 없이 철골을 타고 내려갔다. 손바닥이 녹에 갈렸다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-26, mind:-12 } },
    { l:'② 줄 대신 다섯 손목을 이어 철골을 탄다.', k:'fix', dc:21,
      ok:`줄은 포기했다. 손목을 이었다. 한 사람이 내려서는 동안 위의 넷이 실로 버틴다. 하나씩.<br><br>셋째가 한 번 미끄러졌다. 넷이 동시에 손목을 뒤로 젖혔다. 멈췄다.<br>지붕에 다섯이 내려섰다. 위 세탁실 창에서 흰 모자가 내려다본다. 줄이 없으니 따라 내려오지 못한다.`,
      ng:`손목을 이었는데 첫째가 미끄러지자 넷이 다 창틀에 부딪쳤다. 실이 짧았다.<br><br>창틀 쇠가 가슴을 쳤다. 숨이 막혔다. 버티며 실을 늘렸다. 첫째는 철골에 매달려 한참 기다렸다.<br>너무 오래 걸렸다. 위 창에 흰 모자가 나타났다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-24, spirit:-14 } }
  ] },

{ at:'B2', t:'정각 점검 — 실도 세어진다',
  x:`정각이다. 간호사가 병실 문 앞에 선다. 계수기를 쥐었다.<br><br>
    딸깍. 딸깍. 머리 하나에 한 번. 그런데 이쪽 앞에서 엄지가 멈추지 않는다. 딸깍, 딸깍, 딸깍.<br>
    간호사 눈이 이쪽 손목을 본다. 실이 감긴 손목. 다섯 가닥.<br><br>
    실 끝마다 사람이 있다. 계수기는 실을 센다.`,
  o:[
    { l:'① 빈 침대 이불에 실 한 가닥을 이어 둔다.', k:'bond', dc:21, cost:{ mana:22 },
      ok:`손을 등 뒤로 돌려 실 한 가닥을 뽑았다. 빈 침대 이불에 끝을 묶었다. 마력을 조금 실었다.<br><br>간호사 엄지가 빈 침대 앞에서 내려간다. 딸깍. 이불 속에 아무도 없는데. 실 끝이 거기 있다.<br>숫자가 맞았다. 간호사가 지나갔다.<br><br>실 끝에 사람이 없어도 실이 사람 자리가 된다. 묶어 둔 자리가 거기 누가 있다고 대신 말한다. 실을 남겨 두는 법이 하나 새로 생겼다.`,
      ng:`실을 뽑는 손이 간호사 눈에 걸렸다.<br><br>계수기가 멈춘다. 간호사가 다가와 이쪽 손목을 든다. 차가운 손가락으로 실을 하나씩 짚는다. 한 가닥을 집어 끊었다.<br>끊긴 쪽 끝에서 팀원이 비틀거린다. 화이트보드에서 숫자 하나가 번진다. 다음 정각에 찾으러 올 이름이 하나 생겼다.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-17, spirit:-16 }, wake:1 },
    { l:'② 실을 손목 안쪽으로 감아 소매 속에 숨긴다.', k:'hide', dc:20,
      ok:`소매를 내리고 손목을 안으로 꺾었다. 실이 살 안쪽에 붙는다.<br><br>계수기가 한 번만 딸깍한다. 간호사가 지나간다.<br>소매 속에서 다섯 가닥이 땀에 젖었다. 다섯이 다 이쪽 맥박을 따라 뛴다. 숨긴 동안에도 이어져 있었다.`,
      ng:`감는데 실 한 가닥이 소매 밖으로 빠져나온다.<br><br>계수기가 그 한 가닥을 센다. 딸깍. 간호사가 수첩에 적는다. 하나가 많다.<br>다음 정각에 하나를 데리러 온다는 뜻이다. 누구를 데려갈지는 간호사가 정한다. 그때까지 손목이 계속 저렸다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-16, spirit:-14 } }
  ] },

{ at:'B2', t:'주방 — 음식 승강기 줄',
  x:`주방 벽에 음식 승강기가 있다. 상자 하나 크기. 줄로 오르내린다. 아래층 세탁실까지 간다.<br><br>
    사람 하나가 웅크리면 들어간다. 한 번에 하나.<br>
    줄은 도르래에 걸렸다. 내릴 때 누가 줄을 붙들어야 한다. 놓으면 떨어진다.<br><br>
    위층에서 무언가 줄을 당기고 있다. 아주 약하게.`,
  o:[
    { l:'① 마력 실로 줄을 붙들고 한 사람씩 내려보낸다.', k:'bond', dc:21, cost:{ mana:25 },
      doom:{ title:'음식 승강기', what:'줄째 위로 끌려 올라갑니다', dc:18, sec:50,
        text:`줄에 실을 감고 마력을 실었다. 첫째를 내렸다. 둘째. 셋째. 넷째.<br><br>이쪽 차례다. 상자에 들어가 실을 늦추며 내려가려는데 줄이 멈춘다. 그리고 올라간다.<br>위층에서 당긴다. 이제 약하지 않다. 실이 이쪽 손목에 감겨 있다. 줄과 같이.<br><br>상자가 주방을 지나 위로 간다. 7층 쪽으로. 손목에서 실이 안 풀린다.`,
        dieText:`음식 승강기는 정해진 층에 선다.<br><br>7층 배식구에서 상자 문이 열렸다. 다음 날 배식 수레에 식판이 하나 늘었다. 번호 스티커가 붙어 있었다.<br>아래층 넷은 그 줄을 오래 올려다봤다. 다시 내려오지 않았다.` },
      ok:`줄에 실을 감고 마력을 실었다. 한 사람씩 내렸다. 넷.<br><br>이쪽 차례다. 실을 도르래 축에 묶어 두고 상자에 들어갔다. 줄은 실이 붙든다. 이쪽 손은 비었다.<br>위에서 당기는 힘이 세졌다. 실이 버틴다. 그 사이 상자가 내려간다. 바닥에 닿자마자 실을 끊었다. 줄이 휙 위로 사라졌다. 빈 상자만 올라갔다.`,
      win:{ exp:24, dream:3 } },
    { l:'② 줄을 끊고 승강기 통로 벽을 타고 내려간다.', k:'evade', dc:21,
      ok:`줄을 끊었다. 위에서 당기던 것이 헛당겨 넘어지는 소리가 났다.<br><br>통로 벽에 쇠 손잡이가 박혀 있다. 고치는 사람이 쓰던 것이다. 다섯이 차례로 내려갔다. 좁다. 무릎이 벽에 찧인다.<br>아래층 문을 밀고 나왔다. 끊긴 줄이 천천히 떨어져 내려온다. 끝이 이쪽 발 앞에 닿았다.`,
      ng:`줄을 끊자 상자가 떨어진다. 안에 먼저 들어가 있던 팀원과 같이.<br><br>한 층을 떨어져 바닥에 부딪혔다. 큰 소리가 났다. 팀원이 무릎을 다쳤다. 통로를 타고 내려가 끌어냈다.<br>다들 손바닥이 쇠 손잡이에 까졌다. 위에서 딸깍 소리가 내려온다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-26, mind:-13 } }
  ] },

{ at:'B3', t:'식당칸 — 식탁보 밑의 발목',
  x:`식당칸 식탁마다 손님이 앉아 수프를 떠먹는다. 한 숟가락씩. 다 같은 박자로.<br><br>
    팀원 하나가 빈자리에 앉았다. 다리가 아프다고. 그리고 못 일어난다.<br>
    식탁보 밑을 봤다. 손님들 발목이 의자 다리에 묶여 있다. 가는 끈이다. 팀원 발목에도 벌써 한 바퀴 감겼다. 끈이 스스로 감았다.<br><br>
    급사가 냅킨을 접으며 이쪽을 본다.`,
  o:[
    { l:'① 냅킨을 줍는 척하며 식탁보 밑 끈을 푼다.', k:'bond', dc:21,
      ok:`냅킨을 떨어뜨리고 몸을 숙였다. 식탁보 밑으로 손을 넣었다.<br><br>끈에 매듭이 없다. 감기기만 했다. 감긴 반대로 한 바퀴 풀었다. 끈이 버둥거리며 다시 감으려 한다. 끝을 의자 다리에 대신 감아 줬다. 의자는 일어서지 않는다.<br>팀원이 일어섰다. 급사가 다가와 빈 의자를 본다. 다리에 끈이 감겨 있다. 급사는 만족한 얼굴로 냅킨을 놓고 갔다.`,
      ng:`손을 넣는데 끈이 이쪽 손목을 감는다. 빠르다.<br><br>식탁보 밑에서 손님들 발이 일제히 이쪽을 향한다. 수프 뜨는 박자가 멈췄다.<br>손목을 비틀어 뺐다. 살갗이 끈에 쓸려 벗겨졌다. 팀원은 의자째 끌어냈다. 의자 다리가 부러지며 팀원 발목에 끈 자국이 깊게 남았다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-24, mind:-14 } },
    { l:'② 마력 실을 끈에 엮어 끈이 어디서 당기는지 더듬는다.', k:'fix', dc:21, cost:{ mana:23 },
      ok:`실 한 가닥을 식탁보 밑으로 흘려 끈에 엮었다. 마력이 끈을 타고 들어간다.<br><br>끈이 멈춘다. 실이 감는 힘을 거슬러 더듬는다. 바닥 밑. 바퀴 쪽. 끈은 열차가 감고 있었다.<br>실로 바닥 쪽 끈을 끊었다. 당기는 힘이 끊기자 끈은 그냥 끈이 된다. 팀원이 일어섰다. 다른 손님들은 그대로 수프를 떠먹는다. 그들 끈까지는 끊지 못했다.`,
      ng:`마력이 끈에 들어가자 끈이 마력을 마신다. 식당칸 불빛이 한 번 밝아진다.<br><br>손님들이 동시에 고개를 든다. 실이 끈 쪽으로 빨려 간다.<br>실을 끊었다. 머리가 텅 빈다. 팀원을 끌어낼 때 다리에 힘이 하나도 없었다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-16, spirit:-15 } },
    { l:'③ 팀원 의자를 통째로 들고 나간다.', k:'steady', dc:20,
      ok:`의자째 들었다. 끈은 의자 다리에 묶였다. 의자를 들면 끈도 따라온다.<br><br>연결부까지 의자를 들고 갔다. 거기서 의자 다리를 부러뜨렸다. 끈이 다리 토막을 감은 채 남았다.<br>팀원이 발목을 주무른다. 뒤에서 급사가 의자 하나가 비었다고 혼잣말을 한다. 다음 손님을 기다리는 얼굴이다.`,
      ng:`드는데 의자가 바닥에 붙어 있다. 의자도 묶였다.<br><br>힘을 쓰다 허리가 삐끗했다. 급사가 다가와 정중하게 말한다. 손님, 식사 중에 일어나시면 안 됩니다.<br>칼로 팀원 발목의 끈을 끊어 냈다. 끈과 살 사이가 좁아 피가 났다. 둘 다 절뚝이며 식당칸을 나왔다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-26, mind:-12 } }
  ] },

{ at:'B3', t:'2호차 — 느슨해진 입마개',
  x:`화물칸에 개 여섯 마리가 엎드려 있다. 입마개를 했다. 가죽 끈에 쇠 고리.<br><br>
    추적견이다. 냄새를 맡으면 안 놓는다. 지금은 잔다.<br>
    입마개 끈이 늘어졌다. 오래 써서. 하나는 고리가 반쯤 빠졌다. 잠결에 고개를 털면 빠진다.<br><br>
    칸 끝 문까지 개들 사이로 가야 한다.`,
  o:[
    { l:'① 마력 실로 늘어진 입마개 끈을 하나씩 조인다.', k:'bond', dc:21, cost:{ mana:24 },
      ok:`엎드린 개 옆에 쪼그려 앉았다. 실을 입마개 끈에 엮어 마력으로 한 칸 조였다. 개가 코를 씰룩인다. 안 깬다.<br><br>여섯을 다 조였다. 반쯤 빠진 고리는 실로 감아 붙였다. 그다음 개들 사이를 지났다.<br>마지막 개가 눈을 떴다. 이쪽을 본다. 입을 벌리려다 못 벌린다. 낮게 운다. 그 소리가 칸 끝까지 따라왔다. 문 너머까지는 못 따라왔다.`,
      ng:`조이는데 개가 눈을 뜬다. 코앞에서.<br><br>고리가 반쯤 빠졌던 그 개다. 고개를 턴다. 고리가 빠졌다. 이빨이 팔뚝에 박혔다.<br>실로 주둥이를 감아 겨우 떼어 냈다. 팔뚝 살이 패었다. 나머지 다섯이 깨어 입마개 안에서 으르렁댄다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-28, spirit:-12 } },
    { l:'② 개들 목줄 끝을 서로 이어 한 덩이로 묶는다.', k:'fix', dc:21,
      ok:`목줄 끝을 하나씩 이었다. 여섯이 한 줄이 됐다. 마지막 끝은 쇠기둥에.<br><br>지나가는데 하나가 깼다. 일어서려다 다섯이 같이 끌려온다. 다섯은 안 깨려고 버틴다. 여섯이 엉켜 제자리를 돈다.<br>칸 끝 문을 닫았다. 문 너머에서 엉킨 개들이 서로에게 짖었다. 이쪽에는 아무도 안 짖었다.`,
      ng:`이으려는데 목줄 하나가 짧다. 당기다 그 개가 깼다.<br><br>입마개 안에서도 소리는 난다. 다섯이 깼다. 여섯이 동시에 이쪽을 향한다.<br>뛰었다. 문을 닫는 순간 목줄 하나가 문틈에 걸렸다. 그 개가 문을 들이받았다. 문과 함께 이쪽 어깨가 울렸다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-26, mind:-13 } }
  ] },

{ at:'B3', t:'4호차 지붕 — 바람 속의 다섯 가닥',
  x:`지붕 사다리를 올라왔다. 객차 지붕 위다. 비가 옆으로 친다. 바람이 사람을 민다.<br><br>
    지붕은 둥글고 미끄럽다. 붙잡을 데가 없다. 다음 칸까지 열두 걸음. 터널이 다가오는 소리가 들린다.<br>
    손목에서 다섯 가닥이 바람에 떤다. 바람은 실을 아무 쪽으로나 당긴다.<br><br>
    앞에서 터널 입구가 검게 벌어진다.`,
  o:[
    { l:'① 다섯을 실로 이어 지붕 환기구에 묶고 엎드리게 한다.', k:'bond', dc:22,
      doom:{ title:'터널 바람', what:'바람에 채여 지붕 밖으로 끌려갑니다', dc:18, sec:45,
        text:`다섯을 이었다. 끝을 지붕 환기구에 묶었다. 엎드리라고 소리쳤다. 바람이 소리를 찢었다.<br><br>넷이 엎드렸다. 이쪽은 매듭을 확인하느라 반쯤 일어서 있었다. 터널 바람이 왔다. 이쪽만 들렸다.<br>넷은 환기구에 묶였다. 이쪽은 넷에 묶였다. 바람이 이쪽을 지붕 밖으로 당긴다. 넷이 같이 끌려온다.<br><br>매듭 하나를 풀면 넷이 산다. 이쪽 손목 매듭이다.`,
        dieText:`손목 매듭을 풀었다. 이쪽이 맨 매듭이니 이쪽이 풀 수 있었다.<br><br>터널을 나오자 지붕 위에 넷이 엎드려 있었다. 환기구에 묶인 채.<br>실 한 가닥이 바람에 날린다. 끝에 아무것도 없다.` },
      ok:`다섯을 이었다. 끝을 지붕 환기구에 묶었다. 이쪽이 맨 먼저 엎드렸다. 엎드린 채로 매듭을 확인했다.<br><br>터널이 덮쳤다. 바람이 지붕을 핥는다. 실이 다섯 방향으로 운다. 환기구가 버틴다.<br>터널을 나왔다. 다섯이 다 지붕에 붙어 있다. 매듭을 한 칸씩 옮겨 묶으며 다음 칸까지 기어갔다. 열두 걸음에 매듭 여섯.`,
      win:{ exp:24, dream:4 } },
    { l:'② 지붕을 버리고 객차 옆면 창틀에 실을 걸며 건넌다.', k:'evade', dc:21,
      ok:`지붕 끝에서 객차 옆면으로 내려섰다. 창틀이 발판이다. 창틀마다 실을 걸어 손잡이를 만들었다.<br><br>창 안에 승객들이 잔다. 창에 비친 이쪽 얼굴이 한 박자 늦게 따라온다. 그것만 안 봤다.<br>터널이 지나갔다. 옆면은 바람이 덜 친다. 다음 칸 연결부에 내려섰다. 마지막 창 안에서 누가 이쪽 실을 만지고 있었다.`,
      ng:`창틀에 실을 거는데 창이 안에서 열린다. 잠든 승객이 실을 잡아당긴다. 자면서.<br><br>발이 창틀에서 빠졌다. 실 하나에 매달려 객차 옆구리에 몇 번 부딪혔다. 갈비뼈가 울렸다.<br>다른 팀원이 끌어올렸다. 창은 다시 닫혔다. 잠든 승객 손에 실 한 토막이 남았다.`,
      win:{ exp:18, dream:3 }, lose:{ hp:-30, mind:-12 } }
  ] },

{ at:'B3', t:'기관실 — 기관사가 둘',
  x:`기관실에 기관사가 둘 서 있다. 같은 모자, 같은 검댕, 같은 얼굴.<br><br>
    둘 다 이쪽을 보고 같은 말을 한다. 저 사람이 가짜라고. 서로를 가리킨다.<br>
    진짜만 열차를 세울 줄 안다. 가짜는 세우는 척하며 종착까지 끌고 간다.<br><br>
    실은 사람 손목에 감긴다. 사람이 아닌 것에 어떻게 감기는지는 아직 모른다.`,
  o:[
    { l:'① 두 기관사 손목에 한 가닥씩 실을 감는다.', k:'bond', dc:22,
      ok:`둘에게 손을 내밀라고 했다. 둘 다 내민다. 한 가닥씩 감았다.<br><br>왼쪽 손목 실은 살에 붙는다. 맥이 실을 타고 온다. 빠르다. 겁먹은 맥이다. 오른쪽 손목 실은 미끄러진다. 감아도 한 바퀴 돌아 내려온다. 맥이 없다.<br>오른쪽을 밀어냈다. 왼쪽이 레버를 잡는다. 제동 소리가 길게 운다.<br><br>얼굴은 바꿀 수 있다. 맥은 못 바꾼다. 실은 얼굴을 안 본다. 이제 이 실은 묶기 전에 먼저 가려낸다. 손이 그 순서로 움직인다.`,
      ng:`감는데 둘 다 실이 붙는다. 둘 다 맥이 있다.<br><br>가짜가 맥까지 흉내 낸다. 아니면 둘 다 진짜거나, 둘 다 아니다. 망설이는 사이 오른쪽이 레버를 잡았다. 열차가 빨라진다.<br>왼쪽이 오른쪽에게 덤빈다. 둘 사이에 끼었다. 화실 문에 등이 닿았다. 외투 타는 냄새가 났다.`,
      win:{ exp:25, dream:4 }, lose:{ hp:-30, mind:-14 }, wake:1 },
    { l:'② 두 기관사 손바닥을 펴 보게 한다.', k:'gaze', dc:21,
      ok:`손바닥을 보여 달라고 했다. 둘 다 편다. 둘 다 검댕투성이다.<br><br>왼쪽은 검댕 밑에 굳은살이 있다. 레버 잡는 자리에만. 오른쪽은 굳은살이 고르다. 손바닥 전체에. 무엇을 오래 쥔 손이 아니다. 굳은살을 흉내 낸 손이다.<br>왼쪽에게 고개를 끄덕였다. 레버가 당겨진다. 오른쪽이 처음으로 웃는다. 얼굴이 이쪽 얼굴로 바뀌다 만다.`,
      ng:`보려고 다가가는데 오른쪽이 이쪽 손을 덥석 잡는다. 악수처럼.<br><br>손바닥이 뜨겁다가 차가워진다. 이쪽 손금이 그쪽으로 옮겨 가는 느낌이다. 뿌리쳤다.<br>손바닥이 하얗게 벗겨졌다. 오른쪽 기관사 손바닥에 이쪽 손금이 있다.`,
      win:{ exp:20, dream:3, spirit:6 }, lose:{ hp:-24, spirit:-16 } }
  ] }

]);

// ──────────────────────────────────────────
// 견습 기사 (knight) · 무력
// ──────────────────────────────────────────
kJob('knight', 'B', [

{ at:'B', t:'긴 복도 — 등을 보이지 않는다',
  x:`뒤에서 발소리가 온다. 일정하다. 팀이 앞으로 걷는다. 빠르게. 뛰지는 않는다. 뛰면 저쪽도 뛴다.<br><br>
    견습 기사가 외우는 맹세 둘째 줄은 등을 보이지 않는다이다. 지금 팀은 다 등을 보이고 있다.<br>
    맨 뒤에 누가 서야 한다. 맨 뒤는 등이 아니라 얼굴이 쫓는 쪽을 향하는 자리다.<br><br>
    발소리가 모퉁이를 돈다.`,
  o:[
    { l:'① 맨 뒤에서 뒷걸음으로 걸으며 쫓는 쪽을 마주 본다.', k:'bond', dc:20,
      ok:`맨 뒤로 갔다. 돌아섰다. 뒷걸음으로 걸었다. 왼손은 뒤로 뻗어 바로 앞 팀원 어깨에 얹었다.<br><br>어깨가 길을 알려 준다. 앞사람이 꺾으면 손이 먼저 꺾인다. 눈은 계속 뒤를 본다. 모퉁이에 그림자가 섰다. 따라오지 않는다. 마주 보는 얼굴은 쫓기 어렵다.<br>복도 끝 문을 지났다. 문을 닫은 것도 맨 뒤의 손이었다.<br><br>물러나면서 등을 안 보이는 법. 앞사람 어깨에 손을 얹고 뒤로 걷는 걸음. 맹세 둘째 줄이 발에 붙었다.`,
      ng:`뒷걸음으로 걷다 발뒤꿈치가 문턱에 걸렸다.<br><br>엉덩방아를 찧었다. 그림자가 모퉁이에서 한 걸음 나온다. 팀원 둘이 돌아와 겨드랑이를 잡아 끌었다.<br>꼬리뼈가 울린다. 등을 안 보이려다 바닥을 보였다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-24, mind:-12 }, wake:1 },
    { l:'② 무력을 끌어올려 돌아서서 복도 가운데를 막아선다.', k:'steady', dc:21, cost:{ might:24 },
      ok:`복도 한가운데 섰다. 무력을 다리로 내렸다. 바닥에 박힌 듯 섰다.<br><br>모퉁이에서 그림자가 나온다. 이쪽을 본다. 이쪽도 본다. 숨 스물. 그림자가 한 걸음 물러난다. 지나가려면 비켜 가야 하는데 비켜 갈 자리가 없다.<br>그림자가 돌아갔다. 다른 길로 오겠다는 뜻이다. 시간은 벌었다. 다리가 저렸다.`,
      ng:`섰는데 그림자가 멈추지 않는다. 그대로 걸어온다.<br><br>어깨를 부딪쳐 왔다. 무력으로 버텼는데 사람 무게가 아니다. 벽까지 밀려 등이 박혔다. 숨이 끊겼다.<br>그림자를 지나가게 두지는 않았다. 갈비뼈 하나가 그 값을 냈다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-28, mind:-10 } },
    { l:'③ 다 같이 뛴다.', k:'evade', dc:20,
      ok:`뛰라고 했다. 다섯이 같이 뛰었다. 맨 뒤에서 이쪽이 뛰었다.<br><br>뒤의 발소리도 뛴다. 처음으로. 거리가 준다. 복도 끝 문까지 열 걸음. 다섯. 문을 지나 닫았다. 발소리가 문 앞에서 멈췄다.<br>숨이 턱까지 찼다. 맹세 둘째 줄을 오늘은 못 지켰다. 그래도 다섯이 다 문 안에 있다.`,
      ng:`뛰자 뒤의 발소리도 뛴다. 이쪽보다 빠르다.<br><br>맨 뒤의 외투가 잡혔다. 앞으로 넘어졌다. 턱이 바닥에 찧였다. 팀원 둘이 돌아와 끌었다. 외투 자락이 찢겨 뒤에 남았다.<br>등을 보인 값이었다.`,
      win:{ exp:14, dream:2 }, lose:{ hp:-24, spirit:-12 } }
  ] },

{ at:'B', t:'방문 — 등으로 막는 문',
  x:`팀이 창문으로 빠져나가는 중이다. 창은 좁다. 한 사람씩. 한 사람에 숨 열.<br><br>
    방문 너머에서 누가 민다. 빗장은 없다. 문고리만 있다. 문고리가 아래로 돈다.<br>
    견습 기사가 등을 문에 댔다. 다섯이 다 나가려면 숨 쉰이 필요하다.<br><br>
    문틈으로 젖은 손가락 끝이 들어온다.`,
  o:[
    { l:'① 무력을 끌어올려 등으로 문을 막고 숨을 센다.', k:'steady', dc:21, cost:{ might:25 },
      ok:`등을 문에 붙이고 발을 바닥에 박았다. 무력을 허리로 모았다. 숨을 셌다.<br><br>열. 첫째가 나갔다. 스물. 둘째. 문이 민다. 쉬었다가 다시 민다. 서른. 마흔. 문틈 손가락이 이쪽 옷깃을 더듬는다. 돌아보지 않았다.<br>쉰. 넷째까지 나갔다. 마지막으로 창에 몸을 넣는 순간 문이 열렸다. 창밖 빗속으로 떨어졌다. 등 뒤에서 젖은 손이 허공을 쥐었다.`,
      ng:`서른에서 다리가 미끄러졌다. 바닥이 빗물에 젖었다.<br><br>문이 한 뼘 열렸다. 젖은 손이 들어와 목덜미를 쥔다. 차다. 팀원 하나가 돌아와 그 손등을 칼자루로 내리쳤다.<br>문을 다시 닫았다. 목덜미에 손자국이 하얗게 남았다. 다 나가는 데 숨 백이 걸렸다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-26, mind:-14 } },
    { l:'② 칼집을 문고리에 꿰어 문틀에 걸친다.', k:'fix', dc:20,
      ok:`칼을 뽑고 칼집을 문고리 사이로 꿰었다. 칼집 양끝이 문틀에 걸린다. 빗장이 됐다.<br><br>문이 민다. 칼집이 운다. 버틴다. 그 사이 다섯이 차례로 창을 넘었다.<br>마지막으로 창을 넘으며 칼집을 두고 왔다. 칼은 손에 있다. 칼집은 다시 구하면 된다.`,
      ng:`칼집을 꿰는데 문이 먼저 열렸다. 칼집이 문고리에 걸린 채 문과 같이 돌았다.<br><br>손목이 꺾였다. 칼집을 놓쳤다. 문틈으로 젖은 얼굴이 들어온다. 얼굴이 아니라 얼굴 모양이다.<br>칼등으로 문짝을 쳐서 밀어 닫았다. 손목이 부었다. 칼집은 저쪽에 남았다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-24, spirit:-14 } }
  ] },

{ at:'B', t:'계단 밑 — 두고 가면 길을 열어 준다는 사람',
  x:`다친 팀원이 계단 밑에 앉아 있다. 발목이 부었다. 혼자 못 걷는다.<br><br>
    계단 위에 사람이 하나 서 있다. 외투 깃을 세웠다. 길을 열어 주겠다고 한다. 넷만. 다친 사람은 두고.<br>
    다친 사람은 어차피 늦는다고. 다 같이 늦을 거냐고.<br><br>
    맹세 첫 줄은 약한 자를 지킨다이다. 그 줄에는 늦는다는 말이 없다.`,
  o:[
    { l:'① 무력을 끌어올려 다친 팀원을 업는다.', k:'steady', dc:21, cost:{ might:25 },
      ok:`다친 팀원을 등에 올렸다. 무력을 허리에 모았다. 일어섰다.<br><br>외투 깃 사람이 계단을 한 칸 비켜선다. 길을 막을 생각은 없었다. 무게를 재 보려 했을 뿐이다. 업은 사람이 얼마나 갈 수 있는지.<br>계단 셋을 올라갔다. 다리가 떨린다. 외투 깃 사람이 지나가는 이쪽 귀에 말했다. 다음 층에서 다시 묻겠다고.`,
      ng:`업고 일어서는데 무릎이 꺾였다. 둘이 같이 계단에 박혔다.<br><br>외투 깃 사람이 웃는다. 그것 보라고. 다친 팀원이 이쪽 귀에 속삭인다. 두고 가라고.<br>못 들은 척 다시 업었다. 계단 모서리에 정강이를 몇 번이나 찍으며 올라갔다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-28, mind:-12 } },
    { l:'② 칼을 뽑지 않고 다친 팀원 앞에 서서 올려다본다.', k:'bond', dc:21,
      ok:`다친 팀원 앞에 섰다. 칼은 안 뽑았다. 계단 위 사람을 올려다봤다.<br><br>그 사람이 무언가 더 말하려다 그친다. 서 있는 사람에게는 거래를 못 건다. 거래는 망설이는 사람에게 건다.<br>그 사람이 돌아서 계단 위로 사라졌다. 길을 열어 주지는 않았다. 막지도 않았다.<br><br>넷이 다친 팀원을 둘씩 나눠 부축했다. 이쪽은 맨 앞에서 계단을 올랐다. 앞에 서는 게 칼보다 먼저다. 칼 없이 서 있는 법을 몸이 한 번 더 외웠다.`,
      ng:`앞에 섰는데 그 사람이 계단을 내려온다. 한 칸씩. 천천히.<br><br>코앞까지 와서 이쪽 어깨를 손가락으로 민다. 가볍게. 그런데 뒤로 넘어졌다. 다친 팀원 위로.<br>그 사람이 지나갔다. 다친 팀원 발목을 밟고. 비명이 계단을 올라갔다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-24, spirit:-14 }, wake:1 }
  ] },

{ at:'B', t:'골목 — 빛 하나, 웅크린 둘',
  x:`골목 끝에서 손전등이 들어온다. 팀원 둘이 쓰레기통 뒤에 웅크렸다. 빛이 그쪽으로 간다.<br><br>
    숨을 데가 없다. 빛이 닿으면 끝이다.<br>
    이쪽은 골목 반대편 그늘에 있다. 아직 안 보였다.<br><br>
    빛을 끌어올 수 있는 건 빛 안으로 들어가는 사람뿐이다.`,
  o:[
    { l:'① 빛 속으로 걸어 들어가 시선을 끈다.', k:'bond', dc:21,
      doom:{ title:'빛 속으로', what:'손전등 쪽으로 끌려갑니다', dc:17, sec:55,
        text:`그늘에서 나왔다. 빛 속으로. 일부러 발소리를 냈다.<br><br>빛이 이쪽으로 꺾인다. 얼굴에 박힌다. 눈앞이 하얘졌다. 뛰려는데 빛이 따라온다. 빛 뒤에서 고무장갑 낀 손이 나온다. 빛보다 빠르다.<br>옷깃이 잡혔다. 끌려간다. 쓰레기통 뒤 둘은 숨을 죽이고 있다. 아무도 못 봤다. 그게 이쪽이 원한 거였다.<br><br>골목 끝 어둠이 다가온다.`,
        dieText:`빛은 골목 끝으로 멀어졌다.<br><br>쓰레기통 뒤 둘은 숨 백을 세고 나왔다. 골목에는 아무것도 없었다. 빗속인데 바닥이 깨끗했다.<br>맹세 첫 줄은 지켰다. 약한 쪽은 둘이었다. 이쪽은 하나였다.` },
      ok:`그늘에서 나왔다. 빛 속으로. 일부러 발소리를 냈다.<br><br>빛이 이쪽으로 꺾인다. 그 순간 옆 담을 넘었다. 빛은 담을 못 넘는다. 빛을 든 쪽이 담 앞에서 멈칫한다.<br>그 사이 쓰레기통 뒤 둘이 골목을 빠져나갔다. 이쪽도 담 너머로 빠져나갔다. 담 꼭대기 유리 조각에 손바닥이 베였다. 그 정도는 값도 아니다.`,
      win:{ exp:24, dream:3 } },
    { l:'② 빛 반대편 철판 셔터를 쳐서 소리를 낸다.', k:'luck', dc:20,
      ok:`골목 반대편 셔터를 칼등으로 쳤다. 크게.<br><br>빛이 그쪽으로 꺾인다. 쓰레기통 뒤 둘이 그 틈에 빠져나왔다. 이쪽은 그늘을 타고 따라 나갔다.<br>빛은 한참 셔터를 비췄다. 셔터 앞에 아무도 없다. 다시 돌아왔을 땐 골목이 비어 있었다.`,
      ng:`쳤는데 빛이 꺾이지 않는다. 소리 난 쪽이 아니라 소리 낸 쪽을 안다.<br><br>빛이 이쪽 그늘로 와 얼굴에 박혔다. 뛰었다. 쓰레기통 뒤 둘도 같이 들켰다.<br>셋이 담을 넘었다. 담 꼭대기 철조망에 팔뚝이 길게 찢겼다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-26, mind:-12 } }
  ] },

{ at:'B', t:'쉬는 자리 — 맹세를 버린 사람',
  x:`쉬는 자리에 누가 먼저 와 있다. 낡은 가슴판을 입었다. 문장이 긁혀 지워졌다.<br><br>
    그 사람이 이쪽 손을 본다. 칼자루 감은 방식을 알아본다. 같은 데서 배운 사람이다.<br>
    그 사람이 말한다. 여기서는 맹세가 사람을 죽인다고. 자기는 맹세를 버려서 살았다고.<br><br>
    그 사람 옆에 빈 침낭이 넷 있다.`,
  o:[
    { l:'① 무엇을 지키려다 맹세를 버렸는지 묻는다.', k:'bond', dc:21,
      ok:`무엇을 지키려다 그랬냐고 물었다.<br><br>그 사람이 오래 침낭 넷을 본다. 넷을 지키려고 맨 앞에 섰다고 한다. 넷은 뒤에서 기다리다 다 잡혔다고. 맨 앞에 서 있는 동안.<br>맹세가 죽인 게 아니다. 혼자 앞에 선 게 죽였다. 그 말은 하지 않았다. 대신 침낭 넷을 같이 개었다.<br><br>그 사람이 떠나기 전에 말했다. 앞에 설 거면 뒤를 볼 사람을 하나 세우라고. 그날부터 맨 앞에 설 때마다 뒤를 맡을 사람을 정해 둔다. 처음 맹세에 없던 줄이다. 몸이 먼저 넣었다.`,
      ng:`묻자 그 사람 얼굴이 일그러진다. 그걸 왜 묻냐고.<br><br>낡은 가슴판을 벗어 이쪽 발 앞에 던진다. 맹세하는 놈이나 입으라고.<br>그 사람이 빗속으로 나갔다. 가슴판이 무겁다. 안쪽에 이름 넷이 새겨져 있다. 들고 갈 수도 버릴 수도 없어 한참 앉아 있었다.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-16, spirit:-16 }, wake:1 },
    { l:'② 맹세 세 줄을 소리 내어 읊는다.', k:'steady', dc:20,
      ok:`소리 내어 읊었다. 약한 자를 지킨다. 등을 보이지 않는다. 맹세를 버리지 않는다.<br><br>그 사람이 웃다가 그친다. 셋째 줄에서. 입술이 따라 움직였다. 소리는 안 냈다.<br>그 사람이 일어나 침낭 넷을 둘둘 말아 등에 진다. 버리지 않고. 그리고 이쪽보다 먼저 떠났다. 다음 쉬는 자리에 침낭 하나가 펴져 있었다. 이쪽 몫으로.`,
      ng:`읊는데 둘째 줄에서 목이 멘다. 침낭 넷이 눈에 들어와서.<br><br>그 사람이 웃는다. 그것 보라고. 맹세는 입이 아니라 목에서 걸린다고.<br>그 말이 밤새 목에 걸려 있었다. 아침에 보니 그 사람도 침낭도 없었다.`,
      win:{ exp:18, dream:2, spirit:8 }, lose:{ mind:-15, spirit:-15 } }
  ] },

{ at:'B', t:'쇠다리 — 한 사람 폭',
  x:`두 건물 사이를 쇠다리가 잇는다. 한 사람 폭. 빗물에 젖었다. 아래는 까마득하다.<br><br>
    뒤에서 문 열리는 소리가 났다. 쫓는 쪽이 다리 입구까지 숨 서른.<br>
    한 사람씩 건너면 숨 마흔. 열이 모자란다.<br><br>
    누가 맨 끝에서 그 열을 벌어야 한다.`,
  o:[
    { l:'① 무력을 끌어올려 맨 끝에서 다리 입구를 막고 선다.', k:'steady', dc:21, cost:{ might:26 },
      ok:`다리 입구에서 돌아섰다. 무력을 끌어올려 양손으로 난간을 쥐었다. 이쪽 몸이 다리의 문이 됐다.<br><br>문이 열리고 그림자가 나온다. 다리 앞에 선 이쪽을 본다. 지나가려면 이쪽을 다리 밖으로 밀어야 한다. 한 번 민다. 버텼다.<br>등 뒤에서 마지막 팀원이 건너편에 닿는 소리가 났다. 그제야 뒷걸음으로 건넜다. 그림자는 다리에 오르지 않았다.`,
      ng:`섰는데 그림자가 밀지 않고 손목을 잡는다. 난간 쥔 손가락을 하나씩 떼어 낸다.<br><br>손가락 셋이 떨어졌다. 무력으로 다시 쥐었다. 마디 꺾이는 소리가 났다.<br>팀원 하나가 다리 중간에서 돌아와 이쪽 허리를 잡아당겼다. 둘이 같이 건넜다. 손가락 둘이 한참 굽혀지지 않았다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-28, mind:-12 } },
    { l:'② 먼저 건너가 저쪽 끝에서 한 사람씩 받아 준다.', k:'bond', dc:20,
      ok:`먼저 건넜다. 저쪽 끝에 서서 손을 뻗었다. 건너오는 사람마다 마지막 세 걸음을 손으로 끌었다.<br><br>마지막 세 걸음이 제일 느리다. 끝이 보이면 다리가 풀린다. 그 세 걸음을 이쪽 팔이 대신 걸었다.<br>숨 서른다섯에 다 건넜다. 다섯이 빨라진 게 아니라 끝 세 걸음이 짧아졌다.`,
      ng:`끌어당기다 셋째가 미끄러졌다. 이쪽 팔에 매달렸다.<br><br>난간 밖으로 몸이 반쯤 나갔다. 어깨가 빠지는 줄 알았다. 다른 팀원이 이쪽 다리를 붙들었다.<br>셋째를 끌어올리는 동안 다리 저쪽 입구에 그림자가 섰다. 다 건너긴 했다. 어깨가 한참 올라가지 않았다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-26, spirit:-12 } }
  ] },

{ at:'B', t:'문 앞 — 칼을 맡기고 가라',
  x:`문 앞에서 칼을 맡기라고 한다. 외투 입은 남자 둘이 서 있다. 나갈 때 돌려준다고 한다.<br><br>
    나갈 때가 있을지 모른다. 그래도 맡기지 않으면 못 들어간다. 이 문 너머가 계단이다.<br>
    칼을 내주었다. 손이 비었다. 칼 없이 앞에 서 본 적이 없다.<br><br>
    문 너머에서 무언가 기다린다.`,
  o:[
    { l:'① 빈손으로 맨 앞에 선다.', k:'bond', dc:21,
      ok:`빈손으로 맨 앞에 섰다. 손바닥을 펴서 앞으로 내밀었다. 무언가 오면 밀어낼 수 있게.<br><br>계단 중간에서 무언가 튀어나왔다. 칼이 있었으면 베었을 것이다. 손바닥으로 밀었다. 어깨로 받았다. 뒤의 넷은 털끝 하나 안 다쳤다.<br>앞에 선다는 건 칼을 드는 게 아니었다. 사이에 있는 거였다. 칼은 그다음이다.<br><br>손바닥에 멍이 들었다. 그 멍이 새 쥐는 법을 가르쳤다. 칼이 없어도 손이 막는 모양을 안다.`,
      ng:`빈손으로 섰는데 무언가 손바닥을 문다. 이빨이 있다.<br><br>밀어냈다. 손바닥 살이 찢겼다. 뒤의 팀원이 이쪽 대신 그것을 걷어찼다.<br>계단을 다 내려가서야 피가 멎었다. 칼이 있었으면. 그 생각이 한참 안 떠났다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-26, mind:-12 }, wake:1 },
    { l:'② 무력으로 의자 다리를 뽑아 대신 쥔다.', k:'break', dc:20, cost:{ might:22 },
      ok:`문 옆 의자를 뒤집어 다리 하나를 뽑았다. 무력이 손목에서 나무를 뚝 끊었다.<br><br>짧다. 가볍다. 칼보다 못하다. 그래도 쥔 게 있으니 손이 안 떨린다.<br>계단에서 튀어나온 것을 나무 다리로 쳤다. 나무가 쪼개졌다. 그것도 물러났다. 칼이든 나무든 앞에 선 사람 손에 있으면 같다.`,
      ng:`뽑는데 다리가 아니라 등받이가 부서졌다. 큰 소리가 났다.<br><br>문 앞 남자들이 돌아본다. 하나가 다가와 나무 조각을 빼앗는다. 맡기라고 했을 텐데.<br>등을 떠밀려 계단을 굴렀다. 빈손으로. 무릎과 팔꿈치가 다 까졌다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-26, spirit:-12 } }
  ] },

{ at:'B', t:'출구 — 내려오는 셔터',
  x:`출구 셔터가 내려온다. 천천히. 바닥까지 숨 스물.<br><br>
    팀은 넷이 아직 안쪽이다. 한 사람씩 엎드려 기어 나가면 숨 스물다섯.<br>
    셔터 위 시계가 깜빡인다. 빨간 숫자. 다섯 시 사 분.<br><br>
    셔터 밑에 무언가 괴면 멈출지도 모른다. 아니면 사람이 괴든지.`,
  o:[
    { l:'① 무력을 끌어올려 셔터 밑단을 어깨로 받친다.', k:'steady', dc:22, cost:{ might:28 },
      doom:{ title:'내려오는 셔터', what:'셔터 밑에 깔렸습니다', dc:18, sec:45,
        text:`셔터 밑에 어깨를 넣었다. 무력을 다 끌어올렸다. 셔터가 멈춘다. 무릎 높이에서.<br><br>하나가 기어 나갔다. 둘. 셋. 모터가 운다. 이쪽 어깨를 누른다. 쇠는 사람을 모른다.<br>넷째가 나갔다. 이쪽 차례다. 어깨를 빼면 셔터가 떨어진다. 안 빼면 못 나간다.<br><br>무릎이 바닥에 닿았다. 셔터가 귀 옆까지 왔다.`,
        dieText:`넷은 셔터 밖에서 숨 백을 셌다.<br><br>셔터는 바닥까지 내려오지 않았다. 무릎 높이에서 멈춰 있었다. 무언가 받치고 있었다.<br>빨간 숫자가 다섯 시 십 분이 되자 셔터 위 시계가 꺼졌다.` },
      ok:`셔터 밑에 어깨를 넣었다. 무력을 다 끌어올렸다. 셔터가 무릎 높이에서 멈춘다.<br><br>넷이 기어 나갔다. 모터가 운다. 마지막 팀원이 밖에서 이쪽 손목을 잡았다. 하나, 둘에 어깨를 빼고 그 손에 끌려 나왔다. 셔터가 바닥을 쳤다. 발뒤꿈치 한 뼘 뒤에서.<br><br>어깨에 셔터 이음매 자국이 줄줄이 찍혔다.`,
      win:{ exp:24, dream:4 } },
    { l:'② 셔터 밑에 쇠 의자를 괴어 놓는다.', k:'fix', dc:21,
      ok:`사무실 쇠 의자를 끌어다 셔터 밑에 눕혔다. 다리가 위로 가게.<br><br>셔터가 내려와 의자 다리에 닿는다. 멈춘다. 모터가 운다. 의자 다리가 천천히 휜다.<br>휘는 사이 다섯이 다 기어 나갔다. 마지막이 나오자 의자가 접혔다. 셔터가 바닥을 쳤다. 의자 하나가 다섯 몫을 했다.`,
      ng:`의자를 괴었는데 셔터가 의자를 그냥 접는다. 숨 셋 만에.<br><br>둘이 아직 안쪽이다. 셔터 밑단에 손을 넣어 들었다. 무력 없이. 손가락이 짓눌렸다.<br>둘이 기어 나오는 동안 손가락이 셔터 밑에 있었다. 손톱 둘이 까맣게 죽었다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-28, mind:-12 } }
  ] },

{ at:'B1', t:'냉동 창고 — 냉풍구 밑',
  x:`냉동 창고 문이 닫혔다. 안에서는 안 열린다. 누가 밖에서 열어 줄 때까지 버텨야 한다.<br><br>
    천장 냉풍구에서 찬바람이 쏟아진다. 막내가 그 밑에 웅크렸다. 입술이 파랗다.<br>
    온도계 옆에 손톱으로 그은 글씨가 있다. 한 시간.<br><br>
    바람은 한쪽에서만 온다. 한쪽만 막으면 된다.`,
  o:[
    { l:'① 무력을 끌어올려 냉풍구 밑을 몸으로 막는다.', k:'steady', dc:21, cost:{ might:24 },
      ok:`냉풍구 바로 밑에 섰다. 등을 바람 쪽으로. 무력을 끌어올려 몸을 데웠다.<br><br>찬바람이 등을 친다. 등 뒤로 바람이 갈라진다. 이쪽 앞에 바람 없는 자리가 생겼다. 막내와 둘이 그 자리에 들어갔다.<br>사십 분째에 등에 감각이 없다. 그래도 섰다. 밖에서 문이 열렸다. 하역부 노인이었다.<br><br>막는 게 맞서는 것만은 아니다. 바람을 등으로 갈라 뒤에 자리를 만드는 것이다. 등이 새로 할 줄 아는 일이 생겼다.`,
      ng:`섰는데 무력이 추위에 먹힌다. 몸이 데워지지 않는다.<br><br>삼십 분째에 무릎이 꺾였다. 막내와 같이 바닥에 쓰러졌다. 바닥이 등보다 차다.<br>밖에서 문이 열렸을 때 손가락 끝이 하얬다. 녹으면서 더 아팠다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-28, mind:-12 }, wake:1 },
    { l:'② 외투를 벗어 막내를 싸고 다 같이 붙어 앉게 한다.', k:'bond', dc:20,
      ok:`외투를 벗어 막내를 쌌다. 다섯이 원으로 붙어 앉았다. 막내가 가운데.<br><br>바람이 원 바깥을 돈다. 가운데는 덜 춥다. 이쪽은 바람 쪽 자리에 앉았다. 외투 없이.<br>한 시간이 다 되기 전에 문이 열렸다. 막내 입술에 색이 돌아와 있었다. 이쪽 입술이 파랬다.`,
      ng:`외투를 벗자마자 몸이 떨린다. 이가 맞부딪친다.<br><br>원으로 앉았는데 이쪽 떨림이 옆 사람에게 옮는다. 원 전체가 떤다.<br>문이 열렸을 때 다들 못 일어났다. 외투는 막내가 꼭 쥐고 있었다. 돌려받는 데 손가락을 하나씩 펴야 했다.`,
      win:{ exp:18, dream:2, hp:8 }, lose:{ hp:-26, spirit:-12 } },
    { l:'③ 문을 안에서 두드려 밖에 박자를 보낸다.', k:'luck', dc:20,
      ok:`문을 주먹으로 두드렸다. 셋, 쉼, 셋. 밖의 누군가 들으라고.<br><br>한참 대답이 없다. 그러다 밖에서 똑같이 두드린다. 셋, 쉼, 셋. 그리고 문이 열렸다. 하역부 노인이다. 이 박자를 아는 건 여기 오래 있던 사람뿐이라고 한다.<br>노인이 맑은 물 한 병을 내민다. 냉동 창고에서 나온 사람은 목부터 마른다고.`,
      ng:`두드리는데 대답이 온다. 셋, 쉼, 셋. 그런데 문은 안 열린다.<br><br>대답이 문 바깥이 아니라 안쪽에서 들린다. 창고 깊은 데서. 셋, 쉼, 셋.<br>다들 문에 등을 붙이고 안쪽 어둠을 봤다. 한 시간이 다 될 때까지. 손가락이 하얗게 굳었다.`,
      win:{ exp:16, dream:2, item:'맑은 물' }, lose:{ hp:-22, mind:-16 } }
  ] },

{ at:'B1', t:'경매장 — 갈고리 장대',
  x:`경매장 노란 비옷들이 장대를 들었다. 끝에 갈고리가 달렸다. 얼음 위 생선을 끌어당기는 장대다.<br><br>
    하나가 장대를 뻗는다. 팀원 외투 자락이 걸렸다. 끌려간다. 얼음 위로 미끄러진다.<br>
    비옷들 사이로 끌려가면 다시 안 나온다.<br><br>
    견습 기사가 장대 쪽으로 뛰었다.`,
  o:[
    { l:'① 무력을 끌어올려 장대 자루를 붙잡고 버틴다.', k:'steady', dc:21, cost:{ might:25 },
      ok:`장대 자루를 두 손으로 쥐었다. 무력을 다리로 내렸다. 얼음 위에서 발이 미끄러진다. 버텼다.<br><br>장대가 멈춘다. 비옷이 당긴다. 이쪽도 당긴다. 그 사이 팀원이 외투를 벗어 던졌다. 갈고리에 빈 외투만 걸렸다.<br>장대를 놓았다. 비옷이 뒤로 넘어진다. 비옷들이 빈 외투를 끌어간다. 경매판에 번호가 하나 늘었다.`,
      ng:`쥐었는데 얼음이 발을 받쳐 주지 않는다. 장대와 같이 이쪽도 끌려간다.<br><br>비옷들 사이로 반쯤 들어갔다. 고무장갑 낀 손들이 팔을 잡는다. 팀원들이 이쪽 허리를 잡아 끌어냈다.<br>팔뚝에 고무장갑 손자국이 여럿 남았다. 하나는 소매 안까지 들어왔었다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-26, mind:-13 } },
    { l:'② 장대를 쫓지 않고 팀원에게 가서 외투 자락을 끊는다.', k:'bond', dc:20,
      ok:`장대를 쫓지 않았다. 팀원에게 뛰어가 외투 자락을 칼로 끊었다.<br><br>갈고리가 천 조각만 물고 비옷들 쪽으로 돌아간다. 팀원은 얼음 위에 남았다. 손을 잡아 일으켰다.<br>끌려가는 사람을 구할 때는 끄는 쪽보다 끌리는 쪽으로 가야 한다. 비옷들은 천 조각을 경매판에 걸었다. 번호를 붙여서.`,
      ng:`칼을 대는 순간 장대가 확 당겨진다. 칼날이 팀원 팔을 스쳤다.<br><br>자락은 끊었다. 팀원 팔에서 피가 얼음 위로 떨어진다. 비옷들이 그 핏자국을 본다. 냄새를 맡듯이.<br>둘이 경매장을 빠져나오는 동안 장대 셋이 뒤를 따라왔다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-24, spirit:-14 } }
  ] },

{ at:'B1', t:'컨테이너 야적장 — 탐조등 속의 노인',
  x:`야적장에 탐조등이 돈다. 하얀 원이 바닥을 쓸고 다닌다.<br><br>
    원 한가운데 노인이 서 있다. 모자를 잃었다. 비를 맞으며 두리번거린다. 다른 팀 사람이다.<br>
    원이 노인을 따라 멈췄다. 크레인 쪽에서 노란 비옷들이 내려온다.<br><br>
    컨테이너 그늘까지 스무 걸음.`,
  o:[
    { l:'① 빛을 등지고 노인 앞에 서서 그림자로 가린다.', k:'bond', dc:21,
      ok:`원 안으로 뛰어들었다. 탐조등을 등지고 노인 앞에 섰다. 이쪽 그림자가 노인을 덮었다.<br><br>빛 속에서 그림자 안은 더 어둡다. 크레인 위에서는 서 있는 하나만 보인다.<br>노인을 그림자에 넣은 채 뒷걸음으로 걸었다. 스무 걸음. 그늘에 닿자 노인을 밀어 넣었다. 이쪽도 굴러 들어갔다.<br><br>앞에 서는 일은 막는 일이었다. 오늘은 가리는 일이었다. 등 뒤의 빛이 몸을 방패로 만들었다. 몸이 그걸 기억한다.`,
      ng:`앞에 섰는데 탐조등이 둘이다. 반대편에서 하나가 더 비춘다.<br><br>그림자가 둘로 갈라졌다. 노인이 그 사이에 드러났다. 비옷들이 뛰기 시작한다.<br>노인을 안고 그늘로 뛰었다. 컨테이너 모서리에 옆구리를 박았다. 노인은 무사했다. 이쪽 숨이 한참 안 돌아왔다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-26, mind:-12 }, wake:1 },
    { l:'② 무력을 끌어올려 노인을 업고 그늘까지 뛴다.', k:'steady', dc:21, cost:{ might:24 },
      ok:`노인을 등에 들쳐 업었다. 무력을 다리로 모았다. 뛰었다.<br><br>원이 따라온다. 스무 걸음. 원이 발뒤꿈치에 닿기 직전 그늘로 뛰어들었다.<br>노인이 등에서 내리며 이쪽 손에 무언가 쥐여 준다. 말린 고기 한 덩이. 기름종이에 쌌다. 모자 대신 이걸 챙겼다고.`,
      ng:`업고 뛰는데 빗물에 미끄러졌다. 원 한가운데서 둘이 같이 넘어졌다.<br><br>비옷들이 가까워진다. 노인이 먼저 일어나 이쪽 팔을 끈다. 기어서 그늘에 닿았다.<br>무릎과 손바닥이 다 갈렸다. 노인이 미안하다고 한다. 미안할 사람은 없었다.`,
      win:{ exp:20, dream:2, item:'말린 고기' }, lose:{ hp:-28, spirit:-12 } }
  ] },

{ at:'B1', t:'정문 — 청소부와 마지막 줄',
  x:`정문 철문이 반쯤 열렸다. 다섯 시 십 분까지 일 분.<br><br>
    팀이 한 줄로 철문을 빠져나간다. 맨 뒤가 이쪽이다.<br>
    그 뒤에 고무장화 소리가 있다. 뽀득. 뽀득. 서두르지 않는다. 대걸레를 끌고 온다.<br><br>
    철문은 한 사람씩만 지난다. 앞의 넷이 다 지나려면 숨 스물.`,
  o:[
    { l:'① 돌아서서 청소부 앞에 선다.', k:'bond', dc:22,
      doom:{ title:'마지막 줄', what:'청소부에게 붙잡혀 끌려갑니다', dc:18, sec:45,
        text:`돌아섰다. 청소부 앞에 섰다. 칼을 뽑았다.<br><br>청소부가 멈춘다. 대걸레를 벽에 기대 놓는다. 공손하게. 그리고 칼날을 고무장갑 낀 손바닥으로 쥔다. 피가 안 난다.<br>칼째 끌려간다. 칼을 놓으면 맹세를 놓는 것 같았다. 안 놓았다.<br><br>등 뒤에서 넷째가 철문을 지나는 소리가 났다. 이쪽은 철문 반대쪽으로 끌려간다.`,
        dieText:`철문 밖에서 넷이 기다렸다. 다섯 시 십 분이 지났다.<br><br>철문 안쪽에서 대걸레가 바닥을 한 번 훑는 소리가 났다. 고무장화 소리가 멀어졌다.<br>철문 앞 바닥이 깨끗하다. 칼 한 자루가 철문에 기대 세워져 있다. 공손하게.` },
      ok:`돌아섰다. 청소부 앞에 섰다. 칼은 안 뽑았다. 두 팔을 벌려 철문을 등으로 가렸다.<br><br>청소부가 멈춘다. 이쪽을 오래 본다. 대걸레 자루를 고쳐 쥔다. 그리고 바닥을 닦는다. 이쪽 발 앞까지.<br>닦을 자리가 끝났다. 청소부가 돌아선다. 철문 너머로 넷째가 빠져나가는 소리. 이쪽도 뒷걸음으로 철문을 지났다. 등 뒤에서 철문이 닫혔다. 다섯 시 십 분.`,
      win:{ exp:25, dream:4 } },
    { l:'② 앞사람들 등을 밀어 넣으며 같이 빠져나간다.', k:'steady', dc:21,
      ok:`돌아서지 않았다. 앞사람 등을 두 손으로 밀었다. 하나씩. 철문 틈으로.<br><br>밀 때마다 한 사람이 빨라진다. 숨 스물이 열다섯이 됐다. 마지막으로 이쪽 몸을 틈에 넣었다. 철문 모서리가 어깨를 긁었다.<br>뒤에서 고무장화 소리가 철문 앞에 멈췄다. 따라 나오지 않는다. 청소부는 정문 밖은 닦지 않는다.`,
      ng:`미는데 셋째가 철문 틈에 걸렸다. 가방이 끼었다.<br><br>고무장화 소리가 바로 뒤까지 왔다. 고무장갑이 외투 자락을 잡는다. 외투를 찢으며 셋째 가방끈을 칼로 끊었다.<br>둘이 같이 굴러 나왔다. 철문이 닫혔다. 외투 반쪽은 안에 남았다.`,
      win:{ exp:18, dream:3 }, lose:{ hp:-28, mind:-14 } }
  ] },

{ at:'B2', t:'정각 점검 — 틀린 이름',
  x:`정각이다. 간호사가 문 앞에서 이름을 부른다. 팀원 침대 명패의 이름이다. 팀원 이름이 아니다.<br><br>
    팀원이 대답을 못 한다. 입술이 떨린다. 그 이름으로 대답하면 그 이름이 된다고 들었다.<br>
    간호사가 한 번 더 부른다. 세 번째는 안 부른다. 데리러 온다.<br><br>
    이쪽 침대는 그 바로 옆이다.`,
  o:[
    { l:'① 팀원 대신 이쪽이 그 이름으로 대답한다.', k:'bond', dc:21,
      ok:`대답했다. 그 이름으로. 이쪽 목소리로.<br><br>간호사가 이쪽을 오래 본다. 계수기가 딸깍한다. 그리고 다음 침대로 간다.<br>명패를 봤다. 이름 끝 글자가 번져 있다. 이쪽 글씨체로. 팀원 명패는 멀쩡하다.<br><br>남이 맞을 것을 대신 받았다. 몸 말고 목소리로. 앞에 서는 일이 소리로도 된다. 그 이름을 오래 지고 가야 한다. 지는 게 일이다.`,
      ng:`대답하려는데 팀원이 먼저 대답한다. 떨리는 목소리로. 그 이름으로.<br><br>둘이 같이 대답했다. 계수기가 두 번 딸깍한다. 간호사가 수첩에 적는다. 하나가 많다.<br>팀원이 미안하다는 얼굴로 이쪽을 본다. 다음 정각까지 둘이 한 이름을 나눠 졌다.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-17, spirit:-16 }, wake:1 },
    { l:'② 팀원 침대와 이쪽 침대 명패를 몰래 바꿔 건다.', k:'fix', dc:20,
      ok:`간호사가 두 번째로 부르기 전에 명패를 바꿨다. 이쪽 침대에 그 이름. 팀원 침대에 이쪽 명패.<br><br>간호사가 이쪽 침대 앞에서 그 이름을 부른다. 대답했다. 처음부터 그 자리였던 것처럼.<br>팀원은 이쪽 명패 이름으로 대답했다. 이름 둘이 자리를 바꿨다. 사람은 그대로다. 계수기는 이름이 아니라 침대를 센다.`,
      ng:`바꾸는데 명패 고리가 휘어 안 걸린다.<br><br>간호사가 그 소리를 듣는다. 다가와 명패 둘을 손으로 쓸어 본다. 차갑다.<br>명패는 원래대로 걸렸다. 대신 간호사 수첩에 이쪽 침대 번호가 적혔다. 다음 정각에 이쪽부터 센다는 뜻이다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-15, spirit:-15 } }
  ] },

{ at:'B2', t:'처치실 복도 — 커튼 뒤의 손',
  x:`처치실 복도에 침대마다 커튼이 쳐 있다. 일행이 한 줄로 지나간다.<br><br>
    셋째 커튼이 살짝 열린다. 하얀 손이 나온다. 앞서 가던 팀원 손목을 향한다. 팀원은 모른다. 앞만 본다.<br>
    이쪽은 그 바로 뒤다. 손과 손목 사이 한 뼘.<br><br>
    한 뼘이면 팔 하나 들어간다.`,
  o:[
    { l:'① 팀원 손목과 하얀 손 사이로 팔을 넣는다.', k:'bond', dc:22,
      doom:{ title:'커튼 뒤', what:'커튼 뒤로 끌려 들어갑니다', dc:17, sec:50,
        text:`팔을 넣었다. 하얀 손이 팀원 대신 이쪽 손목을 잡았다.<br><br>차다. 가볍다. 놓지 않는다. 커튼 안쪽으로 당긴다. 천천히. 서두르지 않는다.<br>팀원이 돌아본다. 무슨 일인지 모르는 얼굴이다. 이쪽 어깨가 커튼 안으로 들어간다.<br><br>커튼 안은 침대가 아니다. 복도보다 긴 어둠이다.`,
        dieText:`커튼이 다시 닫혔다. 반듯하게.<br><br>팀원은 한참 커튼 앞에 서 있었다. 커튼 아래로 신발 두 켤레가 보였다. 하나는 하얀 신발. 하나는 이쪽 신발.<br>정각에 그 침대에서 대답이 하나 들렸다.` },
      ok:`팔을 넣었다. 하얀 손이 팀원 대신 이쪽 손목을 잡았다.<br><br>잡힌 손목을 비틀지 않았다. 다른 손으로 커튼 봉을 쥐고 힘껏 당겼다. 커튼이 통째로 뜯겨 내려온다. 커튼 뒤가 다 드러났다.<br>하얀 손이 빛에 놀라 이쪽을 놓는다. 손은 빈 침대 밑으로 들어갔다. 숨는 것은 숨는 데가 드러나면 약하다.<br><br>손목에 하얀 손가락 자국이 넷 남았다. 팀원 손목은 깨끗하다.`,
      win:{ exp:24, dream:3 } },
    { l:'② 무력을 실어 커튼 봉으로 손등을 내리친다.', k:'break', dc:21, cost:{ might:24 },
      ok:`커튼 봉을 뽑았다. 무력을 팔에 실어 하얀 손등을 내리쳤다.<br><br>손이 움츠러들어 커튼 안으로 들어간다. 커튼이 한 번 크게 흔들리고 멈춘다.<br>팀원이 그제야 돌아본다. 이쪽 손에 커튼 봉이 들려 있다. 아무 일 없었다고 했다. 커튼 봉은 들고 갔다. 쓸 데가 또 있을 것이다.`,
      ng:`내리쳤는데 손이 봉을 잡는다. 봉째 커튼 안으로 끌려간다.<br><br>놓았다. 봉이 커튼 뒤로 사라졌다. 이번엔 손이 둘 나온다. 하나는 팀원 쪽, 하나는 이쪽.<br>둘이 같이 복도 끝까지 뛰었다. 팀원 소매가 찢겨 커튼 쪽에 남았다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-26, spirit:-14 } }
  ] },

{ at:'B2', t:'계단참 — 백까지 세는 보호사들',
  x:`계단참에 보호사 셋이 벽을 보고 서 있다. 이마를 벽에 댔다. 소리 내어 숫자를 센다.<br><br>
    쉰하나. 쉰둘. 백이 되면 돌아선다. 돌아섰을 때 보이는 사람은 데려간다.<br>
    계단은 보호사들 등 뒤로 지난다. 한 사람씩 발끝으로.<br><br>
    맨 뒤에 서는 사람은 보호사들 등을 끝까지 봐야 한다.`,
  o:[
    { l:'① 넷을 먼저 보내고 맨 뒤에서 보호사들 등을 지켜본다.', k:'steady', dc:21,
      ok:`넷을 먼저 보냈다. 이쪽은 맨 뒤에서 보호사들 등을 봤다. 눈을 떼지 않았다.<br><br>여든. 여든하나. 셋째 보호사 어깨가 들썩인다. 고개가 반쯤 돈다. 이쪽이 그 눈을 마주 봤다. 고개가 멈춘다. 마주 보는 눈이 있으면 돌아서는 데 시간이 걸린다.<br>아흔아홉에 계단 아래로 내려섰다. 백. 셋이 돌아섰다. 계단참은 비어 있었다.`,
      ng:`보는데 셋째 보호사 숫자가 틀린다. 일흔에서 아흔으로 건너뛴다.<br><br>남은 숫자가 반으로 줄었다. 넷째 팀원이 아직 계단참이다. 그 팀원을 안고 계단을 굴렀다.<br>백. 위에서 보호사들이 돌아서는 소리가 났다. 굴러 내려온 둘의 팔다리가 멍투성이다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-26, mind:-14 } },
    { l:'② 숫자에 맞춰 한 사람씩 등을 밀어 보낸다.', k:'bond', dc:20,
      ok:`보호사 숫자에 맞췄다. 열마다 한 사람. 이쪽 손이 등을 밀면 간다.<br><br>예순, 하나. 일흔, 둘. 여든, 셋. 아흔, 넷. 등을 미는 박자가 숫자보다 일정하다.<br>아흔다섯에 이쪽이 내려섰다. 다섯이 남으면 숨을 고를 수 있다.`,
      ng:`밀었는데 둘째가 발을 헛디뎠다. 계단에 무릎을 찧었다. 소리가 났다.<br><br>숫자가 쉰다섯에서 멈춘다. 셋이 동시에 이마를 벽에서 뗀다.<br>나머지는 뛰었다. 보호사 손이 셋째 옷깃을 스쳤다. 그 팔을 쳐냈다. 팔뚝이 저려 한참 칼을 못 쥐었다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-24, spirit:-14 } },
    { l:'③ 보호사들 숫자 사이에 작게 끼어들어 틀리게 센다.', k:'luck', dc:21,
      ok:`보호사 셋의 숫자 사이에 작게 끼어들었다. 예순다섯 다음에 쉰.<br><br>셋째 보호사가 따라 센다. 쉰하나. 다른 둘은 예순여섯. 숫자가 갈라졌다. 셋이 서로 맞추느라 처음부터 다시 센다. 하나, 둘.<br>다섯이 다 내려갔다. 위에서 보호사들이 아직 서른을 세고 있었다.`,
      ng:`끼어드는 순간 셋이 동시에 멈춘다. 벽에 이마를 댄 채로.<br><br>그리고 동시에 센다. 백.<br>돌아선다. 계단참에 이쪽과 넷째가 있다. 보호사 손이 넷째 머리채를 쥐었다. 그 손목을 쳐서 떼어 냈다. 넷째 머리카락 한 움큼이 보호사 손에 남았다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-24, mind:-15 } }
  ] },

{ at:'B2', t:'4층 개방 병동 — 깨어 있는 아이',
  x:`개방 병동 침대에 아이 하나가 깨어 있다. 이불 밖으로 눈만 내놓았다.<br><br>
    같이 가자고 한다. 엄마가 아래층에서 기다린다고. 아이 손목에 띠가 채워져 있다. 이름 대신 번호.<br>
    아이를 데려가면 숫자가 빈다. 안 데려가면 아이는 다음 정각에도 여기 있다.<br><br>
    약한 자를 지킨다. 맹세에는 숫자가 없다.`,
  o:[
    { l:'① 무력을 끌어올려 아이를 업고 계단을 내려간다.', k:'steady', dc:21, cost:{ might:26 },
      ok:`아이를 업었다. 가볍다. 너무 가볍다. 무력은 아이 무게가 아니라 이쪽 다리 떨림을 누르는 데 썼다.<br><br>계단을 세 층 내려갔다. 계단참마다 무언가 이쪽을 본다. 업힌 아이는 안 본다. 업은 사람만 본다.<br>2층 원무과 앞에 여자가 앉아 있다. 아이가 등에서 미끄러져 내려 달려간다. 여자가 아이를 안고 이쪽에 고개를 숙였다.`,
      ng:`업고 내려가는데 아이가 한 층마다 무거워진다.<br><br>세 번째 계단참에서 무릎이 꺾였다. 아이가 등에서 속삭인다. 내려 달라고. 혼자 걷겠다고.<br>내려 줬다. 아이 손을 잡고 걸었다. 다리가 계속 떨렸다. 아이는 한 번도 안 떨었다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-28, mind:-12 } },
    { l:'② 아이에게 계단 아래를 보는 일을 맡기고 손을 잡고 간다.', k:'bond', dc:21,
      ok:`업지 않았다. 아이 손을 잡았다. 그리고 부탁했다. 계단 아래를 보다가 무언가 보이면 손을 꽉 쥐라고.<br><br>아이가 고개를 끄덕인다. 눈이 커진다. 지켜지는 사람이 아니라 지키는 사람의 눈이 됐다.<br>두 번 손을 꽉 쥐었다. 두 번 다 계단 아래 그늘에 무언가 있었다. 두 번 다 비켜 갔다.<br><br>약한 사람을 등 뒤에만 두지 않았다. 옆에 세웠다. 그러자 둘이 다 덜 약해졌다. 맹세 첫 줄이 조금 넓어졌다.`,
      ng:`아이가 손을 꽉 쥔다. 이쪽은 아무것도 못 봤다. 비켜 가려다 계단을 헛디뎠다.<br><br>아이가 본 건 아래가 아니라 위였다. 위에서 흰 가운이 내려다본다. 아이를 안고 뛰었다.<br>두 층을 뛰어 내려오는 동안 아이가 이쪽 목을 너무 세게 쥐었다. 손톱 자국이 남았다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-24, spirit:-15 }, wake:1 }
  ] },

{ at:'B3', t:'연결 통로 — 맨 마지막에 건너는 사람',
  x:`객차 사이 발판이 어긋났다 맞물린다. 틈으로 선로가 하얗게 흘러간다.<br><br>
    한 사람씩 건넌다. 맞물리는 박자에. 맨 뒤는 박자를 세어 줄 사람이 없다.<br>
    견습 기사가 맨 뒤에서 박자를 세어 넷을 보냈다.<br><br>
    이제 이쪽 차례다. 등 뒤 객차 문이 열린다.`,
  o:[
    { l:'① 무력을 끌어올려 발판 두 장에 두 발을 걸쳐 버티며 건넌다.', k:'steady', dc:21, cost:{ might:25 },
      ok:`박자를 기다리지 않았다. 발판 두 장에 두 발을 하나씩 걸쳤다. 무력을 다리로 내렸다.<br><br>발판이 어긋나려 한다. 다리가 벌어진다. 버텼다. 어긋날 자리를 다리가 붙들었다. 그 사이 몸을 앞으로 던졌다.<br>등 뒤 객차 문에서 누가 발판 위로 나왔다. 발판이 다시 어긋났다. 이번엔 그쪽 발밑에서.`,
      ng:`걸쳤는데 발판이 생각보다 세게 벌어진다.<br><br>한쪽 다리가 틈으로 빠졌다. 무릎까지. 자갈 튀는 바람이 정강이를 때린다.<br>앞의 팀원들이 손을 뻗어 끌어올렸다. 정강이 살이 자갈 바람에 벗겨져 있었다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-30, mind:-12 } },
    { l:'② 건너편 팀원에게 이번엔 이쪽 박자를 세어 달라고 한다.', k:'bond', dc:20,
      ok:`건너편 팀원에게 소리쳤다. 이번엔 그쪽이 세어 달라고.<br><br>팀원이 센다. 하나, 둘. 이쪽이 세던 것보다 느리다. 그 느린 박자가 맞았다. 넷을 보내는 동안 이쪽은 박자를 점점 당겨 셌다. 뒤가 급해서.<br>맞물리는 순간 건넜다. 등 뒤 문에서 나온 손이 외투 끝을 스쳤다. 스치기만 했다.`,
      ng:`팀원이 세는데 바퀴 소리에 묻힌다. 둘이 셋으로 들렸다.<br><br>한 박자 늦게 뛰었다. 발판이 어긋나는 순간이다. 건너편 문틀을 손으로 잡았다. 몸이 틈 위에 매달렸다.<br>팀원들이 끌어올렸다. 손가락 마디가 문틀 쇠에 다 까졌다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-26, spirit:-12 } }
  ] },

{ at:'B3', t:'특실 복도 — 한 박자 늦은 발소리',
  x:`특실 복도는 좁다. 일행이 한 줄로 걷는다. 맨 뒤가 이쪽이다.<br><br>
    발소리가 하나 더 있다. 이쪽 바로 뒤. 이쪽 걸음보다 한 박자 늦게.<br>
    멈추면 멈춘다. 걸으면 걷는다. 돌아보면 아무도 없을 것이다. 누가 등받이에 긁어 놓았다. 돌아보지 말 것.<br><br>
    앞의 넷은 아직 모른다.`,
  o:[
    { l:'① 돌아보지 않고 걸음을 늦춰 뒤의 것을 앞의 넷과 떼어 놓는다.', k:'steady', dc:21,
      ok:`걸음을 늦췄다. 반 박자씩. 앞의 넷과 이쪽 사이가 벌어진다. 뒤의 발소리도 따라 늦어진다.<br><br>뒤의 것은 이쪽만 따라온다. 맨 뒤니까. 이쪽이 느려질수록 앞의 넷은 멀어진다.<br>넷이 다음 칸 문을 지나자 걸음을 바꿨다. 반 박자 빠르게. 뒤의 발소리가 박자를 놓친다. 문을 닫았다. 문 너머에서 한 박자 늦은 노크가 한 번 났다.`,
      ng:`늦추는데 뒤의 발소리가 안 늦춰진다. 그대로 온다.<br><br>숨이 목덜미에 닿는다. 차다. 앞으로 휘청여 팀원 등에 부딪혔다. 다섯이 다 넘어질 뻔했다.<br>뛰었다. 다들 영문도 모르고. 목덜미가 한참 얼얼했다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-22, mind:-16 } },
    { l:'② 돌아서서 뒤의 것과 마주 선다.', k:'bond', dc:22,
      ok:`돌아섰다. 아무도 없다. 그래도 섰다. 칼자루에 손을 얹고 빈 복도를 똑바로 봤다.<br><br>발소리가 한 박자 늦게 멈춘다. 이쪽 바로 앞에서. 안 보인다. 그래도 거기 있다. 이쪽이 서 있으니 지나가지 못한다.<br>숨 쉰을 섰다. 앞의 넷이 다음 칸으로 갔다. 그다음 뒷걸음으로 걸었다. 빈 복도를 마주 본 채.<br><br>안 보이는 것 앞에도 설 수 있다. 막는 건 눈이 아니라 서 있는 몸이다. 돌아서는 일이 이제 겁나지 않는다.`,
      ng:`돌아섰다. 아무도 없다. 다시 앞을 봤다.<br><br>앞의 넷이 없다. 복도가 비었다. 발소리가 이번엔 앞에서 난다. 한 박자 늦게.<br>다음 칸 문 앞에서 넷을 찾았다. 넷 다 이쪽을 보고 놀란다. 이쪽은 아까부터 맨 앞에 있었다고 한다. 머리가 한참 울렸다.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-17, spirit:-16 }, wake:1 }
  ] },

{ at:'B3', t:'가는골 승강장 — 저절로 열린 문',
  x:`열차가 서지 않는 역을 지난다. 승강장 불빛이 길게 늘어진다.<br><br>
    객차 문이 저절로 열린다. 바람이 들이친다. 승강장에 사람들이 서 있다. 다 이쪽을 보고 손을 흔든다.<br>
    팀원 하나가 문 쪽으로 걸어간다. 눈이 풀렸다. 승강장에 아는 얼굴이 있다고 한다.<br><br>
    승강장은 달리는 열차 옆을 같은 빠르기로 흘러간다.`,
  o:[
    { l:'① 팀원과 문 사이를 몸으로 막는다.', k:'bond', dc:22,
      doom:{ title:'가는골 승강장', what:'승강장 쪽으로 끌려 나갑니다', dc:18, sec:45,
        text:`문 앞을 막았다. 팀원을 가슴으로 받았다. 등이 문틀에 닿았다.<br><br>등 뒤 승강장에서 손들이 뻗어 온다. 흔들던 손들이다. 외투를 잡는다. 어깨를 잡는다. 팀원 대신 이쪽이 문에 가까웠다.<br>팀원 눈이 돌아온다. 이쪽을 본다. 이쪽은 문 밖으로 기울어 있다.<br><br>승강장 불빛이 등을 비춘다. 따뜻하다. 그게 제일 무섭다.`,
        dieText:`객차 문이 저절로 닫혔다.<br><br>승강장 불빛이 길게 늘어졌다가 끊긴다. 서지 않는 역이다.<br>팀원은 창에 이마를 대고 지나가는 승강장을 봤다. 손을 흔드는 사람들 사이에 하나가 늘어 있었다. 그 사람만 손을 안 흔들었다. 칼자루에 손을 얹고 서 있었다.` },
      ok:`문 앞을 막았다. 팀원을 가슴으로 받았다. 두 팔로 문틀 양쪽을 쥐었다.<br><br>등 뒤 승강장에서 손들이 뻗어 와 외투를 잡는다. 놓지 않았다. 문틀을 쥔 손에 핏줄이 섰다.<br>승강장이 끝났다. 손들이 한꺼번에 떨어진다. 문이 닫혔다. 팀원 눈이 돌아온다. 이쪽 외투 등판이 손자국투성이다.`,
      win:{ exp:25, dream:4 } },
    { l:'② 무력을 끌어올려 팀원을 안고 객차 안쪽으로 끌고 간다.', k:'steady', dc:21, cost:{ might:25 },
      ok:`팀원 허리를 안았다. 무력을 팔로 모았다. 문 반대쪽으로 끌었다.<br><br>팀원이 버둥거린다. 아는 얼굴이 있다고. 놓으라고. 놓지 않았다. 좌석 사이로 끌어 바닥에 눌렀다.<br>승강장이 지나가고 문이 닫혔다. 팀원이 울었다. 그 얼굴이 누구였는지 묻지 않았다.`,
      ng:`안았는데 팀원 힘이 사람 힘이 아니다. 승강장 쪽에서 같이 당긴다.<br><br>둘이 같이 문 쪽으로 미끄러진다. 문틀에 발을 걸었다. 발목이 꺾였다. 다른 팀원 셋이 달려들었다.<br>다섯이 엉켜 쓰러졌을 때 문이 닫혔다. 발목이 부어올랐다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-28, mind:-14 } }
  ] },

{ at:'B3', t:'기관실 옆 — 04:39, 마지막에 뛰는 사람',
  x:`열차가 속도를 줄였다. 기관실 옆 문이 열렸다. 04:39. 내릴 수 있는 건 지금뿐이다.<br><br>
    한 사람씩 뛰어내린다. 빗속 자갈 위로. 열차는 아직 사람 뛰는 것보다 빠르다.<br>
    문틀을 잡고 넷을 차례로 내보냈다. 등을 밀고, 팔을 잡아 주고.<br><br>
    이제 이쪽이 마지막이다. 등 뒤 탄수차 쪽에서 무언가 기어 온다.`,
  o:[
    { l:'① 무력을 다리에 모아 문틀을 박차고 멀리 뛴다.', k:'steady', dc:21, cost:{ might:28 },
      ok:`문틀을 두 손으로 쥐었다. 무력을 다리에 다 모았다. 박찼다.<br><br>빗속으로 몸이 뜬다. 자갈이 다가온다. 굴렀다. 어깨, 등, 무릎 순서로. 배운 대로 떨어졌다. 칼은 끝까지 손에 있었다.<br>일어나 보니 넷이 자갈 위에 있다. 이쪽을 보고 일어선다. 맨 마지막에 떨어진 사람을 기다리고 있었다.<br><br>맨 앞에 서던 몸이 맨 마지막에 떨어지는 법을 알았다. 앞과 끝은 같은 자리였다. 다섯 중 제일 늦게 안전해지는 자리. 무릎이 그 자리를 외웠다.`,
      ng:`박차는데 발이 미끄러졌다. 문턱이 젖었다.<br><br>반쯤 떨어지다 외투가 문틀에 걸렸다. 열차에 매달려 끌려간다. 자갈이 다리를 긁는다. 칼로 외투를 찢었다.<br>떨어져 굴렀다. 넷이 뛰어왔다. 다리 한쪽이 자갈에 다 갈려 있었다.`,
      win:{ exp:24, dream:4 }, lose:{ hp:-30, mind:-12 }, wake:1 },
    { l:'② 뛰기 전에 돌아서서 기어 오는 것 앞의 문을 닫는다.', k:'bond', dc:21,
      ok:`뛰기 전에 돌아섰다. 탄수차 쪽에서 검댕 묻은 손이 기어 온다. 칸막이 문을 밀어 닫았다. 손과 이쪽 사이에.<br><br>닫힌 문을 등지고 뛰어내렸다. 굴렀다. 일어났다.<br>열차가 멀어진다. 닫힌 문 유리창에 손바닥 하나가 붙어 있다. 안에서. 뒤따라 뛰어내릴 것은 없다.`,
      ng:`돌아서서 문을 미는데 손이 먼저 문틈에 끼었다.<br><br>문이 안 닫힌다. 검댕 묻은 손가락이 소매를 잡는다. 뿌리치며 뛰어내렸다. 너무 늦게.<br>자갈 위를 한참 굴렀다. 소매 한쪽이 없다. 팔꿈치에서 손목까지 다 갈렸다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-28, spirit:-14 } }
  ] }

]);

// ──────────────────────────────────────────
// 신호수 (signal) · 자원 없음
// ──────────────────────────────────────────
kJob('signal', 'B', [

{ at:'B', t:'깜빡이는 간판 — 꺼지는 글자의 박자',
  x:`길 건너 건물에 간판이 걸렸다. 네온 글자 넷. 그중 하나가 꺼졌다 켜진다.<br><br>
    신호수는 깜빡임을 보면 고장인지 손인지 안다. 고장은 박자가 없다. 이건 있다. 짧게 셋, 길게 하나. 다시 짧게 셋.<br>
    누가 안에서 스위치를 누른다. 이쪽이 보이는 창을 향해.<br><br>
    도와 달라는 신호일 수도 있다. 이리 오라는 신호일 수도 있다.`,
  o:[
    { l:'① 손전등 덮개로 같은 박자를 되받는다.', k:'bond', dc:21,
      doom:{ title:'되받은 박자', what:'간판 건물로 끌려갑니다', dc:17, sec:55,
        text:`손전등 덮개를 열고 닫았다. 짧게 셋, 길게 하나.<br><br>간판이 멈춘다. 그리고 네 글자가 한꺼번에 켜진다. 거리가 붉어진다. 이쪽 얼굴도.<br>건물 문이 열린다. 안에서 사람들이 나온다. 우산도 없이. 다 이쪽 창을 본다. 신호는 도와 달라는 게 아니었다. 거기 누구 있냐는 거였다.<br><br>대답을 해 버렸다. 손목을 잡혔다. 길을 건너 끌려간다. 간판 아래로.`,
        dieText:`간판 글자 하나가 다시 꺼졌다 켜진다. 짧게 셋, 길게 하나.<br><br>건너편 창가에서 다음 사람이 그걸 본다.<br>스위치를 누르는 손은 이제 신호를 잘 안다. 박자가 정확하다. 배운 손이다.` },
      ok:`손전등 덮개를 열고 닫았다. 짧게 셋, 길게 하나. 끝에 짧게 하나를 덧붙였다. 아무 뜻 없는 하나.<br><br>간판이 멈춘다. 오래. 그리고 대답이 온다. 짧게 셋, 길게 하나, 짧게 하나. 뜻 없는 끝까지 따라 했다.<br>모르는 신호를 그대로 따라 하는 건 흉내다. 사람이면 되물었을 것이다. 손전등을 끄고 창에서 물러났다. 길 건너 건물 문이 열리는 소리가 났다. 아무도 이쪽 창을 찾지 못했다.`,
      win:{ exp:22, dream:3 } },
    { l:'② 대답하지 않고 박자를 끝까지 읽기만 한다.', k:'gaze', dc:20,
      ok:`대답하지 않았다. 읽었다. 짧게 셋, 길게 하나. 반복. 스무 번.<br><br>스물한 번째에 박자가 흐트러진다. 짧게 둘. 손이 지친 것이다. 사람 손이다. 그런데 다음 박자가 너무 빨리 제자리로 돌아온다. 옆에서 다른 손이 대신 누른다.<br>둘이다. 하나는 부르고, 하나는 부르게 시킨다. 창에서 물러났다. 길은 안 건넌다.`,
      ng:`읽는데 깜빡임이 이쪽 눈 박자를 탄다. 이쪽이 감을 때 켜지고 뜰 때 꺼진다.<br><br>눈을 뗄 수 없다. 머리가 저절로 센다. 셋, 하나. 셋, 하나. 팀원이 어깨를 흔들 때까지.<br>한참 눈앞에 붉은 글자가 남았다. 눈을 감아도 깜빡였다.`,
      win:{ exp:16, dream:2, mind:6 }, lose:{ mind:-16, spirit:-14 } }
  ] },

{ at:'B', t:'정전 — 손바닥에 긋는 신호',
  x:`불이 나갔다. 건물 전체가. 창밖 네온도 같이.<br><br>
    어둠 속 어딘가에 쫓는 쪽이 있다. 숨소리가 들린다. 말을 하면 저쪽도 듣는다.<br>
    손짓은 안 보인다. 출발 전에 가르친 손짓 다섯이 다 쓸모없어졌다.<br><br>
    팀원들 손이 어둠 속에서 서로를 더듬는다.`,
  o:[
    { l:'① 옆 사람 손바닥에 손가락으로 신호를 긋는다.', k:'bond', dc:21,
      ok:`옆 사람 손을 잡아 폈다. 손바닥에 검지로 그었다. 아래로 한 줄. 멈춰.<br><br>그 사람이 알아듣는다. 같은 걸 다음 사람 손바닥에 긋는다. 다섯 손바닥에 같은 줄이 그어졌다. 다음엔 동그라미. 따라와. 손을 잡고 한 줄로 어둠을 지났다.<br>쫓는 쪽 숨소리가 한 번 아주 가까이 지나갔다. 아무도 소리를 안 냈다. 손바닥은 소리가 없다.<br><br>눈으로 보던 신호를 살로 옮겼다. 다섯 손짓이 다섯 획이 됐다. 신호가 빛 없이도 간다는 걸 손끝이 알았다.`,
      ng:`손바닥에 그었는데 그 사람이 간지러워 손을 뺀다. 작게 숨을 들이켰다.<br><br>쫓는 쪽 숨소리가 멈추고 이쪽을 향한다. 다들 엎드렸다. 바닥에 무릎을 부딪쳤다.<br>숨소리가 머리 위를 아주 천천히 지나갔다. 등에 찬 바람이 닿았다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-22, mind:-15 }, wake:1 },
    { l:'② 신발을 벗고 발끝으로 바닥을 두드려 울림으로 모은다.', k:'sense', dc:20,
      ok:`신발을 벗었다. 발끝으로 바닥을 두드렸다. 아주 약하게. 둘, 쉼, 둘.<br><br>소리는 작다. 울림은 바닥을 타고 간다. 맨발에 닿는다. 팀원들이 하나씩 이쪽으로 기어 왔다.<br>쫓는 쪽은 신발을 신었다. 바닥 울림을 못 느낀다. 다섯이 모여 벽을 따라 나갔다.`,
      ng:`두드리는데 바닥이 나무다. 울림이 아니라 소리가 난다.<br><br>쫓는 쪽 발소리가 이쪽으로 꺾인다. 맨발로 뛰었다. 깨진 유리를 밟았다.<br>피 묻은 발자국이 어둠 속에 찍혔다. 쫓는 쪽은 그걸 따라올 것이다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-24, spirit:-12 } }
  ] },

{ at:'B', t:'계단참 — 주운 무전기',
  x:`계단참에 무전기가 떨어져 있다. 쫓는 쪽이 흘린 것이다. 아직 켜져 있다.<br><br>
    잡음 사이로 말이 나온다. 말이 아니다. 숫자다. 일곱, 셋, 일곱. 사이에 딸깍.<br>
    남의 신호를 들으면 귀가 먼저 선다. 숫자는 말보다 정직하다. 규칙이 있으니까.<br><br>
    무전기 옆에 젖은 장갑 한 짝이 있다. 주인이 곧 돌아온다.`,
  o:[
    { l:'① 숫자와 딸깍 사이의 규칙을 읽는다.', k:'gaze', dc:21,
      ok:`무전기를 귀에 댔다. 일곱 셋 일곱, 딸깍. 여섯 셋 일곱, 딸깍. 다섯 둘 일곱, 딸깍.<br><br>첫 숫자는 하나씩 준다. 시간이다. 둘째는 층이다. 셋째는 안 변한다. 일곱. 이쪽 수가 아니다. 저쪽 수다. 일곱이 이 건물 안에서 시간을 세며 층을 내려온다.<br>지금 둘째 숫자가 둘이다. 이쪽은 셋에 있다. 반대편 계단으로 갔다.<br><br>남의 신호를 엿들어 읽었다. 보내는 쪽 규칙을 알면 받는 쪽이 아니어도 된다. 귀가 하나 더 생긴 것 같다.`,
      ng:`듣는데 딸깍이 멈춘다. 그리고 무전기에서 숫자가 나온다. 이쪽이 선 층 숫자.<br><br>저쪽에서도 듣고 있다. 무전기를 놓고 뛰었다.<br>계단 아래에서 발소리가 올라온다. 일곱. 위로 뛰다 난간에 손등을 찢었다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-22, mind:-16 }, wake:1 },
    { l:'② 저쪽 박자 그대로 틀린 층 숫자를 흘린다.', k:'luck', dc:21,
      ok:`딸깍 사이에 끼어들어 숫자를 말했다. 저쪽 박자 그대로. 층 숫자만 바꿔서.<br><br>잡음. 그리고 저쪽 숫자들이 바뀐다. 다 이쪽이 말한 층으로 간다. 박자가 맞는 신호는 의심받지 않는다.<br>무전기를 장갑 옆에 도로 놓았다. 장갑 주인이 돌아와 주울 때 이쪽은 두 층 아래에 있었다.`,
      ng:`말했는데 박자가 반 박자 빨랐다.<br><br>무전기가 조용해진다. 잡음까지. 그리고 사람 말이 나온다. 거기 누구냐고.<br>무전기를 던지고 뛰었다. 등 뒤에서 무전기가 계속 묻는다. 누구냐고. 그 목소리가 꿈에까지 따라왔다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-15, spirit:-15 } }
  ] },

{ at:'B', t:'빗속 골목 — 다섯째 휘파람',
  x:`흩어진 팀을 휘파람으로 모은다. 출발 전에 정한 박자다. 길게 하나, 짧게 둘.<br><br>
    불었다. 골목 저쪽에서 대답이 온다. 길게 하나, 짧게 둘. 팀원이다.<br>
    그런데 다른 골목에서도 온다. 같은 박자로. 조금 더 맑게.<br><br>
    팀원은 넷이다. 대답은 다섯이다.`,
  o:[
    { l:'① 휘파람 끝에 팀원만 아는 꼬리 하나를 붙여 다시 분다.', k:'bond', dc:21,
      ok:`다시 불었다. 길게 하나, 짧게 둘. 그리고 아주 짧게 하나를 덧붙였다. 출발 전에 팀원들에게만 일러 둔 꼬리다. 쓸 일은 없을 줄 알았다.<br><br>대답이 온다. 넷은 꼬리까지 분다. 하나는 꼬리 없이 분다. 맑은 쪽이다. 흉내는 들은 것만 흉내 낸다.<br>꼬리 붙은 대답 쪽으로 넷을 모았다. 맑은 휘파람은 한참 혼자 같은 박자를 불었다.<br><br>신호에 남이 모르는 꼬리를 단다. 그게 열쇠가 된다. 이쪽 신호가 처음으로 잠겼다.`,
      ng:`꼬리를 붙였는데 팀원 하나가 꼬리를 잊었다. 꼬리 없이 대답했다.<br><br>그 대답과 맑은 대답이 똑같다. 어느 쪽이 팀원인지 모른다. 둘 다 찾으러 갔다.<br>첫 골목에 팀원이 있었다. 둘째 골목은 비었다. 벽에 젖은 손자국이 입 높이에 찍혀 있었다. 그 골목을 나오다 미끄러져 무릎을 깼다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-22, spirit:-15 }, wake:1 },
    { l:'② 더 불지 않고 다섯 대답이 온 방향을 귀로 잰다.', k:'sense', dc:20,
      ok:`더 불지 않았다. 다섯 대답이 어디서 왔는지 귀로 되짚었다.<br><br>넷은 바람 아래쪽에서 왔다. 빗소리에 조금 먹혔다. 하나는 바람 위쪽에서 왔는데 빗소리에 하나도 안 먹혔다. 비를 안 맞는 데서 분 것이다.<br>지붕 밑이나 문 안. 그쪽은 버리고 넷 쪽으로 갔다. 넷 다 젖어 있었다. 젖은 게 반가웠다.`,
      ng:`재는데 대답이 다시 온다. 부르지도 않았는데.<br><br>이번엔 여섯이다. 흉내 내는 쪽이 늘었다. 귀가 엉켰다.<br>결국 소리를 질러 이름을 불렀다. 넷이 왔다. 소리 지른 자리를 벗어나다 계단에서 굴렀다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-24, mind:-13 } }
  ] },

{ at:'B', t:'모퉁이 — 붙들린 손의 손짓',
  x:`앞서 간 팀원이 모퉁이 너머에서 손짓을 보낸다. 가.<br><br>
    손목이 꺾였다. 그 팀원 버릇이다. 맞다.<br>
    그런데 손짓이 너무 느리다. 손가락 끝이 떨린다. 손목 위 소매가 누군가에게 쥐인 것처럼 구겨졌다.<br><br>
    팀원이 이쪽을 판 걸까. 아니면 누가 팀원 팔을 쥐고 흔드는 걸까.`,
  o:[
    { l:'① 되묻는 손짓을 보낸다 — 나를 봐.', k:'bond', dc:21,
      ok:`나를 봐를 보냈다. 얼굴을 보이라는 뜻이다.<br><br>손짓이 멈춘다. 그리고 아주 작게 바뀐다. 손가락 하나가 뒤를 가리킨다. 뒤. 그리고 다시 가. 억지로.<br>팀원은 이쪽을 판 게 아니다. 뒤에 누가 있다고 말하고 있다. 가라는 손짓을 하면서. 할 수 있는 만큼.<br><br>모퉁이를 돌지 않았다. 반대편 통로로 크게 돌아 뒤로 갔다. 팀원 뒤의 것이 이쪽을 못 봤다. 팀원 팔을 쥔 손을 떼어 냈다.`,
      ng:`나를 봐를 보냈는데 손짓이 나를 봐로 되받는다. 꺾인 손목으로.<br><br>팀원 버릇까지 흉내 낸다. 팀원 팔을 쥔 쪽이. 모퉁이 너머로 웃음 같은 숨이 들린다.<br>뛰어 들어가 팀원을 낚아챘다. 뒤의 것이 팀원 소매를 찢었다. 둘이 같이 벽에 부딪혔다. 이마가 찢어졌다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-26, mind:-14 } },
    { l:'② 손가락 끝 떨림을 끝까지 읽는다.', k:'gaze', dc:20,
      ok:`떨림을 셌다. 박자가 일정하다. 겁먹은 떨림은 박자가 없다. 이건 있다. 짧게 셋, 길게 셋, 짧게 셋.<br><br>떨림 속에 신호가 숨어 있다. 손짓은 가인데 떨림은 다른 말을 한다. 위험.<br>팀원이 손가락 끝으로 말하고 있었다. 반대로 갔다. 팀원은 나중에 혼자 빠져나와 합류했다. 손목에 남의 손자국이 있었다.`,
      ng:`떨림을 읽는 사이 손짓이 사라졌다. 모퉁이 너머가 조용하다.<br><br>들어가 봤다. 바닥에 팀원 신발 한 짝. 벽에 숯으로 손짓 하나가 그려져 있다. 가.<br>신발을 챙기는 손이 떨렸다. 다음 층에서 팀원을 찾았다. 둘 다 한참 말을 못 했다.`,
      win:{ exp:18, dream:2, spirit:6 }, lose:{ mind:-17, spirit:-16 } },
    { l:'③ 아무 신호도 보내지 않고 모퉁이 앞에서 기다린다.', k:'steady', dc:21,
      ok:`아무것도 보내지 않았다. 대답하지 않는 것도 신호다. 모르겠다는 뜻.<br><br>손짓이 계속된다. 가. 가. 가. 점점 빨라진다. 그러다 멈춘다. 모퉁이 너머에서 발소리가 멀어진다. 팀원 발소리 하나, 다른 발소리 하나.<br>한참 뒤 팀원 혼자 돌아왔다. 붙들고 있던 것이 이쪽이 안 오니 놓고 갔다고 한다. 미끼는 안 물면 쓸모가 없다.`,
      ng:`기다리는데 손짓이 바뀐다. 위험. 팀원 버릇대로 손목이 꺾인 위험.<br><br>진짜 신호다. 팀원이 뒤의 것을 뿌리친 것이다. 기다린 만큼 늦었다. 뛰어 들어갔다.<br>팀원은 벽에 등을 붙이고 있었다. 팔뚝에 긁힌 자국이 길다. 혼자 버틴 자국이다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-16, spirit:-15 } }
  ] },

{ at:'B', t:'빈 사무실 — 끊기지 않는 전화',
  x:`빈 사무실 책상에 전화기가 있다. 울린다. 열 번. 스무 번. 안 끊긴다.<br><br>
    수화기 옆에 메모가 붙었다. 받지 말 것.<br>
    벨 사이에 소리가 있다. 수화기 안에서 누가 두드린다. 똑, 똑똑. 박자로 들린다. 사람이 하는 박자다.<br><br>
    아니면 사람인 척하는 박자다.`,
  o:[
    { l:'① 수화기를 들고 말없이 두드림으로만 대답한다.', k:'bond', dc:21,
      doom:{ title:'수화기 너머', what:'수화기 속으로 끌려 들어갑니다', dc:17, sec:55,
        text:`수화기를 들었다. 말하지 않았다. 손톱으로 송화구를 두드렸다. 똑, 똑똑.<br><br>저쪽이 같은 박자로 대답한다. 그리고 두드림이 멈추고 숨소리가 난다. 이쪽 숨소리다. 이쪽이 쉬기도 전에.<br>수화기를 내려놓으려는데 손이 안 움직인다. 귀가 수화기에 붙었다. 숨이 수화기 속으로 빨려 간다.<br><br>목소리가 나간다. 말한 적도 없는데.`,
        dieText:`수화기가 책상 위에 놓였다. 반듯하게.<br><br>전화는 다시 울리지 않았다. 다음 날 밤 다른 건물 다른 책상에서 울렸다.<br>받는 사람 귀에 두드림이 들렸다. 똑, 똑똑. 이쪽 손톱 박자였다.` },
      ok:`수화기를 들었다. 말하지 않았다. 손톱으로 송화구를 두드렸다. 똑, 똑똑. 그리고 일부러 박자 하나를 틀렸다.<br><br>저쪽이 틀린 박자까지 똑같이 따라 한다. 사람이면 고쳐 주거나 되물었을 것이다. 따라 하기만 하는 건 귀가 없는 것이다.<br>수화기를 내려놓고 전화선을 뽑았다. 벨이 멈췄다. 메모 뒷면에 볼펜 글씨가 있다. 따라 하면 끊어. 앞사람도 신호를 아는 사람이었다.`,
      win:{ exp:24, dream:3 } },
    { l:'② 수화기는 두고 전화선을 따라가 본다.', k:'sense', dc:20,
      ok:`수화기는 안 들었다. 전화선을 따라갔다. 벽을 타고 천장으로. 복도로. 계단으로.<br><br>선이 계단 밑 배전함으로 들어간다. 문틈으로 빛이 샌다. 안에 노인이 수화기를 쥐고 앉아 있다. 사람이다. 울리게만 하고 있다.<br>노인이 먼저 말했다. 받는 사람이 있는 한 아직 산 사람이 있는 거라고. 받지 말라는 메모도 노인이 붙였다. 둘 다 진심이었다.`,
      ng:`선을 따라가는데 선이 끝없이 이어진다. 같은 복도를 세 번 지났다.<br><br>네 번째 지날 때 사무실 전화가 멈췄다. 누가 받았다. 이쪽이 없는 사이.<br>돌아가 보니 팀원 하나가 귀를 문지르며 아무 말도 안 들렸다고 한다. 그 팀원 목소리가 조금 낮아져 있었다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-16, spirit:-15 } }
  ] },

{ at:'B', t:'길 건너 — 갈라진 팀과 거울 조각',
  x:`길이 팀을 갈랐다. 둘은 이쪽 처마, 셋은 길 건너 처마. 사이로 차가 지나간다. 전조등이 없다.<br><br>
    소리치면 안 된다. 길 위에 서 있는 것들이 있다. 우산을 쓰고. 움직이지 않는다.<br>
    손에 깨진 거울 조각이 있다. 아까 주웠다. 간판 불빛이 그 위에 붉게 앉는다.<br><br>
    길 건너 셋이 이쪽을 찾는다. 방향을 모른다.`,
  o:[
    { l:'① 거울 조각에 간판 빛을 받아 셋에게 길을 그려 보인다.', k:'bond', dc:20,
      ok:`거울을 기울여 간판 빛을 받았다. 붉은 점을 길 건너 처마 기둥에 올렸다. 셋 중 하나가 본다.<br><br>점을 천천히 움직였다. 기둥에서 바닥으로. 바닥을 따라 배수로로. 배수로 다리 밑이 건너는 길이다. 우산들이 안 보는 데.<br>셋이 점을 따라 기어 왔다. 우산들은 그대로 서 있다. 붉은 점은 간판 빛이 튄 것일 뿐이다. 누구도 그걸 신호로 안 본다. 받는 사람만 본다.`,
      ng:`거울을 기울이는데 붉은 점이 우산 하나에 닿았다.<br><br>우산이 천천히 돌아선다. 이쪽 처마를 본다. 거울을 감췄다. 늦었다.<br>우산이 길을 건너온다. 둘은 처마를 버리고 뛰었다. 셋은 반대로 뛰었다. 다시 만나는 데 한 시간이 걸렸다. 그동안 무릎이 두 번 깨졌다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-24, mind:-13 } },
    { l:'② 빗물 웅덩이에 돌을 던져 물소리로 길을 알린다.', k:'luck', dc:21,
      ok:`길가 웅덩이에 돌을 하나 던졌다. 셋이 그 소리에 웅덩이를 본다.<br><br>하나 더. 배수로 쪽 웅덩이에. 또 하나. 다리 밑에. 돌 떨어지는 소리가 빗소리에 섞여 우산들은 모른다.<br>셋이 웅덩이를 차례로 따라와 다리 밑에서 만났다. 빗속 신호는 빗소리 속에 숨겨야 한다.`,
      ng:`던진 돌이 웅덩이가 아니라 우산을 맞혔다.<br><br>우산 위에서 돌이 튀는 소리. 우산들이 일제히 이쪽으로 돌아본다.<br>뛰었다. 젖은 차도에서 미끄러져 팔꿈치가 아스팔트에 갈렸다. 길 건너 셋도 들켰다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-24, spirit:-13 } }
  ] },

{ at:'B', t:'쉬는 자리 — 여섯째 손짓',
  x:`쉬는 자리에서 팀원들이 이쪽을 본다. 여기서는 얼굴을 못 믿는다고 한다. 옆에 선 사람이 팀원인지 모를 때가 있다고.<br><br>
    가르친 손짓은 다섯이다. 멈춰, 가, 아래, 위험, 나를 봐.<br>
    하나가 더 필요하다. 이 사람은 우리 편이 아니다.<br><br>
    그 손짓을 정하면 언젠가 쓰게 된다. 팀원끼리.`,
  o:[
    { l:'① 아무 눈에도 신호로 안 보일 여섯째 손짓을 같이 정한다.', k:'bond', dc:21,
      ok:`다섯이 둘러앉아 정했다. 눈에 띄면 안 된다. 손짓처럼 보이면 안 된다.<br><br>엄지로 검지 첫마디를 두 번 긁는 것. 손이 가려울 때 하는 짓이다. 아무도 신호로 안 본다.<br>다음 층에서 쓸 일이 생겼다. 옆 팀원 얼굴이 조금 늦게 웃었다. 맞은편 팀원 엄지가 검지를 두 번 긁었다. 다들 그 사람에게서 천천히 떨어졌다. 얼굴이 원래대로 돌아오기 전에.<br><br>신호처럼 안 보이는 신호. 손짓이 여섯이 됐다. 손은 그 여섯째를 제일 자주 떠올린다.`,
      ng:`정하는데 팀원 하나가 그런 손짓은 싫다고 한다. 언젠가 자기한테 쓰일까 봐.<br><br>다들 말이 없어진다. 서로 얼굴을 본다. 지금 그 말을 한 얼굴이 진짜인지.<br>손짓은 못 정했다. 밤새 서로를 봤다. 아무도 못 잤다. 다음 날 다들 발이 무거웠다.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-16, spirit:-15 }, wake:1 },
    { l:'② 손짓을 늘리는 대신 서로의 버릇을 하나씩 외워 두자고 한다.', k:'gaze', dc:20,
      ok:`손짓은 안 늘렸다. 서로의 버릇을 하나씩 말하게 했다. 숨 쉬는 박자, 발 끄는 소리, 대답 전에 하는 기침.<br><br>다섯이 다섯 버릇을 외웠다. 얼굴은 바꿀 수 있어도 버릇은 늦게 붙는다.<br>다음 층에서 팀원 하나가 대답 전에 기침을 안 했다. 넷이 동시에 알아챘다. 그 하나는 팀원이 아니었다. 진짜 팀원은 한 칸 뒤에서 기침을 하고 있었다.`,
      ng:`버릇을 말하는 걸 쉬는 자리 구석 어둠에서 누가 듣고 있었다.<br><br>다음 층에서 그 버릇들이 하나씩 흉내 내졌다. 숨 박자, 발소리, 기침까지. 더 헷갈린다.<br>팀원끼리 서로 손을 놓지 못하고 걸었다. 다들 손이 땀으로 미끄러웠다.`,
      win:{ exp:18, dream:2, mind:6 }, lose:{ mind:-15, spirit:-16 } }
  ] },

{ at:'B1', t:'항구 — 늘어나는 고동',
  x:`바다 쪽에서 고동이 운다. 해무호다. 짧게 둘.<br><br>
    한참 있다 다시 운다. 짧게 둘, 길게 하나. 그다음엔 짧게 둘, 길게 둘.<br>
    배 고동은 아무렇게나 울지 않는다. 부두에 있는 사람들에게 하는 말이다.<br><br>
    길게 우는 횟수가 하나씩 는다.`,
  o:[
    { l:'① 고동 박자를 세어 무슨 말인지 읽는다.', k:'gaze', dc:21,
      ok:`세 번째 고동까지 셌다. 짧게 둘은 부르는 소리다. 길게는 숫자다. 하나, 둘. 는다.<br><br>창고 칠판의 숫자가 떠올랐다. 전량 다섯. 고동은 실은 것을 세고 있다. 다섯이 되면 다 실었다는 뜻이다. 지금 둘.<br>둘이 실렸다. 이쪽 팀은 아니다. 남은 셋 자리를 채우러 노란 비옷들이 돌아다닌다. 그 셋이 이쪽이 되기 전에 움직였다.`,
      ng:`세는데 고동이 멈춘다. 그리고 아주 가까이서 운다. 창고 바로 밖에서.<br><br>배 고동이 아니다. 누가 입으로 흉내 낸다. 짧게 둘, 길게 셋. 숫자가 이쪽 쪽으로 온다.<br>상자 뒤에 숨어 숨을 죽였다. 흉내 고동이 머리 위에서 한 번 더 울었다. 귀가 한참 멍했다.`,
      win:{ exp:18, dream:3 }, lose:{ mind:-16, spirit:-14 } },
    { l:'② 고동이 우는 동안에만 움직이도록 손짓한다.', k:'bond', dc:20,
      ok:`고동이 우는 동안만 움직였다. 손짓으로 정했다. 소리가 나면 가, 그치면 멈춰.<br><br>길게 우는 동안 다섯이 컨테이너 셋을 지났다. 그치면 섰다. 다시 울면 또.<br>고동은 이쪽에게 하는 말이 아니었다. 그래도 이쪽이 썼다. 남의 신호 위에 이쪽 신호를 얹었다.`,
      ng:`길게 울 줄 알았는데 짧게 끝났다. 다섯이 길 한가운데서 멈췄다.<br><br>탐조등이 그 자리를 지난다. 넷은 엎드렸다. 이쪽은 손짓을 하느라 늦었다. 빛이 손등에 닿았다.<br>빛이 멈춘다. 뛰었다. 컨테이너 모서리에 어깨를 박았다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-24, mind:-12 } }
  ] },

{ at:'B1', t:'방파제 — 꺼진 등대',
  x:`방파제 끝 등대가 꺼져 있다. 유리가 깨졌다. 안에 기름 등잔이 남았다.<br><br>
    바다에 작은 배 하나가 떠 있다. 불이 없다. 방파제를 못 찾고 맴돈다. 노 젓는 소리가 들린다. 사람이다.<br>
    등대에 불을 켜면 배가 방파제를 찾는다. 해무호도 그 불을 본다.<br><br>
    파도가 방파제 위를 넘기 시작한다.`,
  o:[
    { l:'① 등대에 올라 등잔을 켜고 덮개로 박자를 보낸다.', k:'bond', dc:22,
      doom:{ title:'넘어오는 파도', what:'파도에 휩쓸려 끌려갑니다', dc:18, sec:45,
        text:`등대 사다리를 올랐다. 등잔에 불을 붙였다. 덮개를 열었다 닫았다. 길게 하나, 짧게 셋. 이리 오라는 뜻이다.<br><br>작은 배가 방향을 튼다. 됐다. 그런데 해무호 쪽 탐조등도 이쪽을 향한다.<br>내려오는 사다리에 파도가 덮쳤다. 손이 미끄러졌다. 방파제 위로 떨어졌다. 다음 파도가 온다. 몸이 바다 쪽으로 쓸린다.<br><br>작은 배에서 누가 소리친다. 이쪽 이름이 아니다. 아무 이름이나.`,
        dieText:`작은 배는 등대 불을 보고 방파제에 닿았다.<br><br>배에서 내린 사람이 등대를 올려다봤다. 등잔은 아직 탄다. 덮개가 바람에 열렸다 닫혔다 한다. 길게 하나, 짧게 셋.<br>누가 보냈는지 모르는 신호가 새벽까지 바다를 불렀다.` },
      ok:`등대 사다리를 올랐다. 등잔에 불을 붙였다. 덮개를 열었다 닫았다. 길게 하나, 짧게 셋.<br><br>작은 배가 방향을 튼다. 해무호 쪽 탐조등도 이쪽을 향한다. 덮개를 반쯤 닫았다. 불은 켜 둔 채. 덮개 틈으로 배 쪽에만 빛이 새게.<br>파도를 두 번 맞고 내려왔다. 작은 배가 방파제에 닿았다. 늙은 어부다. 배에 남은 민물고기 하나를 내밀며 묻는다. 등대 덮개를 어떻게 그렇게 돌렸냐고.`,
      win:{ exp:24, dream:4, item:'민물고기' } },
    { l:'② 방파제 끝에 엎드려 손전등을 물 위로만 낮게 비춘다.', k:'hide', dc:21,
      ok:`등대에 오르지 않았다. 방파제 끝에 엎드려 손전등을 바다 쪽으로 낮게 비췄다. 물 위로만.<br><br>빛이 파도에 부서진다. 배에서는 보인다. 해무호에서는 파도에 튄 빛과 구별이 안 된다.<br>배가 빛을 따라 들어왔다. 노 젓는 사람이 고개를 숙인다. 말은 안 했다. 빛으로 불렀으니 대답도 빛이 안 나게 했다.`,
      ng:`엎드렸는데 파도가 방파제를 넘었다. 손전등이 휩쓸려 갔다.<br><br>이쪽도 반쯤 쓸렸다. 방파제 가장자리 쇠고리를 잡았다. 손바닥이 찢겼다.<br>바다에 손전등 빛이 가라앉으며 깜빡인다. 배가 그 빛을 따라간다. 방파제가 아니라 바다 쪽으로.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-28, spirit:-12 } }
  ] },

{ at:'B1', t:'컨테이너 야적장 — 탐조등의 박자',
  x:`야적장 탐조등이 돈다. 한 바퀴에 숨 마흔.<br><br>
    도는 빛을 보면 박자부터 잰다. 마흔. 그런데 크레인 쪽을 지날 때만 숨 다섯 동안 멈춘다. 그쪽에서 누가 보고를 받는다.<br>
    팀은 컨테이너 그늘 다섯 군데에 흩어졌다. 서로 안 보인다. 탐조등과 팀원들이 다 보이는 건 이쪽뿐이다.<br><br>
    다섯을 한 박자로 움직여야 한다.`,
  o:[
    { l:'① 빛이 멈추는 다섯 숨마다 한 사람씩 손짓으로 보낸다.', k:'bond', dc:21,
      ok:`빛이 크레인 쪽에서 멈추는 다섯 숨. 그때마다 한 사람에게 손짓했다. 가.<br><br>첫째가 다음 그늘로 간다. 빛이 돌아온다. 멈춰. 빛이 다시 크레인 쪽. 둘째. 다섯 바퀴에 다섯이 야적장 끝까지 왔다.<br>빛보다 빠른 사람은 없다. 빛의 박자를 아는 사람이 있을 뿐이다. 그 박자를 넘겨주면 다섯이 다 빛을 안다.<br><br>남의 박자를 재서 이쪽 박자로 바꿔 나눠 준다. 손이 이제 시계 노릇을 한다.`,
      ng:`셋째에게 손짓하는데 빛이 크레인 쪽에서 안 멈춘다. 보고가 짧았다.<br><br>셋째가 이쪽 손짓을 따라 빛 한가운데로 뛰어나왔다. 빛이 셋째에 멈춘다.<br>소리를 질러 빛을 이쪽으로 끌었다. 둘이 같이 쫓겼다. 철판 모서리에 정강이를 찢었다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-26, mind:-14 }, wake:1 },
    { l:'② 빛이 크레인 쪽을 볼 때 다섯을 한꺼번에 뛰게 한다.', k:'evade', dc:21,
      ok:`손짓 하나로 다섯을 다 움직이기로 했다. 크레인 쪽 다섯 숨. 다 같이 가.<br><br>다섯이 동시에 그늘을 나와 야적장 끝으로 뛰었다. 다섯 숨이면 스무 걸음이다. 딱 스무 걸음이었다.<br>빛이 돌아왔을 때 야적장은 비었다. 빛은 늘 같은 데를 비춘다. 사람은 그렇지 않다.`,
      ng:`다 같이 뛰었는데 둘째가 손짓을 늦게 봤다.<br><br>빛이 돌아왔을 때 둘째가 한가운데 있다. 넷이 돌아가 끌었다. 다섯이 다 빛에 들었다.<br>크레인 쪽에서 무전기 소리가 났다. 다들 흩어져 뛰었다. 다시 모이는 데 오래 걸렸다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-26, spirit:-13 } }
  ] },

{ at:'B1', t:'냉동 창고 — 불이 꺼진 뒤 세는 목소리',
  x:`냉동 창고 불이 나갔다. 깜깜하다. 숨이 하얗게 나오는 것도 안 보인다.<br><br>
    어둠 속에서 목소리가 센다. 하나. 둘. 사람 수를 센다. 다섯까지 세면 무언가 한다.<br>
    팀원들이 갈고리 레일 사이 어딘가에 흩어져 있다.<br><br>
    손이 레일에 닿는다. 쇠는 소리를 멀리 보낸다.`,
  o:[
    { l:'① 레일을 손톱으로 두드려 이리 오라는 박자를 보낸다.', k:'bond', dc:21,
      ok:`레일을 손톱으로 쳤다. 아주 작게. 둘, 쉼, 하나.<br><br>쇠가 소리를 실어 간다. 레일 끝까지. 레일에 손이 닿아 있으면 들린다. 팀원들이 하나씩 레일을 더듬어 왔다.<br>셋까지 셌던 목소리가 멈춘다. 넷을 못 찾는다. 다섯이 한 자리에 붙어 있으면 하나로 센다. 목소리가 하나라고 말하고 그쳤다.`,
      ng:`두드렸는데 쇠가 너무 잘 운다. 레일 전체가 노래한다.<br><br>목소리가 세기를 멈추고 소리 쪽으로 온다. 레일을 따라. 이쪽 손가락이 닿은 데로.<br>손을 떼고 굴렀다. 갈고리 하나가 이쪽이 있던 자리를 긁고 지나갔다. 귓바퀴가 찢겼다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-26, mind:-13 } },
    { l:'② 목소리 박자를 듣고 숫자 사이에만 움직이게 한다.', k:'sense', dc:21,
      ok:`목소리 박자를 들었다. 숫자 사이가 길다. 숨 여섯. 셀 때는 멈춘다. 셀 때만 듣는다.<br><br>숫자와 숫자 사이에 손뼉을 한 번 쳤다. 아주 작게. 팀원들이 그 소리에 움직였다. 셀 때는 다 멈췄다.<br>다섯이 문 앞에 모였다. 목소리가 넷까지 세다가 길을 잃는다. 어둠 속에서 다시 처음부터 센다. 하나.`,
      ng:`숫자 사이에 손뼉을 쳤는데 목소리가 손뼉을 센다. 하나.<br><br>팀원이 움직이자 둘. 이쪽이 움직이자 셋. 소리마다 세어진다.<br>다들 얼어붙은 채 숨만 쉬었다. 숨소리도 세어질까 봐. 손가락이 얼어 갈 때까지.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-16, spirit:-14 } },
    { l:'③ 세는 목소리에게 틀린 숫자를 먼저 대 준다.', k:'luck', dc:21,
      ok:`목소리가 셋을 셀 때 작게 말했다. 다섯.<br><br>목소리가 멈춘다. 다섯을 셌다고 믿는다. 숫자를 다 채웠다. 무언가 해야 할 차례인데 다섯이 어디 있는지 모른다. 다시 센다. 처음부터. 하나.<br>세는 사이 문 앞에 모였다. 세는 쪽은 듣는 대로 센다. 신호는 받는 쪽을 속일 수도 있다.`,
      ng:`다섯이라고 하자 목소리가 이쪽 바로 앞에서 대답한다. 여섯.<br><br>이쪽 목소리까지 셌다. 어둠 속에서 갈고리 레일이 움직이기 시작한다.<br>바닥에 엎드려 기었다. 갈고리가 등 위로 지나갔다. 외투 등판이 찢겼다. 쇠가 닿은 자리가 한참 시렸다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-24, mind:-14 } }
  ] },

{ at:'B2', t:'7층 복도 — 병실마다의 호출등',
  x:`복도 천장에 병실마다 호출등이 달려 있다. 누르면 빨갛게 켜진다. 켜지면 간호사가 간다.<br><br>
    간호사 셋이 복도 끝 간호사실에 앉아 있다. 이쪽은 반대편 끝이다. 가운데 이중문이 있다.<br>
    신호수 눈에 호출등은 줄지은 깃발이다. 켜고 끄는 순서로 말을 할 수 있다.<br><br>
    간호사들이 갈 방향을 이쪽이 정해 줄 수도 있다.`,
  o:[
    { l:'① 반대편 끝부터 호출등을 차례로 켜서 간호사들을 그쪽으로 돌린다.', k:'fix', dc:21,
      ok:`병실을 하나 걸러 들어가 단추를 눌렀다. 복도 반대편 끝부터.<br><br>호출등이 차례로 켜진다. 간호사들이 일어선다. 켜진 순서대로 간다. 등 하나에 한 사람. 셋이 다 반대편 끝에 가 있다.<br>그 사이 이중문을 지났다. 문 위 스피커가 딸깍한다. 호출등은 아직 다 빨갛다. 간호사들이 병실마다 빈 침대를 세고 있다.`,
      ng:`셋째 단추를 누르는데 첫째 등이 꺼진다. 간호사가 벌써 갔다.<br><br>순서가 꼬였다. 간호사 하나가 단추 누르는 소리를 따라 이쪽으로 온다.<br>침대 밑에 숨었다. 하얀 신발이 침대 옆에 오래 섰다. 바닥이 차서 등이 굳었다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-15, spirit:-15 } },
    { l:'② 호출등을 깜빡여 다른 병실의 깨어 있는 사람들과 박자를 주고받는다.', k:'bond', dc:21,
      ok:`단추를 짧게 눌렀다 뗐다. 등이 깜빡한다. 셋, 하나.<br><br>복도 저쪽 병실 등이 깜빡인다. 셋, 하나. 깨어 있는 누가 대답한다. 그 사람이 다른 박자를 보낸다. 짧게 둘. 간호사실 쪽 등이 깜빡였다. 간호사들이 그쪽으로 일어선다.<br>병실 사람들이 이쪽 대신 간호사들을 움직였다. 이쪽은 박자 하나를 보냈을 뿐이다. 이중문을 지날 때 병실 등들이 다 같이 한 번 깜빡였다. 잘 가라는 것 같았다.`,
      ng:`깜빡였는데 대답한 병실 등이 꺼지지 않는다. 계속 켜져 있다.<br><br>간호사들이 그 병실로 간다. 이쪽 박자에 대답한 값을 그 사람이 치른다.<br>이중문을 지나는 동안 그 병실에서 딸깍 소리가 났다. 뒤를 돌아보지 못했다.`,
      win:{ exp:20, dream:3 }, lose:{ mind:-17, spirit:-16 } },
    { l:'③ 지나가며 호출등 단추를 한꺼번에 다 누른다.', k:'luck', dc:21,
      ok:`지나가며 단추를 손바닥으로 다 쳤다. 병실 다섯. 호출등이 한꺼번에 켜진다.<br><br>간호사 셋이 일어선다. 어디부터 갈지 모른다. 셋이 세 방향으로 갈라진다. 가운데가 비었다.<br>그 가운데로 이중문을 지났다. 등이 다섯이면 간호사 셋으로는 다 못 간다. 숫자가 모자란 쪽이 진다.`,
      ng:`다 눌렀는데 간호사들이 안 일어선다. 앉아서 호출등을 본다. 다섯이 한꺼번에 켜지는 일은 없다는 걸 안다.<br><br>셋이 동시에 일어나 이쪽으로 온다. 등이 켜진 병실이 아니라 등을 켠 사람에게로.<br>침대 밑에 숨었다. 하얀 신발 셋이 침대를 둘러쌌다. 숨을 너무 참아 가슴이 찢어질 듯했다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-20, mind:-16 } }
  ] },

{ at:'B2', t:'6층 — 줄무늬 복도의 딸깍 소리',
  x:`6층은 불이 한 칸씩 걸러 켜졌다. 복도가 줄무늬다. 어디선가 딸깍 소리가 온다. 다가왔다 멀어진다.<br><br>
    간호사가 둘인지 셋인지 모른다. 안 보인다. 소리만 있다.<br>
    귀를 기울이면 딸깍마다 높이가 다르다. 계수기마다 쇠가 다르게 운다.<br><br>
    소리로 그림을 그릴 수 있다면.`,
  o:[
    { l:'① 딸깍 소리의 높이와 박자로 간호사들 자리를 그린다.', k:'sense', dc:21,
      ok:`눈을 감았다. 딸깍을 하나씩 들었다. 높은 것, 낮은 것, 탁한 것. 셋이다.<br><br>높은 것은 빠르다. 복도를 돈다. 낮은 것은 느리다. 병실을 하나씩 들어간다. 탁한 것은 안 움직인다. 계단 문 앞에서 같은 박자로 딸깍만 한다. 지키는 것이다.<br>높은 것이 멀어지고 낮은 것이 병실에 든 사이 탁한 것 반대편 비상문으로 갔다. 소리로 그린 지도가 맞았다.<br><br>소리마다 얼굴을 붙였다. 눈 대신 귀로 자리를 그린다. 신호를 받던 귀가 이제 신호 아닌 소리도 읽는다.`,
      ng:`듣는데 딸깍이 넷이 된다. 넷째는 이쪽 바로 뒤에서 난다.<br><br>눈을 떴다. 아무도 없다. 다시 감으니 넷째가 들린다. 이쪽 심장 박자에 맞춰서.<br>복도를 뛰어 빠져나왔다. 빠져나온 뒤에도 넷째가 귀에서 안 떨어졌다. 한참 뒤에 그게 이쪽 이 부딪는 소리라는 걸 알았다.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-17, spirit:-15 }, wake:1 },
    { l:'② 불 꺼진 칸만 밟도록 손짓으로 끌고 간다.', k:'bond', dc:20,
      ok:`불 꺼진 칸에서 불 꺼진 칸으로. 한 칸씩. 손짓으로 다섯을 끌었다. 가, 멈춰, 가.<br><br>켜진 칸은 건너뛰었다. 줄무늬 복도에서 어두운 줄만 밟으면 사람은 안 보인다. 딸깍 소리가 두 번 바로 옆을 지나갔다. 둘 다 켜진 칸에서.<br>마지막 칸이 켜져 있다. 다섯이 숨을 참고 그 칸을 한 번에 건넜다.`,
      ng:`손짓을 하는 손이 켜진 칸에 들어갔다. 손만.<br><br>딸깍이 멈춘다. 켜진 칸에 손 하나가 떠 있다. 간호사가 그걸 본다. 손을 거뒀다. 늦었다.<br>칸 가리지 않고 뛰었다. 계단 문에 팔꿈치를 박았다. 뼈가 울렸다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-24, mind:-13 } }
  ] },

{ at:'B2', t:'기록 보관실 — 환기 덕트 너머의 두드림',
  x:`기록 보관실 환기구 철망 너머에서 두드리는 소리가 난다. 덕트 안이다.<br><br>
    똑, 똑, 똑. 쉼. 똑, 똑, 똑. 사람이 쇠를 두드린다.<br>
    덕트는 층과 층을 잇는다. 아래층 누군가가 덕트를 타고 있다. 아니면 갇혔다.<br><br>
    쇠 너머에서 박자가 오면 손이 먼저 쇠로 간다.`,
  o:[
    { l:'① 두드림으로 말을 정하고 길을 주고받는다.', k:'bond', dc:21,
      ok:`철망에 손톱을 댔다. 둘, 쉼, 하나. 이쪽 말을 먼저 정했다. 하나는 예, 둘은 아니오.<br><br>저쪽이 따라 한다. 물었다. 갇혔냐. 둘. 길을 아냐. 하나. 몇 층이냐. 셋.<br>그다음은 저쪽이 말을 만들었다. 길게 긁는 소리는 왼쪽. 짧게 찍는 소리는 아래. 이쪽이 정한 말 위에 저쪽이 말을 하나씩 얹었다. 그대로 덕트를 탔다. 셋째 꺾인 데서 저쪽 사람 손이 이쪽 손을 잡아끌었다.<br><br>주고받다 둘이 같이 새 말을 지었다. 한쪽이 가르치는 신호가 아니라 같이 짓는 신호. 손톱 끝에 그 감각이 남았다.`,
      ng:`두드렸는데 저쪽 두드림이 멈춘다. 그리고 덕트 안에서 무언가 기어 오는 소리.<br><br>사람이 아니다. 너무 빠르다. 철망이 안쪽에서 부딪친다. 나사가 하나 튄다.<br>서가를 밀어 환기구를 막았다. 서가에 손가락이 끼었다. 철망 너머에서 두드림이 다시 시작됐다. 이쪽 박자로.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-24, mind:-15 }, wake:1 },
    { l:'② 두드리지 않고 두드림 사이 숨소리로 몇 명인지 센다.', k:'sense', dc:20,
      ok:`귀를 철망에 댔다. 두드림 사이 숨소리를 셌다. 둘. 하나는 빠르고 하나는 느리다. 느린 쪽이 다쳤다.<br><br>빠른 쪽이 두드리고 느린 쪽이 가끔 따라 한다. 같이 길을 찾는다.<br>철망 나사를 손톱으로 반쯤 풀어 두었다. 철망 앞에 이쪽 몫 물을 반 남겨 놓았다. 다음 정각 전에 두 사람이 이 철망으로 나올 것이다.`,
      ng:`세는데 숨소리가 셋이다. 셋째 숨은 덕트가 아니라 이쪽 뒤 서가 사이에서 난다.<br><br>돌아봤다. 서가가 이쪽으로 밀려 붙는다. 사이에 낀 팔을 겨우 뺐다. 팔뚝이 쓸려 벗겨졌다.<br>철망 너머 두드림은 그사이 그쳤다.`,
      win:{ exp:18, dream:2, spirit:6 }, lose:{ hp:-24, spirit:-14 } }
  ] },

{ at:'B2', t:'원무과 — 번호표와 전광판',
  x:`원무과 대기석에 사람들이 번호표를 쥐고 앉아 있다. 전광판이 번호를 부른다. 띵동.<br><br>
    불린 번호는 창구로 간다. 창구 뒤 문으로 들어간다. 나오는 사람은 없다.<br>
    전광판 숫자가 가끔 덜 켜진다. 획 하나가 빠진다. 고장이 아니다. 빠지는 획이 매번 다르다.<br><br>
    이쪽 손에도 번호표가 있다. 언제 쥐었는지 모른다.`,
  o:[
    { l:'① 전광판에서 빠지는 획을 모아 읽는다.', k:'gaze', dc:21,
      ok:`빠지는 획을 셌다. 위 가로획, 왼쪽 세로획, 아래 가로획. 숫자가 아니라 글자 조각이다.<br><br>모으니 글자가 된다. 『비상 · 왼쪽 · 셔터 밑』. 누가 전광판 뒤에서 획을 하나씩 끄고 있다. 진짜 직원이었던 누군가.<br>왼쪽 복도 끝 셔터 밑이 한 뼘 들려 있다. 기어 나갔다. 전광판이 이쪽 번호를 부른 건 셔터를 지난 뒤였다.`,
      ng:`획을 세는 사이 전광판이 이쪽 번호를 부른다. 띵동.<br><br>몸이 저절로 일어선다. 대기석 사람들이 다 이쪽을 본다. 부럽다는 얼굴이다.<br>팀원들이 어깨를 눌러 앉혔다. 앉는 동안 무릎이 창구 쪽으로 계속 펴지려 했다. 번호표를 찢었다. 손이 한참 떨렸다.`,
      win:{ exp:20, dream:3 }, lose:{ mind:-17, spirit:-15 } },
    { l:'② 옆 사람에게 손짓해 번호표를 몰래 바꾼다.', k:'bond', dc:22,
      doom:{ title:'호명', what:'번호가 불려 창구로 끌려갑니다', dc:18, sec:50,
        text:`옆 사람에게 손짓했다. 번호표를 아래로 내밀고 엄지로 두 번. 바꾸자는 뜻이다.<br><br>옆 사람이 바꿔 준다. 그 사람 번호는 아직 멀다고 했다. 그 사람이 웃는다. 고맙다는 웃음이 아니다.<br>띵동. 전광판이 부른다. 이쪽이 받은 번호다. 먼 번호가 아니었다. 바로 다음 차례였다.<br><br>몸이 일어선다. 창구 쪽으로 걷는다. 손짓을 하려는데 손이 번호표를 꼭 쥔다.`,
        dieText:`창구 직원이 번호표를 받아 도장을 찍었다. 쾅.<br><br>창구 뒤 문이 열렸다 닫혔다. 대기석 사람들이 다음 번호를 기다린다.<br>번호표를 바꿔 준 사람은 이쪽이 준 번호표를 오래 내려다봤다. 이제 아무도 안 부를 번호다.` },
      ok:`옆 사람에게 손짓했다. 번호표를 아래로 내밀고 엄지로 두 번. 바꾸자는 뜻이다.<br><br>그 사람이 고개를 젓는다. 그리고 손짓으로 대답한다. 손가락 넷을 펴고 하나를 접는다. 턱으로 대기석 맨 끝을 가리킨다. 거기 앉은 사람 번호표에는 숫자가 없다.<br>그 사람에게 가서 바꿨다. 빈 번호표는 불리지 않는다. 대기석 사람들끼리 쓰는 손짓이 따로 있었다. 오래 기다린 사람들 말이다.`,
      win:{ exp:24, dream:3 } }
  ] },

{ at:'B3', t:'차창 밖 — 선로 옆 신호기',
  x:`차창 밖으로 신호기가 지나간다. 붉은 등. 열차는 서지 않는다.<br><br>
    선로 신호는 안다. 붉으면 서라. 노라면 천천히. 그런데 이 신호기들은 등이 둘씩 달렸다. 위가 붉고 아래가 깜빡인다.<br>
    아래 등이 깜빡이는 횟수가 신호기마다 다르다. 하나씩 준다.<br><br>
    다음 신호기까지 숨 서른.`,
  o:[
    { l:'① 깜빡임이 줄어드는 박자를 읽는다.', k:'gaze', dc:21,
      ok:`신호기 셋을 지나며 셌다. 일곱 번. 여섯 번. 다섯 번.<br><br>남은 역 수다. 시간표 여섯 줄 중에 몇 줄이 남았는지 선로가 세어 준다. 방송보다 정직하다. 방송은 다음 역만 부른다.<br>다섯이 남았다. 앞 칸으로 가는 빠르기를 정했다. 한 칸에 신호기 하나. 늦으면 안 된다. 빨라도 안 된다. 빠르면 지키는 것들 앞에 일찍 닿는다.`,
      ng:`세는데 깜빡임이 이쪽 눈 깜빡임과 맞는다.<br><br>어느 쪽이 먼저인지 모르겠다. 신호기가 이쪽을 보고 깜빡이는 것 같다. 창에서 눈을 뗐다. 창에 비친 이쪽 얼굴이 아직 창밖을 보고 있다. 한 박자 늦게 고개를 돌린다.<br>그 한 박자가 오래 눈에 남았다.`,
      win:{ exp:18, dream:2, mind:6 }, lose:{ mind:-16, spirit:-15 } },
    { l:'② 창을 열고 등불로 원을 그려 지나가는 신호소에 알린다.', k:'bond', dc:21,
      ok:`창을 열고 등불을 흔들었다. 선로 쪽으로. 원을 그렸다. 선로 사람들이 쓰는 서라는 손짓이다.<br><br>신호소 하나가 지나간다. 창에 불이 켜져 있다. 안에서 누가 등불을 든다. 원 하나. 대답이다.<br>열차는 안 섰다. 그런데 다음 신호기 아래 등이 깜빡이지 않는다. 계속 켜져 있다. 앞쪽 어딘가에서 누가 이 열차를 기다린다는 뜻이다.`,
      ng:`흔드는데 바람이 등불을 꺼 버렸다. 창으로 빗물이 들이친다.<br><br>창을 닫으려는데 창틀이 안 내려온다. 밖에서 무언가 창틀을 잡고 있다. 객차 옆구리에 매달린 무언가.<br>창틀을 내리쳐 닫았다. 손가락 하나가 끼었다. 창밖에서 무언가 떨어져 선로로 굴러갔다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-24, mind:-14 } }
  ] },

{ at:'B3', t:'우편칸 앞 — 수화기와 벽',
  x:`우편칸 문이 잠겼다. 팀이 둘로 갈렸다. 셋은 문 앞, 둘은 지붕을 타고 먼저 앞 칸에 들어갔다.<br><br>
    벽 옆 비상 통화기가 울린다. 수화기에서 팀원 목소리가 난다. 문을 열었다고. 빨리 오라고.<br>
    그런데 벽 너머에서 두드리는 소리도 난다. 출발 전에 정한 박자다. 짧게 둘, 길게 하나. 기다려.<br><br>
    목소리는 오라고 한다. 두드림은 기다리라고 한다.`,
  o:[
    { l:'① 수화기를 내려놓고 벽을 두드려 박자로 되묻는다.', k:'bond', dc:21,
      ok:`수화기를 내려놓았다. 벽에 주먹을 댔다. 물었다. 짧게 하나, 길게 하나. 몇 명이냐.<br><br>벽 너머에서 대답이 온다. 짧게 둘. 둘이다. 그리고 한 박자 더. 길게 셋. 정한 적 없는 박자다. 그런데 뜻을 알겠다. 셋째가 있다. 우리 편 아닌 것이 둘 옆에.<br>수화기 목소리는 둘 중 누구 것도 아니었다. 셋째가 쓴 목소리였다. 다른 문으로 돌아 들어가 둘을 데려 나왔다. 수화기는 혼자 계속 오라고 했다.<br><br>정하지 않은 박자를 받아서 바로 읽었다. 신호가 규칙을 넘어 뜻으로 건너왔다. 귀가 그 건너온 자리를 오래 기억한다.`,
      ng:`두드렸는데 대답이 두 군데서 온다. 벽 너머와 수화기 속.<br><br>수화기 속에서도 같은 박자로 두드린다. 짧게 둘, 길게 하나. 어느 쪽이 진짜 벽인지 헷갈린다.<br>벽 쪽을 믿고 기다렸다. 너무 오래. 앞 칸 둘이 문을 열고 왔을 때 둘 다 다쳐 있었다. 혼자 싸웠다고 한다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-22, spirit:-16 }, wake:1 },
    { l:'② 수화기에 대고 출발 전에 정한 박자를 말로 해 보라고 한다.', k:'gaze', dc:21,
      ok:`수화기에 물었다. 출발 전에 정한 박자를 말로 해 보라고.<br><br>저쪽이 말한다. 짧게 둘, 길게 하나. 맞다. 그런데 너무 빠르다. 생각도 안 하고. 벽 너머 두드림을 듣고 따라 말한 것이다. 같은 칸에 있으니까.<br>그건 저쪽이 팀원 옆에 있다는 뜻이다. 수화기를 내려놓았다. 벽에 두드렸다. 버텨. 다른 길을 찾았다. 둘은 버텼다.`,
      ng:`물었는데 저쪽이 팀원 목소리로 웃는다. 그런 거 정한 적 없다고.<br><br>이쪽이 헷갈린다. 정했던가. 머릿속 박자가 흐려진다. 수화기 쥔 손이 떨린다.<br>벽 너머 두드림이 그쳤다. 앞 칸 둘을 다시 만났을 때 하나가 팔을 다쳐 있었다. 이쪽이 망설인 시간만큼.`,
      win:{ exp:20, dream:3 }, lose:{ mind:-17, spirit:-16 } }
  ] },

{ at:'B3', t:'객차 창 — 한 박자 늦은 대답',
  x:`객차 창에 안이 비친다. 바깥이 깜깜해서 거울 같다. 비친 얼굴은 한 박자 늦게 움직인다.<br><br>
    일행 다섯이 통로에 섰다. 그중 하나가 얼굴을 바꾼 손님이라는 말을 들었다. 누군지 모른다.<br>
    손짓을 보내면 다섯이 다 따라 한다.<br><br>
    창이 그걸 비출 것이다. 한 박자 늦게.`,
  o:[
    { l:'① 손짓을 보내고 창에 비친 대답이 늦는 박자를 잰다.', k:'gaze', dc:21,
      ok:`창을 보며 손짓을 보냈다. 나를 봐. 다섯이 따라 한다.<br><br>창에 비친 손짓들이 한 박자 늦게 따라온다. 넷은 한 박자다. 하나는 두 박자다. 그 하나는 이쪽 손짓을 보고 따라 한 게 아니다. 옆 사람 손짓을 보고 따라 했다. 한 번 더 늦게.<br>그 하나를 봤다. 그쪽도 이쪽을 봤다. 엄지로 검지를 두 번 긁었다. 넷이 천천히 그 하나에게서 떨어졌다.<br><br>신호를 보내기만 하지 않고 돌아오는 시간을 잰다. 늦는 대답이 누구인지 말해 준다. 손짓 하나가 시계가 됐다.`,
      ng:`보냈는데 창에 비친 손짓이 이쪽보다 먼저 움직인다. 다섯 다.<br><br>창이 거꾸로 됐다. 비친 쪽이 먼저고 이쪽이 늦다. 이쪽이 따라 하고 있는 건가. 손을 내려다봤다. 손이 저절로 나를 봐를 하고 있다.<br>팀원이 손목을 잡아 내렸다. 손가락이 한참 굳어 펴지지 않았다.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-17, spirit:-16 }, wake:1 },
    { l:'② 다섯이 눈을 감고 손을 맞잡아 쥐는 박자를 돌린다.', k:'bond', dc:21,
      ok:`눈을 감으라고 했다. 다섯이 원으로 손을 잡았다. 꽉 한 번 쥐면 옆으로 넘겨.<br><br>쥐었다. 손에서 손으로. 원을 한 바퀴 돌아 이쪽 손에 돌아왔다. 그런데 한 번이 아니라 두 번이다. 원 어딘가에서 하나를 더 쥐었다.<br>한 번 더 보냈다. 이번엔 어디서 늘어나는지 손으로 셌다. 넷째와 다섯째 사이. 눈을 뜨고 그 둘 사이를 봤다. 다섯째 손이 차가웠다.`,
      ng:`손을 잡았는데 손이 여섯 개다. 원은 다섯인데.<br><br>눈을 뜨지 말라고 한 건 이쪽이다. 아무도 눈을 안 뜬다. 여섯째 손이 이쪽 손을 아주 꽉 쥔다.<br>눈을 떴다. 손이 다섯이다. 손등에 여섯째 손가락 자국이 남았다. 손등뼈가 욱신거렸다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-22, mind:-15 } }
  ] },

{ at:'B3', t:'기관실 — 기적 줄',
  x:`기관실 천장에 기적 줄이 달려 있다. 당기면 운다. 이 열차에서 제일 큰 소리다.<br><br>
    팀은 탄수차와 기관실 사이에 흩어졌다. 석탄 소리, 바퀴 소리, 김 소리. 아무 말도 안 들린다.<br>
    04:39에 내릴 문이 열린다. 다섯이 같이 뛰어야 한다. 하나가 늦으면 하나가 남는다.<br><br>
    손이 기적 줄에 닿았다. 보일러 압력계 바늘이 붉은 칸에 들어가 있다.`,
  o:[
    { l:'① 기적 줄을 당겨 정한 박자로 뛸 때를 알린다.', k:'bond', dc:22,
      doom:{ title:'터지는 김', what:'증기에 휩싸였습니다', dc:18, sec:45,
        text:`줄을 당겼다. 길게 하나, 짧게 둘. 뛸 준비. 기적이 운다. 열차 전체가 운다.<br><br>압력계 바늘이 더 붉어진다. 기적은 김을 쓴다. 보일러 이음매에서 김이 새기 시작한다. 이쪽 쪽으로.<br>마지막 짧은 하나를 당기는 순간 이음매가 터졌다. 하얀 것이 이쪽을 덮었다. 뜨겁다는 걸 알기도 전에 앞이 안 보인다.<br><br>밖에서 팀원들이 박자를 듣고 문 쪽으로 모이는 소리가 났다. 신호는 갔다.`,
        dieText:`넷은 기적 박자에 맞춰 뛰어내렸다. 빗속 자갈 위로. 한 사람도 안 늦었다.<br><br>열차가 멀어진다. 기적이 한 번 더 운다. 길게 하나. 아무도 안 당겼는데.<br>넷은 그걸 끝까지 들었다. 정한 박자에 없는 신호였다. 그래도 뜻은 알았다.` },
      ok:`줄을 당겼다. 길게 하나, 짧게 둘. 뛸 준비. 기적이 운다. 열차 전체가 운다.<br><br>압력계 바늘이 더 붉어진다. 줄을 놓고 압력 밸브를 반 바퀴 풀었다. 김이 천장으로 빠진다. 바늘이 한 칸 내려온다. 그리고 다시 당겼다. 짧게 하나. 지금.<br>다섯이 같은 박자에 문으로 왔다. 같은 박자에 뛰었다. 빗속 자갈 위에 다섯이 다 굴렀다. 열차가 기적을 한 번 더 울리며 멀어졌다. 이쪽이 당긴 게 아니다.`,
      win:{ exp:25, dream:4 } },
    { l:'② 기적은 두고 한 사람씩 찾아가 어깨를 두 번 두드린다.', k:'fix', dc:21,
      ok:`기적은 안 당겼다. 석탄 더미를 넘어 한 사람씩 찾아갔다. 어깨를 두 번. 정한 박자다. 문 앞으로.<br><br>다섯 어깨를 다 두드리는 데 오래 걸렸다. 04:38. 넷이 문 앞에 모였다. 이쪽이 마지막으로 닿았다.<br>문이 열렸다. 다섯이 뛰었다. 소리 없는 신호가 제일 큰 소리보다 확실했다.`,
      ng:`셋째 어깨를 두드리는데 그 사람이 놀라 돌아서며 삽을 휘둘렀다. 화부였다. 팀원이 아니었다.<br><br>삽날이 어깨를 스쳤다. 석탄 가루 속에서 팀원을 다시 찾았다. 넷째와 다섯째를 찾았을 때 문은 이미 열려 있었다.<br>뛰어내렸다. 넷째가 늦었다. 그 손을 잡아끌다 같이 자갈 위를 한참 굴렀다.`,
      win:{ exp:18, dream:3 }, lose:{ hp:-28, mind:-13 } }
  ] }

]);

// ──────────────────────────────────────────
// 표사 (escort) · 내공
// ──────────────────────────────────────────
kJob('escort', 'B', [

{ at:'B', t:'처마 밑 — 맡긴 꾸러미',
  x:`우산 쓴 사람이 처마 밑에서 꾸러미를 내민다. 기름종이로 쌌다. 끈으로 열십자를 묶었다.<br><br>
    다음 문 너머까지만 들어 달라고 한다. 값은 치르겠다고. 열어 보지는 말라고.<br>
    표사는 맡은 짐은 끝까지 가져간다. 그 대신 맡기 전에 짐을 본다. 그게 순서다.<br><br>
    꾸러미가 아주 조금 따뜻하다.`,
  o:[
    { l:'① 받기 전에 무게와 소리를 잰다.', k:'gaze', dc:20,
      ok:`꾸러미를 손바닥에 올려 흔들어 봤다. 안에서 굴러가는 게 없다. 무게가 한쪽으로 쏠렸다. 따뜻한 쪽이다.<br><br>귀를 대니 아주 작게 똑딱인다. 시계보다 빠르다. 짐이 아니라 짐을 든 사람이 어디 있는지 알리는 소리다.<br>안 받았다. 우산 쓴 사람이 꾸러미를 도로 품에 넣는다. 다른 사람을 기다리는 얼굴이다. 처마를 떠나며 봤다. 그 사람 신발이 말라 있었다.`,
      ng:`흔드는 순간 꾸러미 안에서 똑딱 소리가 멈춘다.<br><br>우산 쓴 사람이 웃는다. 흔드는 사람이 받는 사람보다 더 확실히 들킨다고. 골목 끝에서 손전등이 켜진다.<br>꾸러미를 처마 밑에 놓고 뛰었다. 젖은 계단에서 미끄러져 무릎을 깼다. 뒤에서 꾸러미가 다시 똑딱이기 시작했다.`,
      win:{ exp:16, dream:2, mind:6 }, lose:{ hp:-22, mind:-15 } },
    { l:'② 받아서 열지 않고 약속한 데까지 들고 간다.', k:'bond', dc:21,
      ok:`받았다. 열지 않았다. 품에 넣지 않고 손에 들었다. 짐은 몸에서 한 뼘 떨어져 있어야 한다. 무슨 일이 생기면 짐보다 사람이 먼저 비켜야 하니까.<br><br>가는 동안 꾸러미가 두 번 따뜻해졌다. 두 번 다 근처에 무언가 있었다. 꾸러미가 그걸 부르고 있었다. 짐이 무엇인지 몰라도 짐이 하는 짓은 알 수 있다. 따뜻해지는 쪽을 피해 걸었다.<br>문 너머에 꾸러미를 내려놓았다. 약속한 데까지. 거기서 손을 뗐다. 받은 것은 다 했다.<br><br>열지 않고도 짐을 읽는 법. 짐이 데워지는 쪽을 피하는 걸음. 손이 짐을 드는 높이가 하나 바뀌었다.`,
      ng:`들고 가는데 꾸러미가 점점 뜨거워진다.<br><br>문 앞에서 손바닥이 데었다. 놓지 않았다. 맡은 짐이다. 문을 열자 저쪽에 손전등들이 기다리고 있었다. 꾸러미가 부른 것이다.<br>꾸러미를 손전등 쪽으로 던지고 뛰었다. 맡은 짐을 처음으로 버렸다. 손바닥보다 그게 더 쓰렸다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-24, spirit:-15 }, wake:1 },
    { l:'③ 내공을 손끝에 모아 포장 너머를 짚는다.', k:'sense', dc:20, cost:{ qi:22 },
      ok:`꾸러미 끈 위에 손가락을 얹고 내공을 손끝으로 내렸다. 기름종이 너머를 짚었다.<br><br>쇠. 작고 둥근 쇠. 그 안에서 무언가 뛴다. 맥처럼. 사람 것이 아니다. 누가 짐 속에 심장 하나를 넣어 두었다.<br>내려놓았다. 우산 쓴 사람이 실망한 얼굴로 꾸러미를 거둔다. 짐을 짚을 줄 아는 손에는 이 짐을 못 맡긴다. 그걸 아는 얼굴이다.`,
      ng:`내공이 손끝에서 기름종이에 먹힌다. 아무것도 안 짚인다.<br><br>대신 꾸러미 안의 것이 이쪽 손끝을 짚는다. 차가운 것이 손가락을 타고 올라온다.<br>손을 뗐다. 손가락 셋이 하얗게 굳었다. 녹는 데 한참 걸렸다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-22, mind:-14 } }
  ] },

{ at:'B', t:'처마 골목 — 빗소리가 둔한 처마',
  x:`처마가 길게 이어진 골목이다. 빗물이 처마마다 같은 소리로 떨어진다. 통, 통, 통.<br><br>
    셋째 처마에서만 소리가 둔하다. 처마 끝 물줄기가 무언가에 막혀 옆으로 튄다.<br>
    산길 매복을 수십 번 지나왔다. 매복 자리는 늘 소리가 조금 다르다. 사람이 소리를 먹는다.<br><br>
    셋째 처마 밑 그늘이 사람 둘만큼 짙다.`,
  o:[
    { l:'① 내공을 실어 낮고 길게 표호를 깐다.', k:'bond', dc:21, cost:{ qi:24 },
      doom:{ title:'처마 밑 매복', what:'처마 밑 어둠으로 끌려갑니다', dc:17, sec:55,
        text:`단전에서 끌어올려 낮게 외쳤다. 지나간다. 짐에 손대지 마라.<br><br>산에서는 그걸 들은 쪽이 물러났다. 여기서는 셋째 처마 그늘이 움직인다. 물러나지 않는다. 나온다.<br>둘이 아니다. 셋째 처마부터 다섯째까지 그늘이 다 일어선다. 표호가 이쪽 자리를 알려 줬다. 맨 앞에서 외친 사람 자리.<br><br>옷깃과 팔이 한꺼번에 잡혔다. 처마 밑으로 끌려 들어간다. 빗소리가 둔해진다.`,
        dieText:`팀원들은 표호가 끝나기 전에 골목 반대쪽으로 빠져나갔다. 그렇게 하라고 외친 소리였다.<br><br>셋째 처마 빗소리가 다시 통, 통, 통 하고 난다. 다른 처마와 같다.<br>골목 바닥이 깨끗하다. 지킨 것은 다 빠져나갔다.` },
      ok:`단전에서 끌어올려 낮게 외쳤다. 지나간다. 짐에 손대지 마라.<br><br>셋째 처마 그늘이 멈칫한다. 표호는 숫자를 알려 주지 않는다. 지키는 사람이 몇인지 모르면 매복은 셈이 안 선다.<br>그늘이 처마 끝을 따라 골목 끝으로 물러난다. 둘. 팀원들을 가운데 두고 지나갔다. 셋째 처마 빗소리가 다시 통, 통 하고 맑아졌다.`,
      win:{ exp:24, dream:3 } },
    { l:'② 둔한 처마를 피해 맞은편 담장 그늘로 돌아간다.', k:'sense', dc:20,
      ok:`셋째 처마 앞에서 길을 꺾었다. 맞은편 담장 그늘로. 빗소리가 맑은 처마 밑만 골라 걸었다.<br><br>셋째 처마 그늘은 안 움직인다. 이쪽을 못 봤거나 쫓을 셈이 안 섰다.<br>골목 끝에서 돌아봤다. 셋째 처마 물줄기가 한 번 크게 튄다. 누가 고개를 내밀었다가 넣었다. 이길 싸움보다 안 할 싸움을 먼저 고른다. 산에서나 여기서나.`,
      ng:`담장 그늘로 꺾었는데 담장 처마도 소리가 둔하다. 거기도 있다.<br><br>양쪽 그늘이 동시에 일어선다. 팀원들 등을 밀어 골목 끝으로 뛰게 했다. 이쪽이 맨 뒤였다.<br>무언가 어깨를 쳤다. 쇠파이프 같은 것. 어깨뼈가 울렸다. 넘어지지 않고 뛰었다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-26, mind:-12 } },
    { l:'③ 짐을 팀원에게 맡기고 빈손으로 혼자 먼저 지나가 본다.', k:'hide', dc:21,
      ok:`짐을 팀원에게 맡기고 혼자 지나갔다. 짐 없는 사람처럼. 고개를 숙이고.<br><br>셋째 처마 앞을 지날 때 그늘이 이쪽 손을 본다. 빈손이다. 그늘이 안 움직인다. 노리는 건 사람이 아니라 짐이다.<br>골목 끝에서 손짓했다. 팀원들이 짐을 담장 너머로 넘기고 반대편 길로 돌아왔다. 짐은 골목을 안 지났다.`,
      ng:`빈손으로 지나가는데 그늘이 손이 아니라 얼굴을 본다.<br><br>노리는 건 짐이 아니라 짐을 지키는 사람이었다. 그늘에서 손이 나와 외투를 잡는다. 외투를 벗어 던지고 빠져나왔다.<br>빗속을 외투 없이 걸었다. 몸이 떨렸다. 떨림이 오래 안 멈췄다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-20, spirit:-15 } }
  ] },

{ at:'B', t:'쫓기는 계단 — 짐이 된 팀원',
  x:`팀원 하나가 다리를 다쳤다. 뒤에서 발소리가 쫓아온다. 계단이 아래로 길다.<br><br>
    업으면 이쪽이 늦다. 안 업으면 그 사람이 늦다. 늦은 쪽은 잡힌다.<br>
    짐 진 사람은 짐 무게로 뛰지 않는다. 다리로 뛴다. 무게는 허리가 진다. 산길에서는 그렇게 배웠다.<br><br>
    여기는 산길보다 계단이 가파르다.`,
  o:[
    { l:'① 내공을 허리에 모아 업고 무릎을 낮춰 뛴다.', k:'steady', dc:21, cost:{ qi:25 },
      ok:`업었다. 다친 사람 무게가 등에서 허리로 내려오게 몸을 숙였다. 내공을 허리에 모았다.<br><br>무릎을 낮추고 계단을 뛰었다. 머리가 출렁이지 않는다. 등의 사람도 안 출렁인다. 무게가 몸 가운데 박혔다. 발소리가 점점 멀어진다. 업은 사람이 안 업은 사람보다 빨랐다.<br>바닥 층에서 내려놓았다. 다친 사람이 말한다. 업힌 것 같지 않았다고. 실려 온 것 같았다고.<br><br>등이 아니라 허리로 지고, 다리가 아니라 무릎으로 뛰는 법. 계단이 가르쳤다. 몸이 그 낮은 자세를 벌써 제자리로 안다.`,
      ng:`업고 뛰는데 계단참에서 발이 미끄러졌다. 둘이 같이 굴렀다.<br><br>다친 사람 머리를 손으로 감쌌다. 손등이 계단 모서리에 다 찍혔다. 발소리가 한 층 위까지 왔다.<br>다시 업었다. 내공이 반쯤 흩어졌다. 무릎이 떨리는 채로 마저 내려갔다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-28, mind:-12 }, wake:1 },
    { l:'② 외투 둘과 막대로 들것을 만들어 둘이 든다.', k:'fix', dc:20,
      ok:`외투 두 벌 소매에 막대 둘을 꿰었다. 들것이 됐다. 다친 사람을 눕혔다.<br><br>둘이 앞뒤로 들었다. 계단에서는 뒤가 높고 앞이 낮다. 뒤에 이쪽이 섰다. 무게가 앞으로 쏠리지 않게.<br>발소리보다 먼저 바닥 층에 닿았다. 들것은 업는 것보다 사람을 덜 흔든다. 다친 사람은 눈을 감고 있었다. 잠든 것이다.`,
      ng:`들것을 만드는 데 숨 서른이 걸렸다. 발소리가 계단참에 닿았다.<br><br>반쯤 들고 뛰다 앞사람이 넘어졌다. 다친 사람이 들것에서 굴러 계단에 부딪혔다. 비명이 났다.<br>결국 업고 뛰었다. 들것은 계단에 버렸다. 쫓는 쪽이 그걸 밟고 미끄러지는 소리가 났다. 그것만 다행이었다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-24, mind:-14 } }
  ] },

{ at:'B', t:'벽시계 — 버릴 짐',
  x:`벽시계가 다섯 시 일 분을 가리킨다. 나가는 문이 닫히기까지 아홉 분.<br><br>
    짐이 무겁다. 다 지고 가면 열한 분이 걸린다. 두 분이 모자란다.<br>
    팀원들 짐 중에 아무도 안 놓는 게 하나 있다. 장부다. 이걸 가지러 들어왔다. 무겁다.<br><br>
    무언가 버려야 한다. 장부를 버리면 들어온 이유가 없어진다.`,
  o:[
    { l:'① 사람이 쓸 것만 추려 다시 꾸리고 장부를 펴 본다.', k:'gaze', dc:21,
      ok:`짐을 다 풀었다. 물, 고기, 약초. 사람이 쓸 것. 장부만 덩그러니 남았다.<br><br>팀원들이 장부를 본다. 아무도 말을 안 한다. 장부를 펴서 맨 마지막 장을 봤다. 이름 다섯. 이쪽 팀 이름이다.<br>그 한 장만 찢어 접어 품에 넣었다. 장부는 두고 갔다. 들어온 이유는 그 한 장이었다. 일곱 분 만에 문을 지났다.`,
      ng:`추리는데 팀원 하나가 장부를 끌어안는다. 이걸 두고 가면 다 헛것이라고.<br><br>실랑이하다 두 분이 갔다. 장부째 들고 뛰었다. 문이 닫히기 시작했다. 마지막 사람 등을 밀어 넣으며 문틀에 어깨를 박았다.<br>장부는 가져왔다. 펴 보니 빈 장이 대부분이었다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-24, mind:-14 } },
    { l:'② 내공을 허리에 모아 장부까지 다 지고 앞장선다.', k:'steady', dc:21, cost:{ qi:26 },
      ok:`안 버렸다. 팀원들 짐을 받아 이쪽이 졌다. 장부는 등 맨 위에. 내공을 허리로 모았다.<br><br>무겁다. 뒤가 가벼워지니 다들 빨라진다. 이쪽은 맨 앞에서 무게로 길을 열었다. 아홉 분 끝에 문을 지났다. 숨 하나 남기고.<br>짐을 내려놓자 무릎이 꺾였다. 장부가 맨 위에서 미끄러져 떨어졌다. 젖지 않았다. 등으로 비를 막았다.`,
      ng:`반쯤 가서 무릎이 바닥에 박혔다. 내공이 무게를 다 못 받는다.<br><br>결국 짐을 버렸다. 어디에 버렸는지도 모른다. 장부만 쥐고 뛰었다.<br>문틈으로 겨우 빠져나왔다. 허리가 한참 펴지지 않았다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-28, mind:-12 } }
  ] },

{ at:'B', t:'처마 밑 — 데려다 달라는 사람',
  x:`처마 밑에 사람이 웅크려 있다. 외투 깃이 찢겼다. 이쪽을 보고 손을 든다.<br><br>
    아까 무엇을 봤다고 한다. 고무장갑 낀 사람이 무언가 닦는 걸. 그래서 쫓긴다고. 출구까지만 데려다 달라고.<br>
    표사는 사람도 짐으로 받는다. 제일 귀한 짐이다. 제일 위험한 짐이기도 하다. 쫓기는 짐은 쫓는 것을 같이 데려온다.<br><br>
    그 사람 손목에 시계가 있다. 아직 간다.`,
  o:[
    { l:'① 받는다 — 일행 가운데에 세운다.', k:'bond', dc:21,
      doom:{ title:'쫓기는 짐', what:'쫓는 쪽에게 함께 끌려갑니다', dc:17, sec:55,
        text:`받았다. 일행 가운데에 세웠다. 넷이 둘러쌌다. 이쪽이 맨 뒤.<br><br>두 골목을 지났다. 셋째 골목에서 그 사람이 걸음을 늦춘다. 손목시계를 본다. 그리고 손을 든다. 처마 밑에서 이쪽에게 했던 것과 같은 손짓으로.<br>골목 양쪽에서 고무장화 소리가 난다. 그 사람은 쫓기는 사람이 아니었다. 길잡이였다. 짐인 척하는 끈이었다.<br><br>맨 뒤 이쪽 어깨가 잡혔다. 그 사람은 일행 가운데에 그대로 서 있다. 웃지 않는다.`,
        dieText:`넷은 골목을 뚫고 빠져나갔다. 그 사람은 어느새 없었다.<br><br>세 골목 뒤에서 대걸레가 바닥을 훑는 소리가 났다.<br>받은 짐은 끝까지 가져간다. 이번 짐은 짐 진 사람을 끝까지 데려갔다.` },
      ok:`받았다. 일행 가운데에 세웠다. 넷이 둘러쌌다. 이쪽이 맨 뒤.<br><br>셋째 골목에서 그 사람이 걸음을 늦추며 손목시계를 본다. 그 손목을 잡았다. 시계를 풀어 하수구에 떨어뜨렸다. 그 사람 얼굴이 하얘진다. 그리고 운다.<br>시계를 차고 사람을 데려오면 동생을 놓아준다고 했단다. 짐 속에 짐이 하나 더 있었다. 출구까지 데려갔다. 동생 이름을 들었다. 들은 이름도 짐이다. 가져가기로 했다.`,
      win:{ exp:25, dream:4 } },
    { l:'② 받기 전에 손목시계와 신발을 본다.', k:'gaze', dc:20,
      ok:`손목시계를 봤다. 바늘이 안 간다. 초침만 같은 자리에서 앞뒤로 떤다. 시간이 아니라 무엇을 재는 바늘이다.<br><br>신발을 봤다. 한쪽만 젖었다. 처마 밑에 오래 웅크린 사람은 양쪽이 다 젖는다. 이 사람은 방금 왔다. 한쪽 발만 빗속에 디디고.<br>받지 않았다. 반대쪽 길을 알려 줬다. 그 사람은 고맙다고 하고 그 길로 가지 않았다. 이쪽이 가는 쪽으로 천천히 따라왔다. 길을 세 번 바꿔 따돌렸다.`,
      ng:`보는 걸 그 사람이 알아챈다. 시계 찬 손을 소매 안으로 넣는다.<br><br>얼굴이 굳는다. 못 믿겠으면 관두라고 한다. 그리고 크게 운다. 일부러 들리게.<br>울음소리에 골목 끝 손전등이 켜졌다. 처마를 버리고 뛰었다. 젖은 철계단에서 발목이 꺾였다.`,
      win:{ exp:18, dream:2, mind:6 }, lose:{ hp:-24, mind:-14 } }
  ] },

{ at:'B', t:'숨어 든 빈방 — 밤 경계',
  x:`빈방을 하나 찾았다. 문을 잠갔다. 넷이 잠들었다. 이쪽은 안 잔다.<br><br>
    창으로 빗물이 흘러내린다. 네온이 빗물에 녹아 방 안 벽까지 번진다. 붉게, 꺼졌다가, 붉게.<br>
    밤에 짐이 제일 많이 없어진다. 산길에서도 그랬다. 여기서 지킬 짐은 잠든 넷이다.<br><br>
    새벽 무렵 열쇠 구멍에서 쇠 긁히는 소리가 난다. 아주 작게.`,
  o:[
    { l:'① 문 앞에 등을 대고 앉아 버틴다.', k:'steady', dc:21,
      ok:`문에 등을 대고 앉았다. 움직이지 않았다.<br><br>열쇠 구멍 소리가 멈춘다. 손잡이가 돈다. 문이 안 밀린다. 사람 하나가 등을 대고 있다는 걸 밖에서도 안다. 한참 서 있다가 간다.<br>아침에 문을 열었다. 문 앞 바닥에 열쇠 하나가 놓여 있다. 이 방 열쇠다. 누가 이 방 열쇠를 가지고 있었다. 팀원들 짐을 하나씩 다시 셌다. 다 있었다.`,
      ng:`등을 대고 있는데 졸음이 왔다. 고개가 한 번 떨어졌다.<br><br>그 사이 문이 한 뼘 열렸다. 등이 밀려 앞으로 쓰러졌다. 문틈으로 손이 들어와 제일 가까운 짐을 끌어간다.<br>문을 다시 밀어 닫았다. 손가락을 문에 찧었다. 물주머니가 든 짐이 없어졌다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-22, mind:-15 } },
    { l:'② 내공을 귀에 모아 열쇠 구멍 너머를 듣는다.', k:'sense', dc:21, cost:{ qi:22 },
      ok:`숨을 고르고 내공을 귀로 모았다. 빗소리를 걷어 냈다.<br><br>열쇠 구멍 너머에 숨이 하나. 열쇠 꾸러미 흔들리는 소리. 하나씩 넣어 본다. 이 방 열쇠를 모른다. 이 방에 사람이 있는 걸 아는 것도 아니다. 방마다 다 넣어 본다.<br>숨을 죽였다. 열쇠가 다 안 맞는다. 다음 방으로 간다. 그 걸음 수를 셌다. 복도 끝까지 열둘. 해 뜨기 전에 반대쪽으로 나갔다.`,
      ng:`내공을 귀로 모았는데 너무 많이 들린다. 빗소리, 네온 우는 소리, 넷의 숨, 이쪽 심장.<br><br>열쇠 구멍 소리가 그 속에 묻혔다. 다시 찾았을 때 손잡이가 이미 돌고 있다. 문으로 몸을 던져 어깨로 받았다.<br>밖의 것이 한참 밀다 갔다. 귀가 웅웅 울려 아침까지 아무것도 안 들렸다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-22, spirit:-15 } },
    { l:'③ 넷을 하나씩 깨워 창밖 사다리로 먼저 내보낸다.', k:'bond', dc:20,
      ok:`넷을 하나씩 깨웠다. 입을 손으로 막으면서. 창을 가리켰다.<br><br>창밖은 비상 사다리다. 넷이 차례로 나갔다. 마지막으로 이쪽이 나가며 창을 닫았다. 닫는 순간 방문이 열렸다.<br>사다리를 내려가며 올려다봤다. 창에 누가 서서 빈방을 본다. 잠든 짐은 깨우면 사람이 된다. 사람은 스스로 걷는다.`,
      ng:`깨우는데 하나가 놀라 소리를 질렀다.<br><br>열쇠 구멍 소리가 멈추고 문이 쾅 하고 운다. 창으로 넷을 밀어냈다. 서두르다 하나가 사다리에서 발을 헛디뎠다.<br>그 하나를 붙잡느라 손목이 사다리 쇠에 비틀렸다. 손목이 부었다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-24, mind:-13 } }
  ] },

{ at:'B', t:'좁은 길목 — 되돌아온 발자국',
  x:`길이 좁아진다. 양쪽이 높은 벽이다. 빗물에 진흙이 고였다.<br><br>
    진흙에 발자국이 있다. 앞으로 간 발자국. 그리고 같은 발이 뒤로 돌아온 발자국. 돌아온 발자국은 벽 틈에서 끝난다.<br>
    이 무늬를 안다. 앞질러 갔다가 되돌아와 숨는 것. 지나가는 짐을 뒤에서 치려고.<br><br>
    벽 틈에 빗물이 안 고인다. 누가 막고 서 있다.`,
  o:[
    { l:'① 지친 팀원을 가운데 두고 벽 틈 쪽에 얼굴을 둔 채 옆걸음으로 지나간다.', k:'bond', dc:21,
      ok:`제일 지친 팀원을 가운데 세웠다. 셋이 둘러쌌다. 이쪽은 벽 틈 쪽에 섰다. 몸을 틈으로 향한 채 옆걸음으로 걸었다.<br><br>틈 앞을 지날 때 안의 것과 눈이 마주쳤다. 손에 쇠파이프가 있다. 등을 노렸는데 얼굴이 와 있다. 쇠파이프가 안 내려온다.<br>틈을 지나서도 옆걸음으로 열 걸음을 더 갔다. 그다음 돌아섰다. 틈에서 아무것도 안 나왔다.<br><br>짐을 둘러싸는 법에 하나를 보탰다. 위험한 쪽에는 등이 아니라 얼굴을 둔다. 옆걸음 하나가 대열을 바꿨다.`,
      ng:`둘러싸고 지나가는데 진흙에 발이 빠졌다. 대열이 흐트러졌다.<br><br>틈에서 쇠파이프가 나와 가운데 팀원 어깨를 쳤다. 그 사이로 몸을 넣었다. 두 번째는 이쪽 팔뚝에 왔다.<br>틈 안의 것을 밀어 넣고 다들 뛰었다. 팔뚝이 붓기 시작했다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-28, mind:-12 }, wake:1 },
    { l:'② 발자국을 따라 담을 넘어 벽 틈 뒤쪽으로 돌아간다.', k:'sense', dc:21,
      ok:`앞으로 간 발자국을 따라갔다. 되돌아온 지점까지. 거기서 담장에 올라 틈 뒤쪽에 내려섰다.<br><br>틈 안의 것이 등을 보이고 서 있다. 길 쪽을 보며. 등을 노리던 쪽이 등을 보이고 있다.<br>소리 없이 담을 넘어 길로 돌아왔다. 팀원들을 손짓으로 불렀다. 틈 안의 것은 끝까지 길 쪽만 봤다.`,
      ng:`따라가는데 발자국이 하나 더 있다. 되돌아오지 않은 발자국. 앞에도 하나 있다.<br><br>앞뒤로 둘이다. 담장 위에 올라서는 순간 앞쪽 것이 이쪽을 본다. 뛰어내렸다. 진흙에 발목이 꺾였다.<br>팀원들과 다른 길로 돌아갔다. 발목이 부어 오래 걸렸다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-24, spirit:-13 } }
  ] },

{ at:'B', t:'쉬는 자리 — 소리 나지 않는 짐',
  x:`쉬는 자리에서 팀원들 짐을 본다. 다 흔들면 소리가 난다. 물주머니 출렁이는 소리, 쇠붙이 부딪치는 소리.<br><br>
    여기서는 소리가 쫓는 것을 부른다. 아까도 그랬다. 계단에서 누구 짐 속 숟가락이 울렸다.<br>
    짐 지는 사람이 제일 먼저 배우는 건 짐 꾸리기다. 산길에서는 무게를 따졌다. 여기서는 소리를 따져야 한다.<br><br>
    시간은 숨 삼백쯤 있다.`,
  o:[
    { l:'① 다섯 짐을 다 풀어 소리가 안 나게 다시 꾸린다.', k:'fix', dc:20,
      ok:`다 풀었다. 물주머니는 공기를 빼고 꽉 묶었다. 출렁일 틈이 없게. 쇠붙이는 천으로 하나씩 감았다. 딱딱한 것은 등 쪽, 무른 것은 바깥쪽.<br><br>하나씩 메게 하고 뛰어 보게 했다. 아무 소리도 안 난다. 사람 숨소리만.<br>다음 계단에서 쫓는 쪽 발소리가 바로 아래층을 지나갔다. 위층 다섯은 숨만 쉬었다. 짐도 같이 숨을 죽였다.<br><br>무게로 꾸리던 손이 소리로 꾸리는 법을 익혔다. 짐을 흔들어 보는 버릇이 하나 더 생겼다.`,
      ng:`다시 꾸리는데 시간이 모자란다. 숨 삼백이 아니었다. 백이었다.<br><br>복도에서 발소리가 다가온다. 반쯤 꾸린 짐을 끌어안고 뛰었다. 품에서 쇠붙이가 쏟아졌다. 큰 소리가 났다.<br>쏟아진 것을 버리고 뛰었다. 칼 하나와 숟가락 둘을 잃었다. 계단에서 무릎을 찧었다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-22, mind:-14 }, wake:1 },
    { l:'② 소리 나는 것만 한 짐에 모아 이쪽이 지고 맨 뒤에 선다.', k:'steady', dc:21,
      ok:`소리 나는 것만 골라 한 짐에 모았다. 물, 쇠, 깡통. 그 짐을 이쪽이 졌다. 넷은 조용한 짐만 졌다.<br><br>걸을 때마다 등에서 소리가 난다. 그래서 맨 뒤에서 멀찍이 걸었다. 쫓는 쪽이 들으면 이쪽만 들린다.<br>소리를 따라온 것은 이쪽만 쫓았다. 넷은 그 사이 멀리 갔다. 이쪽도 결국 따돌렸다. 등이 소리 무게로 무거웠다.`,
      ng:`지고 걷는데 소리가 너무 크다. 깡통이 깡통을 친다.<br><br>쫓는 쪽이 아주 빨리 왔다. 벌려 둔 사이를 다 좁혔다. 짐을 벗어 반대쪽으로 던졌다. 소리가 그쪽으로 굴렀다.<br>빈 등으로 뛰었다. 물과 고기를 다 그 짐에 넣어 두었었다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-24, spirit:-13 } }
  ] },

{ at:'B1', t:'3번 창고 — 검은 우산 도장이 찍힌 송장',
  x:`창고 구석 상자에 송장이 붙어 있다. 받는 사람 칸에 도장이 찍혔다. 검은 우산 모양이다.<br><br>
    품목 칸에 건어물. 수량 칸에 다섯. 상자는 하나다. 사람 하나 누울 만한 크기.<br>
    송장부터 읽는다. 짐보다 송장이 먼저 거짓말을 한다.<br><br>
    상자 봉인은 안 뜯겼다. 다섯 칸 중 첫 칸에만 체크가 되어 있다.`,
  o:[
    { l:'① 송장을 뒷면까지 끝까지 읽는다.', k:'gaze', dc:20,
      ok:`송장을 떼어 뒷면까지 봤다. 작은 글씨가 있다. 적재 순서. 1번 — 3번 창고. 2번 — 냉동 창고. 3번 — 경매장. 4번 — 야적장. 5번 — 선착장.<br><br>상자는 다섯이다. 층마다 하나. 첫 칸 체크는 이 상자다. 이미 찼다. 나머지 넷은 아직 비었다.<br>송장을 품에 넣었다. 층마다 빈 상자가 어디 있는지 안다. 다가가지 않을 데를 안다는 뜻이다. 상자는 손대지 않았다. 남의 봉인이다.`,
      ng:`읽는데 송장이 젖어 글씨가 번진다. 뒷면이 손가락에 묻어 찢어졌다.<br><br>찢는 소리에 상자 안에서 무언가 움직인다. 봉인이 안쪽에서 한 번 부풀었다 꺼진다.<br>물러나다 다른 상자에 부딪혔다. 위 상자가 떨어져 어깨를 쳤다.`,
      win:{ exp:18, dream:3, spirit:6 }, lose:{ hp:-22, mind:-14 } },
    { l:'② 내공을 실어 봉인은 두고 상자째 옮겨 뒤의 쪽문을 연다.', k:'steady', dc:21, cost:{ qi:24 },
      ok:`상자 밑에 손을 넣었다. 내공을 손바닥과 허리로 나눠 실었다. 들었다. 사람 무게다.<br><br>봉인은 그대로 두고 상자를 옆으로 옮겼다. 그 뒤에 쪽문이 있다. 상자가 문을 막고 있었다. 짐이 아니라 문지기였다.<br>쪽문을 열었다. 나가기 전에 상자를 제자리에 돌려놓았다. 남의 짐은 놓인 자리가 있다. 상자 안에서 아주 작게 두드리는 소리가 났다. 고맙다는 박자였는지는 모른다.`,
      ng:`드는데 상자 안 무게가 한쪽으로 쏠린다. 스스로.<br><br>상자가 기운다. 손을 빼려는데 모서리가 손등을 누른다. 손등뼈가 울렸다.<br>겨우 내려놓았다. 봉인이 안쪽에서 찢어지는 소리가 났다. 쪽문으로 뛰었다. 등 뒤에서 상자 뚜껑이 들썩였다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-26, spirit:-13 } }
  ] },

{ at:'B1', t:'냉동 창고 — 얼음 활송로',
  x:`얼음 활송로가 아래층으로 이어진다. 얼음 덩이를 내려보내는 미끄럼길이다. 끝에 분쇄기가 있다. 지금은 멈췄다.<br><br>
    계단은 노란 비옷들이 막았다. 내려갈 길은 이것뿐이다.<br>
    활송로는 빠르다. 끝에서 못 멈추면 분쇄기 입에 들어간다. 누군가 끝에서 받아야 한다.<br><br>
    분쇄기 스위치 옆 시계가 한 시 오십 분이다. 두 시에 돈다고 적혀 있다.`,
  o:[
    { l:'① 먼저 내려가 분쇄기 앞에서 내공으로 버티며 한 사람씩 받아 낸다.', k:'steady', dc:21, cost:{ qi:26 },
      ok:`먼저 내려갔다. 발을 활송로 양 벽에 대고 속도를 죽였다. 분쇄기 입 한 뼘 앞에서 멈췄다.<br><br>분쇄기 앞에 버티고 섰다. 내공을 다리로 내렸다. 내려오는 사람마다 가슴으로 받았다. 하나, 둘, 셋, 넷. 넷째는 무거워서 둘이 같이 미끄러졌다. 분쇄기 날 끝에 신발 코가 닿았다.<br>한 시 오십구 분. 다섯이 분쇄기 앞을 빠져나왔다. 등 뒤에서 분쇄기가 돌기 시작했다.`,
      ng:`내려가다 속도를 못 죽였다. 분쇄기 입 안으로 다리가 들어갔다.<br><br>날 사이에 발목이 끼었다. 분쇄기는 아직 안 돈다. 한 시 오십칠 분. 내려온 팀원이 이쪽을 끌어냈다. 발목 살이 날에 긁혔다.<br>나머지는 서로를 받으며 내려왔다. 이쪽은 그걸 기어서 봤다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-30, mind:-12 } },
    { l:'② 활송로를 버리고 짐꾼이 쓰던 화물 승강기를 찾는다.', k:'sense', dc:21,
      ok:`활송로는 짐이 가는 길이다. 짐 길 옆에는 늘 짐꾼 길이 있다.<br><br>활송로 옆 벽을 따라갔다. 쇠문이 하나 있다. 화물 승강기. 하역부들이 쓰던 것이다. 단추를 누르니 아래에서 줄 감기는 소리가 난다.<br>비옷들은 계단만 봤다. 짐꾼 길은 짐꾼만 안다. 승강기 안에 말린 고기 한 묶음이 걸려 있다. 하역부가 숨겨 둔 새참이다. 한 점만 꺼내고 나머지는 두었다.`,
      ng:`쇠문을 찾았는데 잠겼다. 돌아오는 사이 비옷들이 계단을 내려오기 시작했다.<br><br>결국 활송로로 뛰어들었다. 끝에서 아무도 안 받았다. 다섯이 다 분쇄기 앞 얼음 더미에 처박혔다.<br>분쇄기는 안 돌았다. 한 시 오십팔 분이었다. 얼음에 부딪힌 갈비뼈가 숨 쉴 때마다 울렸다.`,
      win:{ exp:18, dream:2, item:'말린 고기' }, lose:{ hp:-28, mind:-13 } }
  ] },

{ at:'B1', t:'경매장 하역장 — 짐칸에 실리는 자루',
  x:`하역장에 트럭 한 대가 후진해 들어온다. 짐칸 문이 열렸다.<br><br>
    노란 비옷들이 자루를 싣는다. 자루마다 꼬리표가 달렸다. 하나가 움직인다. 그 꼬리표에 적힌 번호가 이쪽 팀 번호다. 팀원 하나가 안 보인다.<br>
    짐칸 문이 닫히면 트럭은 해무호로 간다.<br><br>
    짐은 꼬리표대로 간다. 사람이든 짐이든.`,
  o:[
    { l:'① 비옷 하나를 걸치고 줄에 끼어 꼬리표를 바꿔 단다.', k:'luck', dc:21,
      ok:`벗어 걸어 둔 노란 비옷을 걸쳤다. 자루 싣는 줄에 끼었다.<br><br>움직이는 자루 꼬리표를 떼어 빈 자루에 달았다. 빈 자루 꼬리표를 움직이는 자루에. 빈 자루 꼬리표에는 반품이라고 적혀 있다.<br>비옷들이 꼬리표를 읽는다. 빈 자루는 싣고 움직이는 자루는 구석에 던졌다. 반품이니까. 짐칸 문이 닫혔다. 구석에서 자루를 풀었다. 팀원이 눈을 깜박였다.`,
      ng:`꼬리표를 바꾸는데 비옷 하나가 이쪽 손을 본다. 고무장갑이 없는 손이다.<br><br>비옷 자락이 잡혔다. 뿌리치며 움직이는 자루를 끌어안고 뛰었다. 짐칸 문에 무릎을 찧었다.<br>자루째 굴러 하역장 밖 빗속으로 나왔다. 찢어진 무릎에서 흐른 피가 빗물에 섞였다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-26, mind:-13 } },
    { l:'② 내공을 끌어올려 닫히는 짐칸 문을 붙들고 자루를 끌어낸다.', k:'break', dc:21, cost:{ qi:25 },
      ok:`짐칸 문이 내려온다. 문 밑에 한 손을 넣고 내공을 끌어올렸다. 문이 멈춘다. 다른 손으로 움직이는 자루를 잡아당겼다.<br><br>자루가 짐칸에서 미끄러져 나온다. 비옷들이 돌아본다. 문을 놓지 않았다. 놓으면 자루가 다시 끼인다. 자루가 다 빠져나온 뒤에야 놓았다. 문이 쾅 닫혔다.<br>자루를 메고 하역장을 빠져나왔다. 무거운 건 문이었다. 자루는 가벼웠다.<br><br>짐을 끌어내는 손과 문을 붙드는 손을 나눠 쓰는 법. 한 몸으로 두 짐을 진 셈이다. 내공이 두 손으로 갈라져 흐르는 길이 하나 났다.`,
      ng:`문을 붙들었는데 짐칸 안 자루들이 무너져 문 쪽으로 쏟아진다.<br><br>문과 자루 사이에 팔이 끼었다. 팔꿈치가 꺾일 듯하다. 팀원 자루를 겨우 잡아 뺐다. 팔을 빼는 데 살갗이 한 겹 남았다.<br>비옷들이 뛰어온다. 자루를 끌고 굴렀다. 둘이 빗물 고랑에 처박혔다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-28, spirit:-13 }, wake:1 }
  ] },

{ at:'B1', t:'해무호 선착장 — 선체와 부두 사이',
  x:`해무호 옆구리에 판자가 걸쳐졌다. 부두에서 갑판까지. 한 사람 폭.<br><br>
    배가 파도에 흔들린다. 선체가 부두에서 떨어질 때마다 판자 밑이 벌어진다. 붙을 때마다 그 사이가 닫힌다. 쇠와 콘크리트가 닫힌다.<br>
    넷이 건넜다. 마지막 하나가 다리를 다쳤다. 혼자 못 건넌다.<br><br>
    표사가 그 사람을 업었다.`,
  o:[
    { l:'① 업고 판자를 건넌다.', k:'bond', dc:22,
      doom:{ title:'선체와 부두', what:'선체와 부두 사이에 끼었습니다', dc:18, sec:45,
        text:`업고 판자에 올랐다. 한 걸음. 두 걸음. 배가 떨어진다. 판자가 기운다.<br><br>세 걸음째에 판자 끝이 부두에서 미끄러졌다. 업은 사람을 앞으로 던졌다. 갑판 위 팀원들이 받았다.<br>이쪽은 판자와 같이 떨어졌다. 선체와 부두 사이 물로. 위를 보니 배가 다시 다가온다. 쇠 옆구리가 콘크리트 쪽으로.<br><br>짐은 넘겼다. 짐꾼은 아직 사이에 있다.`,
        dieText:`업혔던 사람은 던져진 그대로 갑판에 닿았다.<br><br>배가 부두에 붙었다가 떨어졌다. 다시 붙었다. 파도는 그걸 새벽까지 했다.<br>갑판 위 다섯은 부두 쪽을 오래 내려다봤다. 받은 짐은 끝까지 데려다주었다. 데려다준 사람만 못 왔다.` },
      ok:`업고 판자에 올랐다. 배가 떨어질 때는 섰다. 붙을 때 걸었다. 등에 업힌 사람이 파도 박자를 숨으로 세어 줬다.<br><br>세 걸음째에 판자가 크게 기울었다. 무릎을 낮추고 버텼다. 판자가 다시 평평해질 때까지. 붙는 박자에 마지막 두 걸음.<br>갑판에 발이 닿았다. 업은 사람을 내려놓았다. 등 뒤에서 판자가 부두와 선체 사이로 떨어져 부서지는 소리가 났다.`,
      win:{ exp:25, dream:4 } },
    { l:'② 업은 사람을 허리끈으로 묶고 계류줄을 타고 건넌다.', k:'evade', dc:21,
      ok:`업은 사람을 허리끈으로 이쪽 몸에 묶었다. 판자 말고 계류줄을 잡았다. 줄은 배와 같이 움직인다. 판자처럼 미끄러지지 않는다.<br><br>줄을 타고 배 옆구리로 건너갔다. 선체가 부두에 붙을 때 이쪽은 이미 선체 바깥쪽에 매달려 있었다. 붙는 쪽이 아니라.<br>갑판 난간을 넘었다. 팀원들이 끌어올렸다. 손바닥이 젖은 밧줄에 다 쓸렸다.`,
      ng:`줄을 잡았는데 업은 사람 무게에 줄이 처진다. 둘이 물에 닿았다.<br><br>찬물이 허리까지 오른다. 선체 쪽으로 쓸린다. 줄을 놓지 않고 끌어당겼다. 갑판 위 넷이 같이 당겼다.<br>난간을 넘었을 때 둘 다 바닷물을 토했다. 업은 사람 다리가 더 부었다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-28, mind:-13 } }
  ] },

{ at:'B2', t:'휴게실 — 종이학 꾸러미',
  x:`휴게실 창가 노인이 종이학을 실에 꿰었다. 스무 마리.<br><br>
    노인이 그걸 이쪽에 내민다. 밖에 가지고 나가 달라고 한다. 아무 데나 비 오는 데 걸어 달라고.<br>
    학마다 날개 안쪽에 글씨가 있다. 이름이다. 스무 개. 노인 이름은 없다.<br><br>
    짐은 받으면 끝까지 간다. 종이는 비에 약하다.`,
  o:[
    { l:'① 꾸러미를 받아 젖지 않게 품 안쪽에 넣는다.', k:'bond', dc:21,
      ok:`받았다. 약 봉투 하나를 펴서 학 꾸러미를 쌌다. 그 위를 기름종이로 한 번 더. 품 안쪽, 심장 쪽에 넣었다.<br><br>노인이 고개를 끄덕인다. 받는 손을 보면 안다. 끝까지 갈 손인지.<br>계단에서 두 번 넘어질 뻔했다. 두 번 다 품을 감싸고 떨어졌다. 팔꿈치가 깨졌다. 학은 하나도 안 구겨졌다.<br><br>무게 없는 짐을 처음 졌다. 가볍다고 덜 지키는 게 아니다. 가벼운 짐일수록 몸 안쪽에 둔다. 품는 자리가 하나 새로 생겼다.`,
      ng:`품에 넣는데 복도에서 딸깍 소리가 다가온다. 서두르다 학 하나가 꾸러미에서 빠졌다.<br><br>주우려는데 간호사 발이 그 위에 선다. 하얀 신발. 학이 신발 밑에서 납작해진다.<br>노인이 이쪽을 본다. 탓하지 않는다. 그게 더 무겁다. 열아홉 마리를 품고 나왔다.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-16, spirit:-16 }, wake:1 },
    { l:'② 학은 두고 날개의 이름을 다 외워 가겠다고 한다.', k:'gaze', dc:21,
      ok:`학은 노인에게 두었다. 날개를 하나씩 펴 이름을 읽었다. 스무 개. 외웠다.<br><br>노인이 묻는다. 왜 학은 안 가져가냐고. 종이는 젖으면 지워진다고 했다. 외운 건 안 젖는다.<br>노인이 스물한 번째 학을 접는다. 자기 이름을 쓴다. 그것도 외워 달라고. 외웠다. 짐이 하나 늘었다. 몸 안쪽에.`,
      ng:`읽다가 이름 하나에서 눈이 멈춘다. 이쪽 이름이다. 이쪽 글씨체로.<br><br>노인이 그 학을 빼서 이쪽 손에 쥐여 준다. 이건 가지고 가라고. 여기 두면 안 된다고.<br>손이 떨렸다. 학을 접었다 폈다 몇 번이나 했다. 그 이름을 누가 언제 썼는지 아무도 모른다.`,
      win:{ exp:18, dream:2, mind:6 }, lose:{ mind:-17, spirit:-15 } }
  ] },

{ at:'B2', t:'세탁실 — 시트 수레',
  x:`세탁실에 시트 수레가 줄지어 있다. 바퀴 달린 큰 바구니. 위를 흰 천으로 덮었다.<br><br>
    수레는 3층 복도를 지나 화물 승강기까지 간다. 간호사들은 수레를 안 센다. 사람만 센다.<br>
    넷이 수레 하나에 들어갈 수 있다. 웅크리면.<br><br>
    수레를 미는 사람은 하나다. 그 사람은 보인다.`,
  o:[
    { l:'① 넷을 싣고 시트를 덮어 짐처럼 천천히 밀고 지나간다.', k:'steady', dc:21,
      ok:`넷을 웅크리게 하고 시트를 덮었다. 접힌 모서리까지 맞췄다. 걸려 있던 직원 가운을 걸쳤다. 수레를 밀었다.<br><br>복도에서 간호사 셋이 지나간다. 수레를 본다. 수레 미는 사람을 본다. 딸깍. 한 번. 하나가 지나간다. 수레는 안 센다.<br>화물 승강기 앞에서 시트를 들추자 넷이 숨을 몰아쉰다. 짐은 짐처럼 밀어야 짐으로 보인다. 서두르면 사람으로 보인다.`,
      ng:`밀고 가는데 바퀴 하나가 끽끽 운다. 네 사람 무게다.<br><br>간호사 하나가 멈춰 선다. 시트 위에 손을 얹고 눌러 본다. 아래에서 누가 숨을 들이켰다.<br>수레를 밀고 뛰었다. 승강기 문에 부딪혀 둘이 굴러 나왔다. 하나가 바닥에 머리를 찧었다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-24, mind:-14 } },
    { l:'② 내공을 손에 모아 수레를 띄우듯 밀어 바퀴 소리를 죽인다.', k:'steady', dc:21, cost:{ qi:24 },
      ok:`손잡이를 쥐고 내공을 손바닥으로 내렸다. 수레를 아주 조금 들어 올리듯 밀었다. 바퀴에 실리는 무게가 빈 수레만큼 됐다.<br><br>바퀴가 조용하다. 빈 수레 소리다. 간호사들이 지나가며 수레를 안 본다. 빈 수레는 아무도 안 본다.<br>승강기 앞에서 손을 놓았다. 그제야 바퀴가 끽 하고 운다. 네 사람 무게로. 승강기 문이 닫힌 뒤였다.`,
      ng:`띄우듯 밀다 내공이 끊겼다. 수레가 쿵 하고 내려앉는다.<br><br>복도 끝 간호사들이 돌아본다. 시트가 들썩였다. 아래 사람들이 놀라 움직였다.<br>수레를 버리고 다들 뛰었다. 세탁실로 되돌아가 투입구로 미끄러져 내려갔다. 팔꿈치가 쇠벽에 갈렸다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-26, mind:-12 } }
  ] },

{ at:'B2', t:'중앙 계단 — 세는 것들 사이',
  x:`2층 중앙 계단 양옆에 사람들이 서 있다. 한 칸에 하나씩. 다 고개를 숙이고 입술로 숫자를 센다.<br><br>
    지나가는 사람을 센다. 다 세고 나면 맨 끝에 지나간 사람을 붙잡는다고 들었다.<br>
    다친 팀원이 하나 있다. 제일 느리다. 맨 끝이 될 것이다.<br><br>
    짐은 가운데 둔다. 맨 끝에 두지 않는다.`,
  o:[
    { l:'① 다친 팀원을 가운데 두고 한 덩어리로 내려간다.', k:'bond', dc:22,
      doom:{ title:'맨 끝', what:'세는 것들에게 붙잡혀 끌려갑니다', dc:18, sec:50,
        text:`다친 팀원을 가운데 세웠다. 셋이 둘러쌌다. 이쪽은 맨 뒤에 섰다. 한 덩어리로 계단을 내려갔다.<br><br>양옆 입술이 센다. 하나. 덩어리가 하나로 세어진다. 됐다. 그런데 마지막 칸에서 덩어리가 계단참으로 풀린다. 넷이 먼저 내려선다. 맨 뒤 이쪽이 한 칸 늦다.<br>마지막 칸 옆에 선 것이 고개를 든다. 맨 끝에 지나간 사람을 본다. 손이 이쪽 소매를 잡는다.<br><br>둘. 하나가 둘로 세어졌다. 둘째가 끌려간다.`,
        dieText:`넷은 계단참에서 돌아봤다. 계단 양옆이 다시 고개를 숙이고 있다. 한 칸에 하나씩.<br><br>마지막 칸에 하나가 늘었다.<br>표사는 짐을 맨 끝에 두지 않았다. 맨 끝에는 표사가 섰다.` },
      ok:`다친 팀원을 가운데 세웠다. 셋이 둘러쌌다. 이쪽은 맨 뒤에 섰다. 한 덩어리로 계단을 내려갔다.<br><br>양옆 입술이 센다. 하나. 덩어리가 하나로 세어진다. 마지막 칸에서 이쪽이 앞의 넷 등을 두 팔로 감쌌다. 덩어리가 안 풀리게. 다섯이 한 걸음에 계단참으로 내려섰다.<br>맨 끝이 없었다. 한 덩어리에는 끝이 없다. 양옆이 한참 입술만 움직이다가 다시 하나부터 세기 시작했다.`,
      win:{ exp:25, dream:4 } },
    { l:'② 이쪽이 다친 팀원과 걸음을 겹쳐 맨 끝을 둘로 만든다.', k:'luck', dc:21,
      ok:`다친 팀원 옆에 붙었다. 발을 그 발에 맞췄다. 한 걸음에 두 발이 같이 내려간다.<br><br>셋, 넷, 다섯. 앞이 다 세어졌다. 마지막 칸에 둘이 같이 내려섰다. 같은 박자로.<br>세는 것들이 고개를 든다. 맨 끝이 둘이다. 누구를 붙잡을지 모른다. 그 망설임 사이에 둘이 계단참에 내려섰다. 끝을 둘로 나누면 끝이 흐려진다.`,
      ng:`걸음을 맞추는데 다친 팀원이 한 박자 늦는다. 아프다.<br><br>마지막 칸에 그 팀원이 혼자 남았다. 손이 그 팀원 머리채를 잡았다. 그 손목을 쳤다.<br>머리카락 한 움큼이 남았다. 팀원은 계단참에서 한참 떨었다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-24, spirit:-15 } }
  ] },

{ at:'B2', t:'1층 정문 — 거꾸로 도는 회전문',
  x:`1층 정문은 회전문이다. 문이 돈다. 거꾸로. 밖에서 안으로.<br><br>
    한 칸에 사람 둘. 칸은 넷. 나가려면 도는 쪽을 거슬러 밀어야 한다.<br>
    당직 의자가 비었다. 당직이 어딘가 갔다. 곧 돌아온다.<br><br>
    회전문 유리에 빗물이 흐른다. 밖이 바로 저기다.`,
  o:[
    { l:'① 내공을 끌어올려 회전문을 거슬러 밀며 한 칸씩 내보낸다.', k:'steady', dc:22, cost:{ qi:28 },
      ok:`회전문 날개를 어깨로 받쳤다. 내공을 끌어올려 밀었다. 거꾸로 돌던 문이 멈춘다. 그리고 천천히 바로 돈다.<br><br>첫 칸에 둘을 넣고 밀었다. 둘이 빗속으로 나갔다. 둘째 칸에 둘. 밀었다. 셋째 칸에 이쪽 혼자. 문이 다시 거꾸로 돌려 한다. 이를 악물고 밀었다.<br>빗속에 나왔다. 등 뒤에서 회전문이 다시 거꾸로 돈다. 빈 칸들이 안쪽으로 들어간다. 차다. 찬 게 반갑다.`,
      ng:`밀었는데 문이 멈추기만 하고 안 돈다. 거꾸로 미는 힘이 사람보다 세다.<br><br>첫 칸에 넣은 둘이 칸 안에 갇혔다. 유리에 손을 대고 이쪽을 본다. 내공을 한 번 더 끌어올렸다. 문이 한 칸 돌았다.<br>나머지는 당직이 돌아오기 직전에 겨우 나왔다. 어깨가 빠진 것처럼 덜렁거렸다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-28, mind:-12 } },
    { l:'② 칸마다 힘센 사람과 지친 사람을 짝지어 넣는다.', k:'bond', dc:21,
      ok:`짝을 지었다. 힘센 사람과 지친 사람. 한 칸에 둘. 힘센 쪽이 날개를 밀고 지친 쪽은 그 허리를 잡는다.<br><br>칸마다 짐 하나에 짐꾼 하나다. 첫 칸이 나갔다. 둘째 칸이 나갔다. 이쪽은 마지막 칸에 혼자 들어갔다. 밖의 넷이 유리에 손을 대고 같이 밀었다. 안팎에서.<br>회전문이 바로 돌았다. 빗속에 나왔다.<br><br>사람마다 짐꾼을 하나씩 붙여 짐을 나누는 법. 혼자 다 지던 버릇이 짝을 짓는 버릇으로 바뀌었다. 손이 사람을 둘씩 묶어 센다.`,
      ng:`짝을 짓는데 다섯이 홀수다. 지친 사람 하나가 남는다.<br><br>그 사람을 이쪽 칸에 넣었다. 둘이 밀었다. 문이 무겁다. 칸 안에서 숨이 막힌다. 유리에 김이 서려 밖이 안 보인다.<br>겨우 빠져나왔다. 칸 안에서 부딪힌 이마에 혹이 났다. 등 뒤에서 당직 의자에 누가 앉는 소리가 났다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-24, spirit:-14 }, wake:1 }
  ] },

{ at:'B3', t:'8호차 — 이름이 적힌 짐표',
  x:`8호차 짐칸 선반에 가방이 줄지어 있다. 손잡이마다 짐표가 달렸다. 행선지와 이름.<br><br>
    한 가방 짐표에 팀원 이름이 적혀 있다. 행선지는 종착. 팀원은 가방을 맡긴 적이 없다.<br>
    가방이 무겁다. 아주 조금 따뜻하다.<br><br>
    짐표를 보면 짐보다 짐표를 먼저 의심한다.`,
  o:[
    { l:'① 짐표를 떼어 아무도 안 찾는 낡은 가방에 옮겨 단다.', k:'luck', dc:21,
      ok:`짐표를 손톱으로 떼었다. 선반 맨 끝 낡은 가방에 달았다. 이름 없는 가방이다. 먼지가 쌓였다.<br><br>그날 밤 검표원이 지나가며 선반을 훑는다. 그 이름 짐표 앞에서 멈춘다. 낡은 가방을 들고 간다. 끝 문 쪽으로.<br>팀원이 그 뒷모습을 본다. 얼굴이 하얗다. 원래 가방은 선반에 그대로 있다. 따뜻한 기가 빠졌다. 그냥 짐이 됐다.`,
      ng:`떼는데 짐표 끈이 팀원 손목으로 이어져 있다. 눈에 안 보이게 가는 끈이다.<br><br>짐표를 떼자 팀원이 비명을 지른다. 손목에 붉은 줄이 났다.<br>칼로 끈을 끊었다. 팀원 손목에서 피가 났다. 짐표는 선반 위에서 저절로 뒤집혀 이번엔 이쪽 이름을 보였다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-22, mind:-16 } },
    { l:'② 가방을 열지 않고 들어 무게가 쏠리는 쪽을 잰다.', k:'gaze', dc:20,
      ok:`가방을 들었다. 열지 않았다. 짐표가 거짓이어도 짐은 남의 짐이다.<br><br>무게가 바닥 쪽으로 쏠린다. 그리고 쏠림이 움직인다. 이쪽이 든 손 쪽으로. 무게가 사람을 찾는다.<br>가방을 선반에 도로 올리고 손잡이를 쇠막대에 허리끈으로 묶었다. 단단히. 그 가방은 종착까지 그 자리에서 이쪽 쪽으로 기울어 있었다.`,
      ng:`드는데 가방이 팔에 매달린다. 놓아도 안 떨어진다.<br><br>손잡이가 손가락에 감겨 있다. 가죽이 아니라 손가락 같은 것이다. 팀원들이 같이 당겨 떼어 냈다.<br>손가락 마디가 다 저렸다. 가방은 선반에 떨어져 조용해졌다.`,
      win:{ exp:18, dream:2, spirit:6 }, lose:{ hp:-24, spirit:-14 } }
  ] },

{ at:'B3', t:'특실 3호실 — 두드리는 트렁크',
  x:`특실 3호실 바닥에 가죽 트렁크가 놓여 있다. 쇠 자물쇠가 셋. 안에서 두드린다. 약하게.<br><br>
    손잡이에 꼬리표가 달렸다. 『취급 주의 — 종착에서 열 것』.<br>
    남의 봉인은 함부로 안 뜯는다. 그런데 안에서 두드리는 건 짐이 아니라 사람일지도 모른다.<br><br>
    복도에서 한 박자 늦은 발소리가 다가온다.`,
  o:[
    { l:'① 내공을 끌어올려 트렁크째 들고 이 칸을 빠져나간다.', k:'steady', dc:21, cost:{ qi:26 },
      ok:`트렁크를 들었다. 사람 무게다. 내공을 허리로 모아 어깨에 올렸다.<br><br>안의 두드림이 멈춘다. 들린 걸 안다. 복도 발소리를 피해 반대쪽 연결부로 갔다. 두 칸을 지나 화장실 앞에 내려놓았다. 거기서 자물쇠 셋을 칼끝으로 열었다.<br>안에 아이가 웅크리고 있다. 다른 팀 막내다. 숨이 약하다. 이쪽 몫 물을 먹였다.<br><br>봉인을 뜯지 않고 짐째 옮겨서 안전한 데서 연다. 지키는 것과 구하는 것을 둘 다 하는 순서. 어깨가 그 무게를 기억한다.`,
      ng:`드는데 트렁크가 바닥에서 안 떨어진다. 안의 것이 바닥을 붙잡고 있다.<br><br>내공을 더 끌어올렸다. 트렁크가 들리며 바닥 판자가 같이 뜯겼다. 손목이 꺾였다.<br>복도 발소리가 문 앞에 섰다. 트렁크를 놓고 창 쪽으로 물러났다. 문이 열렸다. 아무도 없다. 트렁크 두드림이 이번엔 이쪽 박자로 났다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-28, mind:-12 }, wake:1 },
    { l:'② 자물쇠 하나만 열어 뚜껑 틈으로 안을 확인한다.', k:'fix', dc:21,
      ok:`자물쇠 하나만 열었다. 뚜껑을 손가락 한 마디만 들었다.<br><br>틈으로 눈이 보인다. 사람 눈이다. 겁먹었다. 그런데 틈으로 나오는 숨이 차다. 사람 숨이 아니다. 눈만 사람이다.<br>자물쇠를 다시 잠갔다. 꼬리표대로 종착에서 열 짐이다. 남의 짐을 남의 말대로 두었다. 두드림이 멈췄다. 기다리는 것이 하나 줄었다.`,
      ng:`열자마자 뚜껑이 안에서 확 열린다. 자물쇠 둘이 남았는데도.<br><br>틈으로 손이 나와 손목을 잡는다. 아이 손 크기다. 힘은 어른보다 세다. 뿌리치며 뚜껑을 무릎으로 눌렀다.<br>손이 들어갔다. 손목에 작은 손가락 자국이 다섯 남았다. 복도 발소리가 문 앞에 멈췄다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-22, spirit:-16 } }
  ] },

{ at:'B3', t:'탄수차 — 젖은 석탄 더미',
  x:`탄수차는 석탄 더미다. 기관실로 가려면 그 위를 넘어야 한다. 젖은 석탄이 발밑에서 흘러내린다.<br><br>
    다친 팀원이 혼자 못 넘는다. 업어야 한다.<br>
    더미 꼭대기에 바람이 분다. 터널이 다가온다. 터널 천장은 낮다.<br><br>
    업은 사람 머리가 이쪽 머리보다 높다.`,
  o:[
    { l:'① 업고 낮게 엎드려 석탄 더미를 기어 넘는다.', k:'bond', dc:22,
      doom:{ title:'흘러내리는 석탄', what:'석탄과 함께 쓸려 내려갑니다', dc:18, sec:45,
        text:`업고 엎드렸다. 업힌 사람 머리를 이쪽 등에 눌러 붙였다. 기었다.<br><br>석탄이 무릎 밑에서 흘러내린다. 한 줌, 한 삽, 한 더미. 몸이 같이 미끄러진다. 탄수차 가장자리 쪽으로.<br>업힌 사람을 앞으로 밀었다. 기관실 문 앞 팀원이 그 팔을 잡았다. 받았다.<br><br>이쪽은 석탄과 같이 가장자리를 넘는다. 아래는 빗속 선로다.`,
        dieText:`업혔던 사람은 밀어 올려진 그대로 기관실 문 안에 닿았다.<br><br>탄수차 석탄 더미가 한 자락 낮아졌다. 터널이 그 위를 지나갔다.<br>맡은 짐을 문 앞까지 데려갔다. 문 앞이 끝이었다.` },
      ok:`업고 엎드렸다. 업힌 사람 머리를 이쪽 등에 눌러 붙였다. 기었다.<br><br>석탄이 흘러내릴 때마다 멈췄다. 손을 석탄 깊이 넣어 단단한 덩이를 찾았다. 거기 손을 걸고 또 기었다. 터널이 머리 위를 지나갔다. 천장 쇠가 업힌 사람 등을 스쳤다. 스치기만 했다.<br>기관실 문 앞에 닿았다. 둘 다 얼굴이 새까맣다. 업힌 사람이 귀에 대고 말했다. 짐 같지 않았다고. 같이 기어 온 것 같았다고.`,
      win:{ exp:25, dream:4 } },
    { l:'② 내공을 발바닥에 모아 석탄이 꺼지기 전에 디뎌 건넌다.', k:'evade', dc:21, cost:{ qi:26 },
      ok:`업은 사람을 단단히 고쳐 업었다. 내공을 발바닥에 모았다. 석탄이 꺼지기 전에 다음 발. 수렁 건너는 법이다.<br><br>더미 위를 세 번 디뎌 건넜다. 디딘 자리마다 석탄이 흘러내린다. 발은 이미 다음 자리에 있다.<br>기관실 문 앞에 내려섰다. 등 뒤에서 석탄 더미가 무너지는 소리가 났다. 터널 바람이 그 위를 핥았다.`,
      ng:`세 번째 디딜 때 석탄 밑이 비었다. 발목까지 빠졌다.<br><br>업은 사람 무게로 무릎까지 박혔다. 터널이 온다. 업은 사람은 엎드리게 했고 이쪽은 못 엎드렸다. 터널 천장 쇠가 어깨를 쳤다.<br>터널을 나와서야 빠져나왔다. 어깨가 한참 올라가지 않았다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-30, mind:-12 } }
  ] },

{ at:'B3', t:'기관실 옆 문 — 내리는 순서',
  x:`04:39. 기관실 옆 문이 열렸다. 열차가 느려졌다. 그래도 사람 뛰는 것보다 빠르다.<br><br>
    다섯이 문 앞에 섰다. 한 사람씩 뛰어야 한다. 누가 먼저 뛰는지가 누가 내리는지를 정한다. 마지막은 늦을 수 있다.<br>
    제일 약한 사람이 맨 끝에 서 있다. 스스로 그 자리에 섰다.<br><br>
    표사는 맡은 것을 끝까지 데려간다. 끝은 문 앞이 아니다. 자갈 위다.`,
  o:[
    { l:'① 제일 약한 사람을 안고 같이 뛴다.', k:'bond', dc:22,
      ok:`셋을 먼저 보냈다. 넷째로 이쪽이 섰다. 맨 끝 사람을 앞으로 당겨 안았다. 둘이 같이 뛰었다.<br><br>공중에서 몸을 틀었다. 이쪽 등이 먼저 자갈에 닿게. 안은 사람은 이쪽 가슴 위로 떨어졌다. 둘이 한 덩이로 굴렀다.<br>멈췄다. 안은 사람이 고개를 든다. 다친 데가 없다. 이쪽 등이 자갈에 다 갈렸다.<br><br>맡은 것의 끝을 다시 정했다. 문 앞이 아니라 땅에 닿을 때까지. 짐과 같이 떨어지는 몸은 짐보다 먼저 땅에 닿는다. 등이 그 자리를 외웠다.`,
      ng:`안고 뛰는 순간 열차가 덜컹했다. 발이 문턱에 걸렸다.<br><br>둘이 엇나가게 떨어졌다. 안은 사람이 팔에서 빠져 자갈에 굴렀다. 이쪽은 선로 옆 배수로에 처박혔다.<br>기어 나와 그 사람에게 갔다. 무릎이 찢겼다. 그 사람이 일어나 이쪽을 부축했다. 거꾸로 됐다.`,
      win:{ exp:25, dream:4 }, lose:{ hp:-30, mind:-12 }, wake:1 },
    { l:'② 내공으로 문틀을 붙들고 한 사람씩 등을 밀어 멀리 내보낸다.', k:'steady', dc:21, cost:{ qi:25 },
      ok:`문틀을 한 손으로 쥐었다. 내공을 팔로 모았다. 한 사람씩 등을 밀었다. 열차 밖으로 멀리. 바퀴에서 멀리.<br><br>넷이 자갈 위에 굴렀다. 맨 끝 사람까지. 이쪽이 마지막이다. 문틀을 박차고 뛰었다. 굴렀다.<br>일어나 보니 넷이 다 먼저 일어서 있다. 맨 끝에 섰던 사람이 이쪽 손을 잡아 일으켰다.`,
      ng:`밀다가 맨 끝 사람이 문틀을 붙잡고 안 놓는다. 무섭다고.<br><br>손가락을 하나씩 떼어 냈다. 그 사이 열차가 다시 빨라진다. 그 사람을 안고 같이 뛰었다. 너무 늦게.<br>자갈 위를 한참 굴렀다. 둘 다 팔다리가 갈렸다. 먼저 내린 셋이 빗속을 거슬러 뛰어왔다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-28, spirit:-14 } }
  ] }

]);
